export const CORE = [{"id":2,"cat":"duas-importance","sub":1,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","tr":"Laa ilaaha illallahu wahdahu laa sharika lahu, lahul-mulku wa lahul-hamdu wa huwa 'alaa kulli shay'in qadir. Allaahumma laa maani'a limaa a'taita wa laa mu'tia limaa mana'ta wa laa yanfa'u dhal-jaddi minka al-jaddu","ref":"Bukhari: 844"},{"id":4,"cat":"duas-importance","sub":2,"ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","tr":"Iyyaaka na'budu wa lyyaaka nasta'een","ref":"Surah Al-Fatihah 1:5"},{"id":5,"cat":"duas-importance","sub":2,"ar":"اِهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُّسْتَقِيْمٍ","tr":"Ihdini limakhtulifa fihi minal-haqqi bi'idhnika innaka tahdi man tasha'u ila siratim mustaqim","ref":"Muslim: 770"},{"id":6,"cat":"duas-importance","sub":2,"ar":"اَللَّهُمَّ أَعِنِّيْ عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","tr":"Allaahumma 'a'innee 'alaa thikrika, wa shukrika, wahusni 'ibaadatik","ref":"Sahih (Albani). Abu Dawud: 1522"},{"id":7,"cat":"duas-importance","sub":2,"ar":"وَاهْدِنِيْ لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِيْ لِأَحْسَنِهَا إِلَّا أَنْتَ وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ","tr":"Wahdini li ahsanil-akhlaaqi, la yahdi li ahsanihaa illa anta wasrif anni sayyi'ahaa laa yasrifu anni sayyi'ahaa illa anta","ref":"Muslim: 771"},{"id":9,"cat":"duas-importance","sub":2,"ar":"اَللَّهُمَّ اهْدِنِيْ فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِيْ فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ","tr":"Allahum-mahdinee feeman hadayta, wa 'aafinee feeman 'aafayta, wa tawallanee feeman tawallayta, wa baarik lee feemaa 'a'atayta, wa qinee sharra maa qadhayta, fa'innaka taqdhee wa laa yuqdhaa 'alayka, 'innahu laa yadhillu man waalayta, wa laa ya 'izzu man 'aadayta, tabaarakta Rabbanaa wa ta'aalayta","ref":"Sahih (Albani). Abu Dawud: 1425"},{"id":11,"cat":"duas-importance","sub":2,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ","tr":"Rabbighfirli wa tub `alayya innaka Antat-Tawwabur-Rahim","ref":"Sahih (Albani). Abu Dawud: 1516"},{"id":12,"cat":"duas-importance","sub":2,"ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَىُّ الْقَيُّوْمُ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfirullaa hal-'Adheemal-ladhee laa 'ilaaha 'illaa Huwal-Hayyul-Qayyoomu wa 'atoobu 'ilayhi","ref":"Sahih (Albani). Tirmidhi: 3577"},{"id":13,"cat":"duas-importance","sub":3,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ","tr":"Allaahumma 'innee 'as'alukal-jannata wa 'a'oodhu bika minan-naar","ref":"Sahih (Albani). Ibn Majah: 910"},{"id":15,"cat":"duas-importance","sub":4,"ar":"اَللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ","tr":"Allaahumma musarrifal-qulubi, sarrif qulubana 'ala ta'atik","ref":"Muslim: 2655"},{"id":16,"cat":"duas-importance","sub":4,"ar":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِيْ عَلَى دِيْنِكَ","tr":"Ya Muqallibal-qulubi, thabbit qalbi 'ala dinik","ref":"Sahih (Albani). Tirmidhi: 3522"},{"id":922,"cat":"duas-importance","sub":4,"ar":"يَا وَلِيَّ الْإِسْلَامِ وَأَهْلِهُ ثَبِّتْنِيْ بِهِ حَتّٰى أَلْقَاكَ.","tr":"Yaa waliyyal islaami wa ahlihu thabbitni bihi hatta alqaaka.","ref":"Proved on the basis of all sanads (Albani). Silsilatus Sahihah 1823"},{"id":17,"cat":"duas-importance","sub":5,"ar":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآَخِرَةِ","tr":"Allaahumma a'hsin ‘aaqibatanaa fil umuri kullihaa wa ajirna min khiz-yid dunya wa ‘adhaabil akhirah","ref":"Sahih (Suyuti). Jami'us Sagir: 1450"},{"id":18,"cat":"duas-importance","sub":6,"ar":"اَللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ","tr":"Allaahumma aslih lee deeni alladhi huwa ‛is-matu amree, Wa aslih lee dun-yaaiallati feeha ma‛aashee, Wa asli lee aakhiratee allati feeha ma‛aadee, Waj-‛alil hayaata ziyaa‛datan lee fee kulli khair waj 'alilmawta raa‛hatan lee min kulli sharr","ref":"Muslim: 2720"},{"id":22,"cat":"duas-excellence","sub":8,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tr":"SubhaanAllahi wa bihamdihi","ref":"Bukhari: 6405"},{"id":23,"cat":"duas-excellence","sub":8,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ","tr":"SubhaanAllahi wa bihamdihi, Subhaanal-laahil-'Adheem","ref":"Bukhari: 6406"},{"id":24,"cat":"duas-excellence","sub":8,"ar":"سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ","tr":"SubhaanAllahi, walhamdu lillaahi, wa Laa 'ilaaha 'illAllahu, wa Allahu 'Akbar","ref":"[1] Muslim: 2137 [2] Muslim: 2695"},{"id":25,"cat":"duas-excellence","sub":8,"ar":"سُبْحَانَ اللَّهِ","tr":"SubhaanAllah","ref":"Muslim: 2698"},{"id":27,"cat":"duas-excellence","sub":8,"ar":"سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ","tr":"SubhaanAllahil-'Adheem wa bihamdihi","ref":"Sahih (Albani). Tirmidhi: 3464"},{"id":28,"cat":"duas-excellence","sub":8,"ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Laa hawla wa laa quwwata 'illaa billaah","ref":"Bukhari: 6384"},{"id":29,"cat":"duas-excellence","sub":8,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَزِيزِ الْحَكِيمِ","tr":"Laa 'ilaaha 'illAllahu wahdahu laa shareeka lahu, Allahu 'Akbar kabeeran, walhamdu lillaahi katheeran, SubhaanAllahi Rabbil-'aalameen, laa hawla wa laa quwwata 'illaa biilaahil-'Azeezil-Hakeem","ref":"Muslim: 2696"},{"id":30,"cat":"duas-excellence","sub":8,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَعَافِنِي وَارْزُقْنِي","tr":"Allaahummaghfir lee, warhamnee, wahdinee, wa 'aafinee warzuqnee","ref":"Muslim: 2697"},{"id":32,"cat":"duas-excellence","sub":8,"ar":"سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"SubhaanAllah, walhamdu lillaah, wa Laa 'ilaaha 'illAllah, wa Allahu 'Akbar, Laa hawla wa laa quwwata 'illaa billaah","ref":"Musnad-e Ahmad (no. 513) (Ahmad Shakir, ed.) and its chain of narration is authentic. See Majma'uz-Zawa'id 1/297. Ibn Hajar mentions it in Bulughul-Maram saying that Ibn Hibban and Al-Hakim considered it authentic."},{"id":36,"cat":"time-of-dua","sub":9,"ar":"إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ١ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ ٢ لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ ٣ تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ ٤ سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ ٥","tr":"Innaaa anzalnaahu fee Lailatil-Qadr. Wa maaa adraaka maa Lailatul-Qadr. Lailatul-Qadri khairum-min alfi shahr. Tanazzalul-malaaa'ikatu war-Roohu feehaa bi-izni Rabbihim min kulli amr. Salaamun hiya hattaa matla'il-fajr.","ref":"Surah Al-Qadr 97:1-5"},{"id":39,"cat":"time-of-dua","sub":9,"ar":"كَانُوا قَلِيلًا مِّنَ اللَّيْلِ مَا يَهْجَعُونَ ١٧ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ ١٨","tr":"Kaanoo qaleelam minal layli maa yahja'oon. Wa bil ashaari hum yastaghfiroon.","ref":"[1] Bukhari: 1145 [2] Surah Az-Zariyat: 51: 17-18"},{"id":45,"cat":"time-of-dua","sub":9,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ اَلْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Laa ilaaha illAllahu Wa'hdahu laa Sharika lahu Lahul mulku, wa lahul-'hamd wa huwa 'alaa kulli shay'in Qadir. Al'hamdulillahi wa sub'hanallahi wa laa ilaaha illAllahu wAllahu akbar wa laa 'hawla Walaa Quwwata illa billaah","ref":"Bukhari: 1154"},{"id":46,"cat":"time-of-dua","sub":9,"ar":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِيْنَ","tr":"Laa 'ilaaha 'illaa 'Anta sub'haanaka 'innee kuntu minadh-dhaalimeen","ref":"Sahih (Albani). Tirmidhi: 3505"},{"id":47,"cat":"time-of-dua","sub":9,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِّنْهَا","tr":"Innaa lillaahi wa 'innaa 'ilayhi raaji'oon, Allaahumma'-jurni fee museebatee wa 'akhliflee khayran minhaa","ref":"Muslim: 918"},{"id":49,"cat":"time-of-dua","sub":9,"ar":"اَللَّهُ أَكْبَرُ كَبِيْرًا وَالْحَمْدُ لِلَّهِ كَثِيْرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيْلًا","tr":"Allahu 'Akbar Kabiran, walhamdu lillaahi kathiran, wa Subhaanallahi bukratan wa'asila","ref":"Muslim: 601"},{"id":50,"cat":"time-of-dua","sub":9,"ar":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيْرًا طَيِّبًا مُبَارَكًا فِيهِ","tr":"Alhamdulillaahi hamdan kathiran tayyiban mubaarakan fih","ref":"Muslim: 600"},{"id":52,"cat":"time-of-dua","sub":9,"ar":"رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيْرًا طَيِّبًا مُبَارَكًا فِيهِ","tr":"Rabbanaa wa lakal-hamd, hamdan katheeran tayyiban mubaarakan feeh","ref":"Bukhari: 799"},{"id":54,"cat":"time-of-dua","sub":9,"ar":"اَللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ","tr":"Allaahumma Rabbanaa wa lakal-hamd","ref":"Bukhari: 796"},{"id":55,"cat":"time-of-dua","sub":9,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","tr":"Allaahumma inni as'aluka ya Allahu bi annakal Wahidul-Ahad us-Samadulla-dhi lam yalid wa lam yowlad, wa lam yakun lahu kufuwan ahad, an taghfirali dhunubi, innaka antal-Ghafurur-Rahim","ref":"Sahih (Albani). Nasai: 1301"},{"id":56,"cat":"time-of-dua","sub":9,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّوْمُ","tr":"Allaahumma inni as'aluka bi-anna lakal-hamdu, laa ilaaha illaa antal-mannanu badi'us-samawaati wal-ardi, yaa dhal-jalaali wal-ikraam! Yaa hayyu yaa qayyum","ref":"Sahih (Albani). Abu Dawud: 1495"},{"id":57,"cat":"time-of-dua","sub":9,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ اَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","tr":"Allaahumma 'innee 'as'aluka bi 'anni 'ash-hadu 'annaka 'AntAllahu laa 'ilaaha 'illaa 'Antal-'Ahadus-Samadul-ladhee lam yalid wa lam yoolad wa lam yakun lahu kufuwan 'Ahad","ref":"Sahih (Albani). Abu Dawud: 1493"},{"id":58,"cat":"time-of-dua","sub":9,"ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","tr":"Ash-hadu an laa ilaaha ill-Allahu wahdahu laa sharika lahu, wa ash hadu anna Muhammadan ‘abduhu wa Rasooluhu","ref":"Muslim: 234"},{"id":59,"cat":"time-of-dua","sub":9,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ","tr":"Laa ilaaha ill-Allahu, wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa huwa ‛alaa kulli shay’in qadeer","ref":"Hasan (Albani). Tirmidhi: 3585"},{"id":68,"cat":"dua-acceptance","sub":10,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيْرٌ. اَلْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Laa ilaaha illAllahu Wa'hdahu laa Sharika lahu Lahul mulku, wa lahul-'hamdu wa huwa 'alaa kulli shay'in Qadir. Alhamdulillah wa subhanallah wa laa ilaaha illAllahu wAllahu akbar wa laa 'hawla Walaa Quwata illa billah","ref":"Bukhari: 1154"},{"id":72,"cat":"dua-acceptance","sub":10,"ar":"لَا إِلَهَ إِلَّآ أَنتَ سُبْحٰنَكَ إِنِّى كُنْتُ مِنَ الظّٰلِمِينَ","tr":"Laa 'ilaaha 'illaa 'Anta subhaanaka 'innee kuntu minadh-dhaalimeen","ref":"Sahih (Albani). Tirmidhi: 3505"},{"id":73,"cat":"dua-acceptance","sub":10,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِّنْهَا","tr":"Innaa lillaahi wa 'innaa 'ilayhi raaji'oon, Allaahumma'-jurni fee museebatee wa 'akhliflee khayran minhaa","ref":"Muslim: 918"},{"id":74,"cat":"dua-acceptance","sub":10,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","tr":"Allaahumma inni as-aluka bi anna ash-hadu annaka antallahu laa ilaaha illaa antal a'hadus samadulladhi lam yalid wa lam yulad wa lam yakun lahu kufuwan a'had","ref":"Sahih (Albani). Nasai: 1300"},{"id":75,"cat":"dua-acceptance","sub":10,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّوْمُ","tr":"Allaahumma inni as'aluka bi-anna lakal-hamda, laa ilaaha illaa antal-mannaanu badi'us-samawaati wal-ardi, yaa dhal-jalaali wal-ikraam! Yaa hayyu yaa qayyum","ref":"Sahih (Albani). Nasai: 1300"},{"id":78,"cat":"morning-and-evening","sub":12,"ar":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ","tr":"Asbahnaa wa 'asbahal-mulku lillaahi walhamdu lillaahi, laa 'ilaaha 'illAllahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa Huwa 'alaa kulli shay'in Qadeer. Rabbi 'as'aluka khayra maa fee haathal-yawmi wa khayra maa ba'dahu wa 'A'oodhu bika min sharri maa fee haathal-yawmi wa sharri maa ba'dahu, Rabbi 'A'oodhu bika minal-kasali, wa soo'il-kibari, Rabbi 'A'oodhu bika min 'athaabin fin-naari wa 'athaabin fil-qabr.","ref":""},{"id":79,"cat":"morning-and-evening","sub":12,"ar":"أَمْسَيْنَا وَأَمْسَا الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ","tr":"Amsaynaa wa'amsal-mulku lillaahi walhamdu lillaahi, laa 'ilaaha 'illAllahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa Huwa 'alaa kulli shay'in Qadeer. Rabbi 'as'aluka khayra maa fee haathihil-laylati wa khayra maa ba'daha wa 'A'oodhu bika min sharri maa fee haathihil-laylati wa sharri maa ba'daha, Rabbi 'A'oodhu bika minal-kasali, wa soo'il-kibari, Rabbi 'A'oodhu bika min 'athaabin fin-naari wa 'athaabin fil-qabr.","ref":"Muslim: 2723"},{"id":80,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ","tr":"Allaahumma bika 'asbahnaa, wa bika 'amsaynaa, wa bika nahyaa, wa bika namootu wa 'ilaykan-nushoor.","ref":""},{"id":81,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ","tr":"Allaahumma bika 'amsaynaa, wa bika 'asbahnaa, wa bika nahyaa, wa bika namootu wa 'ilaykal-maseer.","ref":"Sahih (Albani). Abu Dawud: 5068"},{"id":82,"cat":"morning-and-evening","sub":12,"ar":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ اَللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ فَتْحَهُ وَنَصْرَهُ وَنُورَهُ وَبَرَكَتَهُ وَهُدَاهُ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ","tr":"Asbahnaa wa 'asbahal-mulku lillaahi Rabbil-'aalameen, Allaahumma 'innee 'as'aluka khayra haathal-yawmi, Fathahu wa nasrahu wa noorahu, wa barakatahu, wa hudaahu, wa'A'oodhu bika min sharri maafeehi wa sharri maa ba'dahu.","ref":""},{"id":83,"cat":"morning-and-evening","sub":12,"ar":"أَمْسَيْنَا وَأَمْسَا الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ اللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ :فَتْحَهَا وَنَصْرَهَا وَنُورَهَا وَبَرَكَتَهَا وَهُدَاهَا وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا","tr":"Amsaynaa wa 'amsal-mulku lillaahi Rabbil-'aalameen, Allaahumma 'innee 'as'aluka khayra haadhi hil-laylati, Fathahaa wa nasrahaa wa noorahaa, wa barakatahaa, wa hudaahaa, wa'A'oodhu bika min sharri maa feehaa wa sharri maa ba'dahaa.","ref":"Abu Dawud 4/322, No. 5084"},{"id":84,"cat":"morning-and-evening","sub":12,"ar":"أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ وَعَلَى كَلِمَةِ الْإِخْلَاصِ وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ","tr":"Asbahnaa 'alaa fitratil-'Islaami wa 'alaa kalimatil-'ikhlaasi, wa 'alaa deeni Nabiyyinaa Muhammadin (ﷺ), wa 'alaa millati 'abeenaa 'Ibraaheema, haneefan Musliman wa maa kaana minal-mushrikeen.","ref":""},{"id":85,"cat":"morning-and-evening","sub":12,"ar":"أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ وَعَلَى كَلِمَةِ الْإِخْلَاصِ وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ","tr":"Amsaynaa 'alaa fitratil-'Islaami wa 'alaa kalimatil-'ikhlaasi, wa 'alaa deeni Nabiyyinaa Muhammadin, wa 'alaa millati 'abeenaa 'Ibraaheema, haneefan Musliman wa maa kaana minal-mushrikeen.","ref":"Sahih (Albani). Sahih Al Jame: 4674"},{"id":86,"cat":"morning-and-evening","sub":12,"ar":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfirullaaha wa 'atoobu 'ilayhi.","ref":"Bukhari: 6307, Muslim: 2702"},{"id":87,"cat":"morning-and-evening","sub":12,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَى نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","tr":"SubhaanAllahi wa bihamdihi, 'Adada khalqihi, wa ridhaa nafsihi, wa zinata 'arshihi wa midaada kalimaatihi.","ref":"Muslim: 2726"},{"id":88,"cat":"morning-and-evening","sub":12,"ar":"اَللَّھُمَّ صَلِّ عَلَی مُحَمَّدٍ وَّعَلَی آلِ مُحَمَّدٍ کَمَا صَلَّیْتَ عَلَی اِبْرَاھِیْمَ وَعَلَی آلِ اِبْرَاھِیْمَ اِنَّكَ حَمِیْدٌ مَّجِیْدٌ اَللَّھُمَّ بَارِكْ عَلَی مُحَمَّدٍ وَّعَلَی آلِ مُحَمَّدٍ کَمَا بَارَکْتَ عَلَی اِبْرَاھِیْمَ وَعَلَی آلِ اِبْرَاھِیْمَ اِنَّكَ حَمِیْدٌ مَّجِیْدٌ","tr":"Allaahumma salli 'alaa Muhammadin wa 'alaa 'aali Muhammadin, kamaa sallayta 'alaa 'Ibraaheema wa 'alaa 'aali 'Ibraaheema, 'innaka Hameedun Majeed. Allaahumma baarik 'alaa Muhammadin wa 'alaa 'aali Muhammadin, kamaa baarakta 'alaa 'Ibraaheema wa 'alaa 'aali 'Ibraaheema, 'innaka Hameedun Majeed.","ref":"At-Tabrani, Sahih at-Targhib wa at-Tarhib 1/273"},{"id":89,"cat":"morning-and-evening","sub":12,"ar":"بِسْمِ اللَّهِ الَّذِيْ لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","tr":"Bismillaahil-lathee laa yadhurru ma'as-mihi shay'un fil-'ardhi wa laa fis-samaa'i wa Huwas-Samee 'ul- 'Aleem.","ref":"Sahih (Albani). Abu Dawud: 5088"},{"id":90,"cat":"morning-and-evening","sub":12,"ar":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَاّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ","tr":"HasbiyAllahu laa 'ilaaha 'illaa Huwa 'alayhi tawakkaltu wa Huwa Rabbul-'Arshil-'Adheem.","ref":"Sahih Maquf (Shu'aib and Arnaut). Abu Daud: 5081"},{"id":91,"cat":"morning-and-evening","sub":12,"ar":"يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ أَصْلِحْ لِي شَأْنِيْ كُلَّهُ وَلَا تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ","tr":"Yaa Hayyu yaa Qayyoomu birahmatika 'astagheethu 'aslih lee sha'nee kullahu wa laa takilnee 'ilaa nafsee tarfata 'aynin","ref":"Hasan (Albani). Silsilatul Sahiha: 227"},{"id":92,"cat":"morning-and-evening","sub":12,"ar":"رَضِيْتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِيْنًا وَبِمُحَمَّدٍ نَبِيًّا","tr":"Radheetu billaahi Rabban, wa bil-'Islaami deenan, wa bi-Muhammadin Nabiyyan","ref":"Sahih li ghairihi (Shu’aib al-Arnaut). Takhrijul Musnad: 23112"},{"id":93,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ إِنِّي قَدْ تَصَدَّقْتُ بِعِرْضِي عَلَى عِبَادِكَ","tr":"Allaahumma innii qad tasaddaqtu bi-’irdi ‘ala ‘ibaadik","ref":"Sahih Maktu (Albani). Abu Dawud: 4886"},{"id":95,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ (لَكَ) بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","tr":"Allaahumma 'Anta Rabbee laa 'ilaaha 'illaa 'Anta, khalaqtanee wa 'anaa 'abduka, wa 'anaa 'alaa 'ahdika wa wa'dika mas-tata'tu, 'A'oodhu bika min sharri maa sana'tu, 'aboo'u laka bini'matika 'alayya, wa 'aboo'u (laka) bithanbee faghfir lee fa'innahu laa yaghfiruth-thunooba 'illaa 'Anta.","ref":"Bukhari: 6306"},{"id":96,"cat":"morning-and-evening","sub":12,"ar":"اللَّـهُ لَا إِلَـٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ٢٥٥","tr":"Allahu laa 'ilaaha 'illaa Huwal-Haiyul-Qayyoom, laa ta'khuthuhu sinatun walaa nawm, lahu maa fis-samaawaati wamaa fil-'ardhi, man thal-lathee yashfa'u 'indahu 'illaa bi'ithnihi, ya'lamu maa bayna 'aydeehim wa maa khalfahum, wa laa yuheetoona bishay'im-min 'ilmihi 'illaa bimaa shaa'a, wasi'a kursiyyuhus-samaawaati wal'ardh, wa laa ya'ooduhu hifdhuhumaa, wa Huwal-'Aliyyul- 'Adheem.","ref":"Bukhari: 2311"},{"id":99,"cat":"morning-and-evening","sub":12,"ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ ١٠","tr":"Rabbanaghfir lana wali ikhwanina alladheena sabaqoona bileemani wala taj'aal fee quloobina ghillan lilladheena amanoo rabbana innaka raoofur raheem","ref":"Surah Hashr 59:10"},{"id":100,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ عَافِنِي فِي بَدَنِي اَللَّهُمَّ عَافِنِيْ فِي سَمْعِي اَللَّهُمَّ عَافِنِيْ فِي بَصَرِي لَا إِلَهَ إِلَّا أَنْتَ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allaahumma 'aafinee fee badanee, Allaahumma 'aafinee fee sam'ee, Allaahumma 'aafinee fee basaree, laa 'ilaaha 'illaa 'Anta. Allaahumma 'innee 'A'oodhu bika minal-kufri, wal-faqri, wa 'A'oodhu bika min 'athaabil-qabri, laa 'ilaaha 'illaa 'Anta.","ref":"Hasan (Albani). Abu Dawud: 5090"},{"id":101,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوْءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","tr":"Allaahumma 'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal'ardhi, Rabba kulli shay'in wa maleekahu, 'ash-hadu 'an laa 'ilaaha 'illaa 'Anta, 'A'oodhu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa 'an 'aqtarifa 'alaa nafsee soo'an, 'aw 'ajurrahu 'ilaa Muslim.","ref":"Sahih (Albani). Tirmidhi: 3529"},{"id":102,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ اَللَّهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَوْعَاتِيْ اَللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِيْنِيْ وَعَنْ شِمَالِي وَمِنْ فَوْقِيْ وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ","tr":"Allaahumma 'innee 'as'alukal-'afwa wal'aafiyata fid-dunyaa wal'aakhirah, Allaahumma 'innee 'as'alukal-'afwa wal'aafiyata fee deenee wa dunyaaya wa 'ahlee, wa maalee, Allahum-mastur 'awraatee, wa 'aamin raw'aatee, Allahum-mahfadhnee mim bayni yadayya, wa min khalfee, wa 'an yameenee, wa 'an shimaalee, wa min fawqee, wa 'A'oodhu bi'adhamatika 'an 'ughtaala min tahtee.","ref":"Sahih (Albani). Abu Dawud: 5074"},{"id":103,"cat":"morning-and-evening","sub":12,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ","tr":"Laa 'ilaaha 'illAllahu wa'hdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa 'alaa kulli shay'in Qadeer.","ref":"Bukhari: 3293"},{"id":106,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتِكَ وَجَمِيعَ خَلْقِكَ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","tr":"Allaahumma 'innee 'asbahtu 'ush-hiduka wa 'ush-hidu hamalata 'arshika, wa malaa'ikatika wajamee'a khalqika, 'annaka 'AntAllahu laa 'ilaaha 'illaa 'Anta wahdaka laa shareeka laka, wa 'anna Muhammadan 'abduka wa Rasooluka.","ref":""},{"id":107,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ","tr":"Allaahumma maa 'asbaha bee min ni'matin 'aw bi'ahadin min khalqika faminka wa'hdaka laa shareeka laka, falakal-'hamdu wa lakash-shukru.","ref":""},{"id":108,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا","tr":"Allaahumma 'innee 'as'aluka 'ilman naafi'an, wa rizqan tayyiban, wa 'amalan mutaqabbalan.","ref":"Sahih (Albani). Ibn Majah: 925"},{"id":109,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتِكَ وَجَمِيعَ خَلْقِكَ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","tr":"Allaahumma 'innee 'amsaytu 'ush-hiduka wa 'ush-hidu hamalata 'arshika, wa malaa'ikatika wajamee'a khalqika, 'annaka 'AntAllahu laa 'ilaaha 'illaa 'Anta wahdaka laa shareeka laka, wa 'anna Muhammadan 'abduka wa Rasooluka.","ref":"Hasan (Ibn Baz). Abu Dawud: 5069"},{"id":110,"cat":"morning-and-evening","sub":12,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ وَسُبْحَانَ اللَّهِ الْعَظِيْمِ","tr":"Subhanallahi wa bi'hamdihi wa sub'hanallahil 'adhim","ref":"Bukhari: 6682"},{"id":862,"cat":"morning-and-evening","sub":12,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِيْ أَقَالَنَا يَوْمَنَا هٰذَا وَلَمْ يُهْلِكْنَا بِذُنُوْبِنَا","tr":"Alhamdu lillaahil-ladhi aqaalanaa yawmanaa hadhaa wa-lam yuh-liknaa bi-dhunubinaa","ref":"Muslim: 822"},{"id":864,"cat":"morning-and-evening","sub":12,"ar":"أَسْأَلُ اللَّهَ الْعَافِيَةَ فِيْ الدُّنْيَا وَالْآخِرَةِ","tr":"As’alullaahal ‘aafiyata feed dunyaa wal akhirah.","ref":"Sahih. Tirmidhi: 3514"},{"id":866,"cat":"morning-and-evening","sub":12,"ar":"أَعُوْذُ بِاللَّهِ مِنْ شَرِّ هٰذَا الغَاسِقِ","tr":"A‛oodhu Billahi Min Sharri Haazal Gasiq","ref":"Sahih (Albani). Sahihul Jame' 6918"},{"id":1001,"cat":"morning-and-evening","sub":12,"ar":"اَللَّهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ","tr":"Allaahumma maa 'amsaa bee min ni'matin 'aw bi'ahadin min khalqika faminka wahdaka laa shareeka laka, falakal-hamdu wa lakash-shukru.","ref":"Hasan (Ibn Hajar). Nata'ijul Afkaar: 2/380"},{"id":111,"cat":"morning-and-evening","sub":13,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِيْ وَاهْدِنِيْ وَعَافِنِيْ وَارْزُقْنِيْ","tr":"Allaahummaghfir lee, war'hamnee, wa'hdinee, wa 'aafinee warzuqnee","ref":"Muslim: 2697"},{"id":112,"cat":"morning-and-evening","sub":13,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ بِيَدِهِ الْخَيْرُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tr":"Laa ilaaha illallahu wa'hdahu laa sharika lahu, lahul-mulku wa lahul-'hamdu, yu'hyi wa yumitu, wa Huwa 'hayyun laa yamutu, bi yadihil-khairu, wa Huwa 'ala kulli shay’in Qadir.","ref":"Hasan (Albani). Tirmidhi: 3428"},{"id":113,"cat":"morning-and-evening","sub":13,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ اَلْحَمْدُ لِلَّـهِ الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَل لَّهُ عِوَجًا ۜ ١ قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا ٢ مَّاكِثِينَ فِيهِ أَبَدًا ٣ وَيُنذِرَ الَّذِينَ قَالُوا اتَّخَذَ اللَّـهُ وَلَدًا ٤ مَّا لَهُم بِهِ مِنْ عِلْمٍ وَلَا لِآبَائِهِمْ ۚ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَاهِهِمْ ۚ إِن يَقُولُونَ إِلَّا كَذِبًا ٥ فَلَعَلَّكَ بَاخِعٌ نَّفْسَكَ عَلَىٰ آثَارِهِمْ إِن لَّمْ يُؤْمِنُوا بِهَـٰذَا الْحَدِيثِ أَسَفًا ٦ إِنَّا جَعَلْنَا مَا عَلَى الْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا ٧ وَإِنَّا لَجَاعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا ٨ أَمْ حَسِبْتَ أَنَّ أَصْحَابَ الْكَهْفِ وَالرَّقِيمِ كَانُوا مِنْ آيَاتِنَا عَجَبًا ٩ إِذْ أَوَى الْفِتْيَةُ إِلَى الْكَهْفِ فَقَالُوا رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا ١٠","tr":"Bismillaahir-Rahmaanir-Raheem. Alhamdu lillaahillazeee anzala 'alaa 'abdikhil-kitaaba wa lam yaj'al-lahoo 'iwajaa. Qayyimal-liyunzira ba'san shadeedam-mil-ladunhu wa yubashshiral-mu'mineenal-lazeena ya'maloonas-saalihaati anna lahum ajran hasanaa. Maakitheena feehi abadaa. Wa yunziral-lazeena qaalut-takhazallaahu waladaa. Maa lahum bihee min 'ilmin wa laa li-aabaaa'ihim; kaburat kalimatan takhruju min afwaahihim; in yaqooloona illaa kazibaa. Fala'allaka baakhi'un-nafsaka 'alaa aathaarihim in lam yu'minoo bihaazal-hadeethi asafaa. Innaa ja'alnaa maa 'alal-ardi zeenatal-lahaa linabluwahum ayyuhum ahsanu 'amalaa. Wa innaa lajaa'iloona maa 'alayhaa sa'eedan juruzaa. Am hasibta anna Ashaabal-Kahfi war-Raqeemi kaanoo min aayaatinaa 'ajabaa. Iz awal-fityatu ilal-Kahfi faqaaloo Rabbanaa aatinaa mil-ladunka rahmatan wa hayyi' lanaa min amrinaa rashadaa.","ref":"Muslim: 809"},{"id":114,"cat":"morning-and-evening","sub":13,"ar":"أُعِيذُكُمَا [أَعُوْذُ] بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tr":"Oo-'idhukumaa (For self: A'ooudhu) bi kalimaat-illaahit-taammati min kulli shaytaanin wa haammah, wa min kulli ‛aynin laammah","ref":"Bukhari: 3371"},{"id":863,"cat":"morning-and-evening","sub":13,"ar":"اَللَّهُمَّ اِنَّا نَعُوْذُ بِكَ اَنْ نَرْجِعَ عَلٰى أَعْقَابِنَا أَوْ نُفْتَنَ عَنْ دِيْنِنَا.","tr":"Allaahumma inna nau’dhu bika an narji’ya ‘alaa a’qaabinaa aw nuftana an dininaa.","ref":"Bukhari: 6593"},{"id":865,"cat":"morning-and-evening","sub":13,"ar":"اَللَّهُمَّ إِنِّي أَسْتَهْدِيكَ لِأَرْشَدِ أَمْرِي وَأَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ","tr":"Allahumma inni astahdika li-arshadi amri, wa ‘auzubika min sharri nafsi","ref":"Sahih (Albani). Sahih Al-Mawarid 2059"},{"id":867,"cat":"morning-and-evening","sub":13,"ar":"اَللَّهُمَّ قِنِيْ شَرَّ نَفْسِيْ وَاعْزِمْ لِيْ عَلٰى أَرْشَدِ أَمْرِيْ اَللَّهُمَّ اغْفِرْ لِيْ مَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَخْطَأْتُ وَمَا عَمَدْتُّ وَمَا جَهِلْتُ.","tr":"Allaahumma qini sharra nafsi, wa’jim lee alaa arshadi amri, Allaahummaghfir lee maa as’rartu wa maa a’lantu wa maa akhta’tu wa maa amadtu wa maa jahiltu.","ref":"Sahih (Shuaib al-Arnaut). Musnad Ahmad 19992"},{"id":116,"cat":"sleep","sub":14,"ar":"اَللَّهُ لَآ إِلٰهَ إِلَّا هُوَ الْحَىُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى السَّمٰوٰتِ وَمَا فِى الْأَرْضِ ۗ مَنْ ذَا الَّذِى يَشْفَعُ عِنْدَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ الْعَلِىُّ الْعَظِيمُ","tr":"Allahu laa 'ilaaha 'illaa Huwal-Hayyul-Qayyoom, laa ta'khudhuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-'ardh, man dhal-ladhee yashfa'u 'indahu 'illaa bi'idh nih, ya'lamu maa bayna 'aydeehim wa maa khalfahum, wa laa yuheetoona bishay'im-min 'ilmihi 'illaa bimaa shaa'a, wasi'a kursiyyuhus-samaawaati wal'ardh, wa laa ya'ooduhu hifdhuhumaa, wa Huwal-'Aliyyul- 'Adheem","ref":"Al-Bukhari, Fathul Bari 4/487, no. 2311"},{"id":117,"cat":"sleep","sub":14,"ar":"آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّـهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ٢٨٥ لَا يُكَلِّفُ اللَّـهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ٢٨٦","tr":"(285) Aamanar-Rasoolu bimaa 'unzila ilayhi mir-Rabbihi wal mu'minoon, kullun 'aamana billaahi wa malaa'ikatihi wa Kutubihi wa Rusulih, laa nufarriqu bayna 'ahadim-mir-Rusulih, wa qaaloo sami'naa wa 'ata'naa ghufraanaka Rabbanaa wa 'ilaykal-maseer. (286) Laa yukallifullaahu nafsan 'illaa wus'ahaa, lahaa maa kasabat wa 'alayhaa mak-tasabat, Rabbanaa laa tu'aakhidhnaa 'in naseenaa 'aw 'akhta'naa, Rabbanaa wa laa ta'hmil 'alaynaa 'isran kamaa hamaltahu 'alal-ladheena min qablinaa, Rabbanaa wa laa tu'hammilnaa maa laa taaqata lanaa bihi, wa'fu 'annaa, waghfir lanaa war'hamnaa, 'Anta Mawlaanaa fansurnaa 'alal-qawmil-kaafireen","ref":"Al-Bukhari, Fathul Bari 9/94, Muslim 1/554, no. 807"},{"id":118,"cat":"sleep","sub":14,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ يَا أَيُّهَا الْكَافِرُونَ ١ لَا أَعْبُدُ مَا تَعْبُدُونَ ٢ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ٣ وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ ٤ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ٥ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ٦","tr":"Bismillaahir Rahmaanir Raheem (1) Qul yaa-ayyuhal kaafiroon (2) Laaa a'budu maa t'abudoon (3) Wa laa antum 'aabidoona maaa a'bud (4) Wa laaa ana 'abidum maa 'abattum (5) Wa laa antum 'aabidoona maa a'bud (6) Lakum deenukum wa liya deen","ref":"Sahih (Albani). Tirmidhi: 3403"},{"id":119,"cat":"sleep","sub":14,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ هُوَ اللَّـهُ أَحَدٌ ١ اللَّـهُ الصَّمَدُ ٢ لَمْ يَلِدْ وَلَمْ يُولَدْ ٣ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ٤","tr":"Bismillaahir-Rahmaanir-Raheem (1) Qul HuwAllahu 'Ahad. (2) Allahus-Samad. (3) Lam yalid wa lam yoolad. (4) Wa lam yakun lahu kufuwan 'ahad","ref":"Sahih Muslim: 811"},{"id":122,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ بِاسْمِكَ أَمُوْتُ وَأَحْيَا","tr":"Allaahumma bismika amutu wa a'h-yaa","ref":"Bukhari: 6314"},{"id":123,"cat":"sleep","sub":14,"ar":"بِاسْمِكَ اَللَّهُمَّ أَمُوْتُ وَأَحْيَا","tr":"Bismika Allaahumma 'amootu wa 'ahyaa","ref":"Al-Bukhari, Fathul Bari 11/113 no. 6324, Muslim 4/2083 no. 2711"},{"id":124,"cat":"sleep","sub":14,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِى كَفَانِى وَآوَانِى وَأَطْعَمَنِى وَسَقَانِى وَالَّذِى مَنَّ عَلَىَّ فَأَفْضَلَ وَالَّذِى أَعْطَانِى فَأَجْزَلَ اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ اَللَّهُمَّ رَبَّ كُلِّ شَىْءٍ وَمَلِيْكَهُ وَإِلَهَ كُلِّ شَىْءٍ أَعُوْذُ بِكَ مِنَ النَّارِ","tr":"Alhamdu lillaahil-ladhi kafaani wa aa'wani wa at'amani wa saqaani wal-ladhi manna alayya fa-afdala wal-ladhi a'taani fa-ajzala alhamdu-lillaahi alaa kulli hal, Allaahumma rabba kulli shayin wa malikahu wa ilaaha kulli shayin A‛oodhu bika minan naar","ref":"Sahih (Albani). Abu Dawud: 5058"},{"id":125,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا لَكَ مَمَاتُهَا وَمَحْيَاهَا إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ","tr":"Allaahumma 'innaka khalaqta nafsee wa 'Anta tawaffaahaa, laka mamaatuhaa wa mahyaahaa, 'in 'ahyaytahaa fa’hfadhhaa, wa 'in 'amattahaa faghfir lahaa. Allaahumma 'innee 'as'alukal-'aafiyah","ref":"Muslim: 2712"},{"id":126,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","tr":"Allaahumma 'Antal-'Awwalu falaysa qablaka shay'un, wa 'Antal-'Aakhiru falaysa ba'daka shay'un, wa 'Antadh-Dhaahiru falaysa fawqaka shay'un, wa 'Antal-Baatinu falaysa doonaka shay'un, iqdhi 'annad-dayna wa 'aghninaa minal-faqr","ref":"Muslim: 2713"},{"id":127,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ فَالِقَ الْحَبِّ وَالنَّوَى وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","tr":"Allaahumma Rabbas-samaawaatis-sab'i wa Rabbal ard, wa Rabbal-'Arshil-'Adheem, Rabbanaa wa Rabba kulli shay 'in, faaliqal-habbi wannawaa, wa munzilat-Tawraati wal-'Injeeli, wal-Furqaan, 'a'oodhu bika min sharri kulli shay 'in 'Anta 'aakhidhun binaasiyatihi. Allaahumma 'Antal-'Awwalu falaysa qablaka shay'un, wa 'Antal-'Aakhiru falaysa ba'daka shay'un, wa 'Antadh-Dhaahiru falaysa fawqaka shay'un, wa 'Antal-Baatinu falaysa doonaka shay'un, iqdhi 'annad-dayna wa 'aghninaa minal-faqr","ref":"Muslim: 2713, Sahih (Albani). Tirmidhi: 3481"},{"id":128,"cat":"sleep","sub":14,"ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ (التَّامَّاتِ) مِنْ غَضَبِهِ وَعِقَابِهِ وَ(مِنْ) شَرِّ عِبَادِهِ وَمِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَأَنْ يَحْضُرُوْنِ","tr":"A'oodhu bikalimaatil-laahit-taammaati min ghadhabihi wa 'iqaabihi, wa (min) sharri 'ibaadihi, wa min hamazaatish-shayaateeni wa 'an yahduroon","ref":"Hasan (Albani). Tirmidhi: 3528"},{"id":129,"cat":"sleep","sub":14,"ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","tr":"Bismika Rabbee wada'tu janbee, wa bika 'arfa'uhu, fa'in 'amsakta nafsee far’hamhaa, wa 'in 'arsaltahaa fa’hfadh haa, bimaa ta’hfadhu bihi 'ibaadakas-saaliheen","ref":"Al-Bukhari 11/126 no. 6320, Muslim 4/2084 no.2714"},{"id":130,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ","tr":"Allaahumma qinee 'adhaabaka yawma tab'athu 'ibaadak","ref":"Sahih (Albani). At-Tirmizi: 3398"},{"id":131,"cat":"sleep","sub":14,"ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِيْ فَاغْفِرْ لِي ذَنْبِيْ","tr":"Bismika Rabbi Wada`tu janbi, faghfir lee janbi","ref":"Hasan (Shuaib al-Arnait). Musnad Ahmad: 6620"},{"id":132,"cat":"sleep","sub":14,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ","tr":"Alhamdu lillaahil-ladhee 'at'amanaa wa saqaanaa, wa kafaanaa, wa 'aawaanaa, fakam mimman laa kaafiya lahu wa laa mu'wiya","ref":"Muslim 4/2085 no. 2715"},{"id":133,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ وَمِنْ شَرِّ الشَّيْطَانِ وَ شِرْكِهِ وَأَنْ أَقْتَرِفَ عَلَى نَفْسِيْ سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","tr":"Allaahumma 'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal'ardh, Rabba kulli shay 'in wa maleekahu, 'ash-hadu 'an laa 'ilaaha 'illaa 'Anta, 'a'oodhu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa 'an 'aqtarifa 'alaa nafsee soo 'an, 'aw 'ajurrahu 'ilaa Muslim","ref":"Sahih (Albani). Tirmidhi: 3392"},{"id":134,"cat":"sleep","sub":14,"ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ مِنْ شَرِّ مَا خَلَقَ وبَرَأَ وَذَرَأَ وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ","tr":"A‛oodhu bikalima-tillahit taamma-tillati la-yujawizuhunna barrun wala-fa-jirun, min sharri ma- khalaqa wa bara-aa wa dhara-aa, wa min sharri ma yanzilu minas sama-yi wa min Sharhri Ma Ya’ruju fi-haa, Wa Min sharri maa dhara-a fil ardhi,Wa Min sharri Ma Ya'khruju Minhha-, Wa Min sharri Fitanillali Wan Naha-ri, Wa Min sharri Kulli Ta-Riqin Illa- Tariqan Yatruqu Bikhairin Ya-Rahmaan","ref":"Sahih (Arnaut). Ahmed: 15499"},{"id":135,"cat":"sleep","sub":14,"ar":"بِسْمِ اللَّهِ وَضَعْتُ جَنْبِى اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ وَأَخْسِئْ شَيْطَانِيْ وَفُكَّ رِهَانِيْ وَاجْعَلْنِيْ فِي النَّدِىِّ الْأَعْلَى","tr":"Bismillaahi wada‘tu janbi, Allahum-maghfir li dhanbi wa akhsi’ shaytaani wa fukka rihaani waj‘alni fi’n-nadiyyi al-a‘laa","ref":"Sahih (Albani). Sunan Abu Dawud: 5054"},{"id":136,"cat":"sleep","sub":14,"ar":"اَللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ وَفَوَّضْتُ أَمْرِي إِلَيْكَ وَوَجَّهْتُ وَجْهِيْ إِلَيْكَ وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ رَغْبَةً وَرَهْبَةً إِلَيْكَ لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ","tr":"Allaahumma 'aslamtu nafsee 'ilayka, wa fawwadhtu 'amree 'ilayka, wa wajjahtu wajhee 'ilayka, wa 'alja'tu dhahree 'ilayka, raghbatan wa rahbatan 'ilayka, laa maalja' wa laa manjaa minka 'illaa 'ilayka, 'aamantu bikitaabikal-ladhee 'anzalta wa bi-nabiyyikal-ladhee 'arsalta","ref":"Al-Bukhari, Fathul Bari 11/113 no. 6313, Muslim 4/2081 no. 2710"},{"id":138,"cat":"sleep","sub":15,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ","tr":"Laa 'ilaaha 'illAllahul-Waahidul-Qahhaar, Rabbus-samaawaati wal'ardh, wa maa baynahumal-'Azeezul-Ghaffaar","ref":"Sahih by Hakim. Imam Dhahabi 1/540; Nasai, Amalul Yaomi Wallayla No. 202, Ibnus sunni No. 757. Also see, Sahih Jame 4:213"},{"id":139,"cat":"sleep","sub":15,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيْمِ رَبِّ اغْفِرْ لِي","tr":"Laa 'illaaha 'illAllahu wa’hdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa 'alaa kulli shay'in Qadeer Subhaanallahi, walhamdu lillaahi, wa laa 'ilaaha 'illAllahu, wAllahu 'akbar, wa laa ‘hawla wa laa Quwwata 'illaa billaahil-'Aliyyil-'Adheem, Rabbighfir lee","ref":"Sahih (Albani). Abu Dawud: 5060"},{"id":140,"cat":"sleep","sub":15,"ar":"إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ ١٩٠ الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ١٩١ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ١٩٢ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ١٩٣ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ١٩٤ فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّن بَعْضٍ ۖ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّهِ ۗ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ ١٩٥ لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ ١٩٦ مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ ۚ وَبِئْسَ الْمِهَادُ ١٩٧ لَٰكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ اللَّهِ ۗ وَمَا عِندَ اللَّهِ خَيْرٌ لِّلْأَبْرَارِ ١٩٨ وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِآيَاتِ اللَّهِ ثَمَنًا قَلِيلًا ۗ أُولَٰئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ ١٩٩ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ ٢٠٠","tr":"Inna fee khalqis-samaawaati wal-ardi wakhtilaafil-layli wan-nahaari la-aayaatil-li-ulil-albaab. Allazeena yazkuroonallaaha qiyaaman wa qu'oodan wa 'alaa junoobihim wa yatafakkaroona fee khalqis-samaawaati wal-ardi Rabbanaa maa khalaqta haazaa baatilan Subhaanaka faqinaa 'azaaban-Naar. Rabbanaa innaka man tudkhilin-Naara faqad akhzaitahoo wa maa lizzaalimeena min ansaar. Rabbanaa innanaa sami'naa munaadiyan yunaadee lil-eemaani an aaminoo bi-Rabbikum fa-aamannaa; Rabbanaa faghfir lanaa zunoobanaa wa kaffir 'annaa sayyi-aatinaa wa tawaffanaa ma'al-abraar. Rabbanaa wa aatinaa maa wa'adtanaa 'alaa rusulika wa laa tukhzinaa Yawmal-Qiyaamah; innaka laa tukhliful-mee'aad. Fastajaaba lahum Rabbuhum annee laaa udee'u 'amala 'aamilim-minkum min zakarin aw unthaa; ba'dukum min ba'd; fallazeena haajaroo wa ukhrijoo min diyaarihim wa oozoo fee sabeelee wa qaataloo wa qutiloo la-ukaffiranna 'anhum sayyi-aatihim wa la-udkhilannahum jannaatin tajree min tahtihal-anhaar; thawaaban min 'indillaah; wallaahu 'indahoo husnuth-thawaab. Laa yaghurrannaka taqallubul-lazeena kafaroo fil-bilaad. Mataa'un qaleelun thumma ma'waahum Jahannamu wa bi'sal-mihaad. Laakinil-lazeena-ttaqaw Rabbahum lahum jannaatun tajree min tahtihal-anhaaru khaalideena feehaa nuzulan min 'indillaah; wa maa 'indallaahi khairul-lil-abraar. Wa inna min Ahlil-Kitaabi laman yu'minu billaahi wa maaa unzila ilaikum wa maaa unzila ilaihim khaashi'eena lillaahi laa yashtaroona bi-aayaatillaahi thamanan qaleelaa; ulaaa'ika lahum ajruhum 'inda Rabbihim; innallaaha saree'ul-hisaab. Yaaa ayyuhal-lazeena aamanus-biroo wa saabiroo wa raabitoo wattaqullaaha la'allakum tuflihoon.","ref":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 8/237 no.4569; Muslim 1/530 no. 256"},{"id":141,"cat":"sleep","sub":15,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُوْرُ","tr":"Alhamdu lillaahil-ladhee 'ahyaanaa ba'da maa 'amaatanaa wa'ilayhin-nushoor","ref":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/113 no. 6314; Muslim 4/2083 no. 2711"},{"id":142,"cat":"sleep","sub":15,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِيْ فِي جَسَدِيْ وَرَدَّ عَلَيَّ رُوحِيْ وَأَذِنَ لِي بِذِكْرِهِ","tr":"Alhamdu lillaahil-ladhee 'aafaanee fee jasadee, wa radda 'alayya roo’hee, wa 'adhina lee bidhikrih","ref":"At-Tirmithi 5/473. See Al-Albani's Sahih Tirmiihi 3/144"},{"id":144,"cat":"sleep","sub":15,"ar":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"A'oodhu billaahi minash-Shaytaanir-rajeem","ref":"[1] Bukhari: 7044 [2] Muslim: 6041 [3] Sahih (Albani). Tirmidhi: 2280"},{"id":146,"cat":"cloths","sub":16,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي كَسَانِيْ هَذَا الثَّوْبَ وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِنِّيْ وَلَا قُوَّةٍ","tr":"Alhamdu lillaahil-ladhee kasaanee haadhaa aththawba wa razaqaneehi min ghayri hawlim-minnee wa laa quwwah","ref":"Hasan (Albani). Abu Dawud: 4023"},{"id":147,"cat":"cloths","sub":16,"ar":"اَللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيْهِ أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ وَأَعُوْذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ","tr":"Allaahumma lakal-hamdu 'Anta kasawtaneehi, 'as'aluka khayrahu wa khayra maa suni'a lahu, wa 'a'oodhu bika min sharrihi wa sharri ma suni'a lahu","ref":"Sahih (Albani). Tirmidhi: 1767"},{"id":148,"cat":"cloths","sub":16,"ar":"تُبْلَی وَيُخْلِفُ اللَّهُ تَعَالَی","tr":"Tubla- wa yukhliful-laahu ta'aalaa","ref":"Sahih (Albani). Abu Dawud: 4020"},{"id":149,"cat":"cloths","sub":16,"ar":"بِسْمِ اللَّه","tr":"Bismillaah","ref":"Sahih (Albani). Tirmidhi: 606"},{"id":150,"cat":"cloths","sub":16,"ar":"أَبْلِيْ وَأَخْلِقِيْ","tr":"Abli wa akhliqi","ref":"Bukhari: 5993"},{"id":151,"cat":"cloths","sub":16,"ar":"أَبْلَ وَأَخْلَقْ","tr":"Abla wa akhlaq","ref":"Bukhari: 5993"},{"id":152,"cat":"cloths","sub":16,"ar":"اِلْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا","tr":"ilbas jadeedan, wa‛ish 'hameedan wa mut shaheedan","ref":"Sahih (Albani). Ibn Majah: 3558"},{"id":153,"cat":"cloths","sub":16,"ar":"اِلْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا وَيَرْزُقُكَ اللَّهُ قٌرَّةَ عَيْنٍ فِي الدُّنْيَا وَالْاَخِرَةِ","tr":"ilbas jadeedan, wa‛ish 'hameedan wa mut shaheedan wa iyarjuqukallahu qurrata ‘ainin feeduniya wal akhirah","ref":"Sahih (Albani). Sahihul Jami: 1234"},{"id":154,"cat":"home","sub":17,"ar":"بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"bismillaahi, tawakkaltu 'alal-laahi, laa hawla wa laa quwwata illaa billaah","ref":"Sahih (Albani). Abu Dawud: 5095"},{"id":155,"cat":"home","sub":17,"ar":"بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ اَللَّـهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نَزِلَّ أَوْ نَضِلَّ أَوْ نَظْلِمَ أَوْ نُظْلَمَ أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا","tr":"Bismillaahi, tawakkaltu 'alal-laahi. Allaahumma, inna na`udhu bika min an nazilla aw nadilla, aw nazlima aw nuzlama, aw najhala aw yujhala 'alaina","ref":"Sahih (Albani). Tirmidhi: 3427"},{"id":156,"cat":"home","sub":17,"ar":"اَللَّـهُمَّ إِنِّي أَعُوْذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ أَوْ أَزِلَّ أَوْ أُزَلَّ أَوْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ","tr":"Allaahumma innee a‛oodhu bika an adilla aw udalla, aw azilla aw uzalla, aw azlima aw uzlama, aw adhala aw yudhala ‛alayya","ref":"Sahih (Albani). Abu Dawud: 5094"},{"id":157,"cat":"home","sub":18,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","tr":"Allaahumma inni as'aluka khairal-mawliji wa khairal-makhraji. Bismillahi wa lajna, wa bismillahi kharajna, wa 'al-Allahi rabbina tawakkalna","ref":"Hasan (Ibn Baz). Abu Dawud: 5096"},{"id":159,"cat":"home","sub":18,"ar":"بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","tr":"Bismil-laahi walajna, wabismil-laahi kharajna, wa'alallaahi rabbina tawakkalna","ref":"[1] Hasan (Ibn Baz). Abu Dawud: 5096 [2] Muslim: 2018"},{"id":160,"cat":"toilet","sub":19,"ar":"بِسْمِ اللَّهِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","tr":"Bismillaah, Allaahumma 'innee 'A'oodhu bika minal-khubuthi walkhabaa'ith","ref":"Bukhari: 142"},{"id":161,"cat":"toilet","sub":19,"ar":"غُفْرَانَكَ","tr":"Gufraanak","ref":"Sahih (Albani). Abu Dawud: 30"},{"id":163,"cat":"adhaan-and-iqamah","sub":20,"ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ رَضِيتُ بِاللَّهِ رَبًّا وَبِمُحَمَّدٍ رَسُولًا وَبِالْإِسْلَامِ دِينًا","tr":"Ash-hadu an laa ilaaha ill-Allahu wa'hdahu laa shareeka lahu wa anna mu'hammadan ‛abduhu wa rasooluhu, radeetu billaahi rabban wa bimu'hammadin rasoolan wa bil -islaami deen-an","ref":"Muslim: 386"},{"id":164,"cat":"adhaan-and-iqamah","sub":21,"ar":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ اَللَّهُمَّ بَارِكَ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ","tr":"Allaahumma salli 'alaa Mu'hammadin wa 'alaa 'aali Mu'hammadin, kamaa sallayta 'alaa 'Ibraaheema wa 'alaa 'aali 'Ibraaheema, 'innaka Hameedun Majeed. Allaahumma baarik 'alaa Mu'hammadin wa 'alaa 'aali Mu'hammadin, kamaa baarakta 'alaa 'Ibraaheema wa 'alaa 'aali 'Ibraaheema, 'innaka Hameedun Majeed","ref":"Muslim: 384"},{"id":165,"cat":"adhaan-and-iqamah","sub":21,"ar":"اَللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا وَالْوَسِيْلَةَ وَالْفَضِيْلَةَ وَابْعَثْهُ مَقَامًا مَحْمُوْدًا الَّذِيْ وَعَدْتَهُ","tr":"Allaahumma rabba haadhi-hid-da watit-taammah, wassalaatil-qaa’imah, aati mu'hammadan-il- waseelata wal-fadeelah, wab‛ath-hu maqaaman ma'hmoodan-illadhee wa‛adtah","ref":"Bukhari: 614"},{"id":168,"cat":"adhaan-and-iqamah","sub":23,"ar":"اَللَّهُمَّ أَرْشِدِ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِيْنَ","tr":"Allaahumma arshidil a-immata wagfir lilmua-ddhinin","ref":"Sahih (Albani). Abu Dawud: 517"},{"id":170,"cat":"ablution-and-bath","sub":25,"ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","tr":"Ash-hadu 'an laa 'ilaaha 'illAllahu wahdahu laa shareeka lahu wa 'ash-hadu 'anna Muhammadan 'abduhu wa Rasooluhu","ref":"Muslim: 234 , 576"},{"id":171,"cat":"ablution-and-bath","sub":25,"ar":"اَللَّهُمَّ اجْعَلْنِيْ مِنَ التَّوَّابِيْنَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِيْنَ","tr":"Allaahummaj'alnee minat-tawwaabeena waj'alnee minal-mutatahhireen","ref":"Sahih (Albani). Tirmidhi: 55"},{"id":172,"cat":"ablution-and-bath","sub":25,"ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلاَّ أَنْتَ أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ","tr":"Subhaanaka Allaahumma wa bihamdika, 'ash-hadu 'an laa 'ilaaha 'illaa 'Anta, 'astaghfiruka wa 'atoobu 'ilayk","ref":"An-Nasa'i, 'Amalul-Yawm wal-Laylah, p. 173. See also Al-Albani, 'Irwa'ul-Ghalil 1/135 and 2/94."},{"id":173,"cat":"mosque","sub":26,"ar":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِيْ نُوْرًا وَّفِي لِسَانِىْ نُوْرًا وَّاجْعَلْ فِي سَمْعِىْ نُوْرًا وَّاجْعَلْ فِي بَصَرِىْ نُوْرًا وَّاجْعَلْ مِنْ خَلْفِي نُوْرًا وَّمِنْ أَمَامِيْ نُوْرًا وَّاجْعَلْ مِنْ فَوْقِىْ نُوْرًا وَّمِنْ تَحْتِىْ نُوْرًا اَللَّهُمَّ أَعْطِنِىْ نُوْرًا","tr":"Allaahumma-j‛al fee qalbee noor-an, wa fee lisaanee noor-an, waj‛al fee sam‛ee noor-an, waj‛al fee basaree noor-an, waj‛al min khalfee noor-an, wamin amaamee noor-an, waj‛al min fawqee noor-an, wa min t'ahtee noor-an, Allaahumma a‛tinee noor-an","ref":"Bukhari: 6316"},{"id":174,"cat":"mosque","sub":26,"ar":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا وَفِي لِسَانِي نُورًا وَفِي سَمْعِي نُورًا وَفِي بَصَرِي نُورًا وَمِنْ فَوْقِي نُورًا وَمِنْ تَحْتِي نُورًا وَعَنْ يَمِينِي نُورًا وَعَنْ شِمَالِي نُورًا وَمِنْ أَمَامِي نُورًا وَمِنْ خَلْفِي نُورًا وَاجْعَلْ فِي نَفْسِي نُورًا وَأَعْظِمْ لِي نُورًا وَعَظِّمْ لِي نُورًا وَاجْعَلْ لِي نُورًا وَاجْعَلْنِي نُورًا اَللَّهُمَّ أَعْطِنِي نُورًا وَاجْعَلْ فِي عَصَبِي نُورًا وَفِي لَحْمِي نُورًا وَفِي دَمِي نُورا وَفِي شَعْرِي نُورًا وَفِي بَشَرِي نُورًا","tr":"Allaahummaj'al fee qalbee nooran, wa fee lisaaanee nooran, wa fee sam'ee nooran, wa fee basaree nooran, wa min fawqee nooran, wa min tahtee nooran, wa 'an yameenee nooran, wa 'an shimaalee nooran, wa min 'amaamee nooran, wa min khalfee nooran, waj'al fee nafsee nooran, wa 'a'dhim lee nooran, wa 'adhdhim lee nooran, waj'al lee nooran, waj'alnee nooran, Allaahumma 'a'tinee nooran, waj'al fee 'asabee nooran, wafee lahmee nooran, wafee damee nooran, wa fee sha'ree nooran, wa fee basharee nooran.","ref":"Bukhari: 6316"},{"id":175,"cat":"mosque","sub":27,"ar":"بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"Bismillaahi, Wassalaatu Wassalaamu 'alaa Rasoolillaah. Allahum-maftah lee 'abwaaba rahmatik.","ref":"Sahih (Albani). Abu Dawud: 465, Muslim: 713"},{"id":176,"cat":"mosque","sub":27,"ar":"بِسْمِ اللَّهِ اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"Bismillaahi, Allaahumma salli 'ala muhammad, Allaahummaf ta'hlii abwaba ra'hmatik","ref":"Hasan (Albani). Ibn Sunni: 88, Muslim: 713"},{"id":177,"cat":"mosque","sub":27,"ar":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"Rabbig-firli dhunubi waftah li abwaaba rahmatik","ref":"Sahih (Albani). Ibn Majah: 771"},{"id":178,"cat":"mosque","sub":27,"ar":"أَعُوْذُ بِاللَّهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ وَسُلْطَانِهِ الْقَدِيْمِ مِنَ الشَّيْطَانِ الرَّجِيْمِ بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"A'oodhu billahil-Aatheem wa bi wajhihil-kareem wa sultanihil-qadeem minash-shaytanir-rajeem, bismil-lahi, wassalatu wassalamu 'Aala rasoolil-lah, Allaahumma iftah lee abwaaba rahmatik","ref":"Sahih (Albani). Abu Dawud: 465, 466"},{"id":179,"cat":"mosque","sub":28,"ar":"بِسْمِ اللَّهِ اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ فَضْلِكَ","tr":"Bismillahi Allaahumma salli 'ala muhammad, Allaahumma inni as-aluka min fadlik","ref":"Hasan (Albani). Ibn Sunni: 88, Muslim: 713"},{"id":180,"cat":"mosque","sub":28,"ar":"بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ اَللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"Bismillaahi wassalaatu wassalaamu 'alaa Rasoolillaah, Allaahumma 'innee 'as'aluka min fadhlik, Allaahumma'simnee minash-Shaytaanir-rajeem.","ref":"Sahih (Albani). Ibn Majah: 773"},{"id":181,"cat":"mosque","sub":28,"ar":"اَللَّهُمَّ أَجِرْنِيْ مِنَ الشَّيْطَانِ الرَّجِيْمِ","tr":"Allaahumma ajirni minash shaitaanir rajeem","ref":"Sahih (Ibn Hibban). Ibn Hibban: 2047"},{"id":182,"cat":"mosque","sub":28,"ar":"اَللَّهُمَّ اعْصِمْنِى مِنَ الشَّيْطَانِ الرَّجِيْمِ","tr":"Allaahumma aa'simni minash shaitaanir rajeem","ref":"Sahih (Albani). Ibn Majah: 773"},{"id":183,"cat":"mosque","sub":28,"ar":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ","tr":"Allaahummaghfirli dhunubi, waftahli abwaba fadlik","ref":"Sahih (Albani). Ibn Majah: 771"},{"id":184,"cat":"mosque","sub":29,"ar":"لَا رَدَّهَا اللَّهُ عَلَيْكَ","tr":"laa raddahAllahu 'alaik","ref":"Sahih (Albani). Tirmidhi: 1321"},{"id":185,"cat":"mosque","sub":30,"ar":"لَا أَرْبَحَ اللَّهُ تِجَارَتَكَ","tr":"laa arba'ha Allahu tijaarataka","ref":"Sahih (Albani). Tirmidhi: 1321"},{"id":186,"cat":"salah","sub":31,"ar":"وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ اَللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ أَنْتَ رَبِّي وَأَنَا عَبْدُكَ ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ كُلُّهُ بِيَـدَيْكَ وَالشَّـرُّ لَيْسَ إِلَيْـكَ أَنَا بِكَ وَإِلَيْكَ تَبارَكْتَ وَتَعَالَيْتَ أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ","tr":"Wajjahtu wajhiya lilladhee fataras-samawaati wal-arda haneefan wa maa ana minal-mushrikeen, inna salaatee wa nusukee wa mahyaaya wa mamaatee lillaahi rabbil-’alameen, laa shareeka lahu wabi dhaalika umirtu wa-ana minal-muslimeen. Allaahumma antal-maliku laa ilaaha illaa anta. anta rabbee wa-anaa ‘abduka, dhalamtu nafsee wa’taraftu bidhanbee faghfir lee dhunoobee jamee’an innahu laa yaghfirudh-dhunooba illaa anta. wahdinee li-ahsanil-akhlaaqi laa yahdee li-ahsaniha illaa anta, wasrif ‘annee sayyiaha laa yasrifu ‘annee sayyiaha illaa anta, Labbayka wa sa’dayka, wal-khayru kulluhu biyadayka, washsharru laysa ilayka, ana bika wa-ilayka, tabarakta wa ta’alayta, astaghfiruka wa atoobu ilayk","ref":"Muslim: 771"},{"id":187,"cat":"salah","sub":31,"ar":"اَللَّهُمَّ بَاعِدْ بَيْنِيْ وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ اَللَّهُمَّ نَقِّنِيْ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ اَللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ","tr":"Allaahumma baa'id baynee wa bayna khataayaaya kamaa baa'adta baynal-mashriqi walmaghrib, Allaahumma naqqinee minal khataayaa kamaa yunaqqath-thawbul-'abyadhu minad-danas, Allaahummaghsil khataayaaya, bil maa'i wath-thalji wal-barad","ref":"Bukhari: 744"},{"id":188,"cat":"salah","sub":31,"ar":"اَللَّهُمَّ رَبَّ جِبْرَائِيْلَ وَمِيْكَائِيْلَ وَإِسْرَافِيلَ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ اِهْدِنِيْ لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِيْ مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيْمٍ","tr":"Allaahumma rabba jibraa-eel, wameekaa-eel, wa-israafeel faatiras-samawaati wal-ardi, ‘Aalimal-ghaybi wash-shahadati, anta tahkumu bayna ‘ibaadika feemaa kaanoo feehi yakhtalifoon. ihdinee limakh-tulifa feehi minal-haqqi bi-idhnika, innaka tahdee man tasha-o ilaa siratin mustaqeem","ref":"Muslim: 770"},{"id":189,"cat":"salah","sub":31,"ar":"اَللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ وَلَكَ الْحَمْدُ لَكَ مُلْكُ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ وَلَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالْأَرْضِ وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ وَوَعْدُكَ الْحَقُّ وَلِقَاؤُكَ حَقٌّ وَقَوْلُكَ حَقٌّ وَالْجَنَّةُ حَقٌّ وَالنَّارُ حَقٌّ وَالنَّبِيُّونَ حَقٌّ وَمُحَمَّدٌ صلى الله عليه وسلم حَقٌّ وَالسَّاعَةُ حَقٌّ اَللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ وَإِلَيْكَ حَاكَمْتُ فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ (لَا إِلَهَ غَيْرُكَ)","tr":"Allaahumma lakal-hamdu. Anta qaiyyimus-samawaati wal-ardi wa man fihinna. Walakal-hamdu, Laka mulkus-samawaati wal-ardi wa man fihinna. Walakal-hamdu, anta nurus-samawaati wal-ardi. Walakal-hamdu, antal-haqqu wa wa'dukal-haqqu, wa liqaa'uka Haqqun, wa qauluka Haqqun, wal-jannatu Haqqun wan-naaru Haqqun wannabiyuna Haqqun. Wa Muhammadun (ﷺ) Haqqun, was-sa'atu Haqqun. Allaahumma Laka aslamtu wabika amantu, wa 'Alaika tawakkaltu, wa ilaika anabtu wa bika khaasamtu, wa ilaika ‘haakamtu faghfir li maa qaddamtu wamaa akh-khartu wamaa as-rartu wamaa a’lantu, antal-muqaddimu wa antal muakh-khiru, laa ilaaha illaa anta (in another narration there is laa ilaaha ghairuka instead of laa ilaaha illaa anta)","ref":"Bukhari: 1120"},{"id":190,"cat":"salah","sub":31,"ar":"اَللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ أَنْتَ رَبِّي وَأَنَا عَبْدُكَ ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ.","tr":"Allaahumma antal-maliku laa ilaaha illaa anta. anta rabbee wa-anaa ‘abduka, dhalamtu nafsee wa’taraftu bidhanbee faghfir lee dhunoobee jamee'aan innahu laa yaghfirudh-dhunooba illaa anta. wahdinee li-ahsanil-akhlaaqi laa yahdee li-ahsanihaa illaa anta, wasrif 'annee sayyi-ahaa laa yasrifu 'annee sayyi-ahaa illaa anta","ref":"Muslim: 771"},{"id":191,"cat":"salah","sub":31,"ar":"لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ كُلُّهُ بِيَـدَيْكَ وَالشَّـرُّ لَيْسَ إِلَيْـكَ أَنَا بِكَ وَإِلَيْكَ تَبَارَكْتَ وَتَعَالَيْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","tr":"Labbayka wa sa'dayka, wal-khayru kulluhu biyadaika, washsharru laysa ilayka, anaa bika wa-ilayka, tabaarakta wa ta'Aalayta, astaghfiruka wa-atoobu ilayk","ref":"Muslim: 771"},{"id":192,"cat":"salah","sub":31,"ar":"اَللَّهُ أَكْبَرُ كَبِيرًا اَللَّهُ أَكْبَرُ كَبِيرًا اَللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا","tr":"Allahu 'Akbar Kabeera, Allahu 'Akbar Kabeera, Allahu 'Akbar Kabeera, walhamdu lillaahi katheera, walhamdu lillaahi katheera, walhamdu lillaahi katheera, wa SubhaanAllahi bukratan wa'aseela","ref":"Hasan li gairihi (Shu'aib Al-Arnaut). Abu Dawud: 764"},{"id":872,"cat":"salah","sub":31,"ar":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلٰهَ غَيْرُكَ","tr":"Subhaanaka Allaahumma wa bihamdika, wa tabaarakasmuka, wa ta'aalaa jadduka, wa laa 'ilaaha ghayruk.","ref":"Muslim: 399"},{"id":193,"cat":"salah","sub":32,"ar":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيْمِ","tr":"A'oodhu billaahi minash-Shaytaanir-rajeem","ref":"Muslim: 2203"},{"id":195,"cat":"salah","sub":33,"ar":"سُبْحَانَ رَبِّيَ الْعَظِيمِ","tr":"Subhaana Rabbiyal-'Adheem","ref":"Sahih (Albani). Tirmidhi: 262"},{"id":196,"cat":"salah","sub":33,"ar":"سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ","tr":"Subhaana Rabbiyal-'Adheem wa bihamdihi","ref":"Hasan Sanad (Shu'aib Al-Arnaut). Abu Dawud: 870"},{"id":197,"cat":"salah","sub":33,"ar":"سُبُّوْحٌ قُدُّوْسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوْحِ","tr":"Subboohun, Quddoosun, Rabbul-malaa'ikati warrooh","ref":"Sahih (Albani). Abu Dawud: 872"},{"id":198,"cat":"salah","sub":33,"ar":"اَللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ خَشَعَ لَكَ سَمْعِيْ وَبَصَرِيْ وَمُخِّيْ وَعِظَامِيْ وَعَصَبِيْ","tr":"Allaahumma laka raka'tu, wa bika 'aamantu, wa laka 'aslamtu khasha'a laka sam'ee, wa basaree, wa mukhkhee, wa 'idhaamee, wa 'asabee","ref":"Sahih (Albani). Abu Dawud: 760"},{"id":199,"cat":"salah","sub":33,"ar":"سُبْحَانَ ذِي الْجَبَرُوْتِ وَالْمَلَكُوْتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ","tr":"Subhaana dhil-jabarooti, wal-malakooti, wal-kibriyaa'i, wal-'adhamah","ref":"Sahih (Albani). Abu Dawud: 873"},{"id":200,"cat":"salah","sub":33,"ar":"سُبْحَانَكَ وَبِحَمْدِكَ أَسْتَغْفِرُكَ وَأَتُوْبُ اِلَيْكَ","tr":"Subhaanaka wa bihamdika, 'astaghfiruka wa 'atoobu 'ilayk","ref":"Hasan (Albani). Silsila Sahiha: 3032"},{"id":201,"cat":"salah","sub":33,"ar":"سُبْحَانَكَ اَللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اَللَّهُمَّ اغْفِرْ لِي","tr":"Subhaanaka Allaahumma Rabbanaa wa bihamdika Allahum-maghfir lee","ref":"[1] Bukhari: 794 [2] Sura Nasr 110:3"},{"id":871,"cat":"salah","sub":33,"ar":"اَللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ أَنْتَ رَبِّي خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعَظْمِي وَعَصَبِي وَمَا اِسْتَقَلَّتْ بِهِ قَدَمِي لِلَّهِ رَبِّ الْعَالَمِينَ","tr":"Allahumma laka raka’tu wa bika amantu wa laka aslamtu, anta rabbi khasha’a laka sam’i wa basari wa mukh-khi wa ‘azmi wa ‘asabi wa ma istaqallat bihi qadami lillahi rabbil ‘alamin","ref":"Sahih (Al-Aini). Nukhbul Afkaar 4/247"},{"id":873,"cat":"salah","sub":33,"ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Subhaanaka allahumma wa bihamdika, laa ilaaha illaa anta.","ref":"Sahih. Nasa'i: 1131"},{"id":202,"cat":"salah","sub":34,"ar":"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ","tr":"Sami'Allahu liman hamidah","ref":"Bukhari: 796"},{"id":203,"cat":"salah","sub":34,"ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ أَحَقُّ مَا قَالَ الْعَبْدُ وَكُلُّنَا لَكَ عَبْدٌ اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","tr":"Allaahumma Rabbanaa lakal-hamdu mil'as-samawaati wa mil’al-ardi, wa mil'a maa shi'ta min shay'in ba'du, ahlath-thanaa'i wal-majdi, ahaqqu maa qaalal 'abdu, wa kullunaa laka 'abdun. Allaahumma laa maani'a limaa a'taita, wa laa mu'tiya limaa mana'ta, wa laa yanfa'u dhal-jaddi minkal-jaddu","ref":"Muslim: 477"},{"id":204,"cat":"salah","sub":35,"ar":"(اَللَّهُمَّ) رَبَّنَا لَكَ الْحَمْدُ","tr":"(1) Rabbanaa lakal-hamd (2) Allaahumma Rabbanaa lakal-hamd","ref":"Bukhari: 796"},{"id":205,"cat":"salah","sub":35,"ar":"(اَللَّهُمَّ) رَبَّنَا وَلَكَ الْحَمْدُ","tr":"(1) Rabbanaa wa lakal-hamd (2) Allaahumma Rabbanaa wa lakal-hamd","ref":"Bukhari: 795"},{"id":206,"cat":"salah","sub":35,"ar":"رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ","tr":"Rabbanaa wa lakal-hamd, hamdan katheeran tayyiban mubaarakan feeh","ref":"Bukhari: 799"},{"id":207,"cat":"salah","sub":35,"ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ","tr":"Alla-humma Rabbanaa lakal ‘hamdu mil-as samawaati wa mil-al ardi wa mil-aa maa baina humaa, wa mil-aa maa shi’ta min shayin ba’du","ref":"Muslim: 476"},{"id":208,"cat":"salah","sub":35,"ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","tr":"Allaahumma, rabbanaa lakal ‘hamdu, mil-as samawaati wa mil-al ardi wamaa bainahumaa, wa mil-aa maa shi’ta min shayin ba’du, ahlath thanaa’i wal majdi. Laa- maani'a limaa a'taita, walaa mut'ia limaa mana'ta, walaa yanfa'u dhal jaddi minkal jaddu","ref":"Muslim: 478"},{"id":209,"cat":"salah","sub":35,"ar":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ مُبَارَكًا عَلَيْهِ كَمَا يُحِبُّ رَبُّنَا وَيَرْضَى","tr":"Alhamdu lillahi hamdan kathiran tayyiban mubarakan fihi mubarakan ‘alaihi kamaa yuhibbu rabbunaa wa yardaa","ref":"Hasan (Albani). Sunan Nasai: 931"},{"id":874,"cat":"salah","sub":35,"ar":"لِرَبِّيَ الْحَمْدُ","tr":"li-rabbi-al hamd","ref":"Sahih. Abu Dawud: 874"},{"id":876,"cat":"salah","sub":35,"ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَىْءٍ بَعْدُ اَللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ اَللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الْوَسَخِ","tr":"Allaahumma, rabbanaa lakal ‘hamdu, mil-as samawaati wa mil-al ardi wa mil-aa maa shi’ta min shayin ba’du, Allaahumma tah-hirni bith-thalji wal baaradi wal ma-il baarad, Allaahumma tah-hirni minadh dhunubi wal khataaya kamaa yunakkath thawbul abyadu minal wasakh.","ref":"Muslim: 476"},{"id":213,"cat":"salah","sub":36,"ar":"سُبْحَانَ رَبِّيَ الْأَعْلَى","tr":"Subhaana Rabbiyal-A'laa","ref":"Muslim: 772"},{"id":214,"cat":"salah","sub":36,"ar":"سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ","tr":"Subhaana Rabbiyal-A'laa wa bihamdihi","ref":"Hasan Sanad (Shu'aib Al-Arnaut). Abu Dawud: 870"},{"id":215,"cat":"salah","sub":36,"ar":"اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ كُلَّهُ دِقَّهُ وَجِلَّهُ وَأَوَّلَهُ وَآخِرَهُ وَعَلَانِيَّتَهُ وَسِرَّهُ","tr":"Allahum-maghfir lee dhanbee kullahu, diqqahu wa jillahu, wa 'awwalahu wa 'aakhirahu wa 'alaa-niyyatahu wa sirrahu","ref":"Muslim: 483"},{"id":216,"cat":"salah","sub":36,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَأَعُوْذُ بِكَ مِنْكَ لَا أُحْصِيْ ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ","tr":"Allaahumma 'innee 'a'oodhu biridhaaka min sakhatik, wa bimu'aafaatika min 'uqoobatik wa 'a'oodhu bika minka, laa 'uhsee thanaa'an 'alayka, 'Anta kamaa 'athnayta 'alaa nafsik","ref":"Muslim:486, Sahih (Albani). Tirmidhi: 3566"},{"id":217,"cat":"salah","sub":36,"ar":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِيْ نُورًا وَفِي سَمْعِيْ نُورًا وَفِي بَصَرِيْ نُورًا وَعَنْ يَمِيْنِيْ نُورًا وَعَنْ شِمَالِيْ نُورًا وَأَمَامِيْ نُورًا وَخَلْفِي نُورًا وَفَوْقِيْ نُورًا وَتَحْتِيْ نُورًا وَاجْعَلْ لِي نُورًا (وَاجْعَلْنِيْ نُورًا) وَاجْعَلْ فِي نَفْسِي نُورًا (وَفِي عَصَبِيْ نُورًا وَفِي لَحْمِي نُورًا وَفِي دَمِيْ نُورًا وَفِي شَعْرِيْ نُورًا وَفِي بَشَرِيْ نُورًا) اَللَّهُمَّ أَعْطِنِيْ نُورًا","tr":"Allahum-maj'al fi qalbi nuran, wa fi sami' nuran, wa fi basari nuran, wa`an yamini nuran, wa`an shimaali nuran, wa amaami nuran, wa khalfi nuran, wa fawqi nuran, wa ta’hti nuran, waj`alli nuran (waj`alni nuran), waj`al fi nafsi nuran, (wa fi asabi nuran, wa fi lahmi nuran, wa fi dami nuran, wa fi sha’ri nuran, wa fi bashari nuran), Allaahumma a’tini nuran","ref":"Sahih Bukhari: 6316, Sahih Muslim: 763"},{"id":219,"cat":"salah","sub":36,"ar":"سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","tr":"Subboohun, Quddoosun, Rabbul-malaa'ikati warrooh","ref":"Sahih (Albani). Abu Dawud: 872"},{"id":220,"cat":"salah","sub":36,"ar":"اَللَّهُمَّ لَكَ سَجَدْتُ وَلَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ وَصَوَّرَهُ فَأَحْسَنَ صُوْرَتَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","tr":"Allaahumma laka sajadtu wa laka 'aslamtu, wa bika 'aamantu sajada wajhiya lilladhee khalaqahu, wa sawwarahu fa'ahsana su-ratahu, wa shaqqa sam'ahu wa basarahu, tabaarakAllahu 'ahsanul-khaaliqeen","ref":"Sahih (Albani). Nasai: 1126"},{"id":221,"cat":"salah","sub":36,"ar":"سُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ","tr":"Subhaana dhil-jabarooti, wal-malakooti, wal-kibriyaa'i, wal-'adhamah","ref":"Hasan (Albani). Abu Dawud: 873"},{"id":222,"cat":"salah","sub":37,"ar":"رَبِّ اغْفِرْ لِي رَبِّ اغْفِرْ لِي","tr":"Rabbighfir lee, Rabbighfir lee","ref":"Sahih (Albani). Abu Dawud: 874"},{"id":223,"cat":"salah","sub":37,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي","tr":"Allahum-maghfir lee, warhamnee, wa 'aafinee, wahdinee, warzuqnee","ref":"Sahih (Albani). Tirmidhi: 284, Hasan (Albani). Abu Dawud: 850"},{"id":225,"cat":"salah","sub":38,"ar":"اَللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا وَضَعْ عَنِّي بِهَا وِزْرًا وَاجْعَلْهَا لِي عِنْدَكَ ذُخْرًا وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ","tr":"Allahum-maktub lee bihaa ‘indaka ‘ajran, wada', ‘annee bihaa wizran, waj’alhaa lee ‘indaka dhukhran, wa taqabbalhaa minnee kamaa taqabbaltahaa min ’abdika Daawood","ref":"Hasan (Albani). Tirmidhi: 579"},{"id":226,"cat":"salah","sub":38,"ar":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ","tr":"Sajada wajhiya lilladhee khalaqahu, wa shaqqa sam'a-hu wa basarahu bi hawlihi wa quwwatih","ref":"Hasan (Albani). Tirmidhi: 580"},{"id":227,"cat":"salah","sub":38,"ar":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","tr":"Sajada wajhiya lilladhee khalaqahu, wa shaqqa sam'ahu wa basarahu bi hawlihi wa quwwatihi. FatabaarakAllahu 'ahsanul-khaaliqeen","ref":"Sahih (Albani). Tirmidhi: 3425, Sura Al Muminun 23:14"},{"id":228,"cat":"salah","sub":39,"ar":"اَلتَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","tr":"Attahiyyaatu lillaahi wassalawaatu, wattayyibaatu, assalaamu 'alayka 'ayyuhan-Nabiyyu wa rahmatullaahi wa barakaatuhu, assalaamu 'alaynaa wa 'alaa 'ibaadillaahis-saaliheen. 'Ash-hadu 'an laa 'ilaaha 'illAllahu wa 'ash-hadu 'anna Muhammadan 'abduhu wa Rasooluhu","ref":"Bukhari: 7381"},{"id":868,"cat":"salah","sub":39,"ar":"اَلتَّحِيَّاتُ الْمُبَارَكَاتُ الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ اَلسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَّا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ","tr":"Attahiyyaatul muba’rakaatus salawaatut, tayyibaatu lillaahi, assalaamu 'alayka 'ayyuhan-Nabiyyu wa rahmatullaahi wa barakaatuhu, assalaamu 'alaynaa wa 'alaa 'ibaadillaahis-saaliheen. 'Ash-hadu 'an laa 'ilaaha 'illAllahu wa 'ash-hadu 'anna Muhammadar Rasoolullaah.","ref":"Muslim: 403"},{"id":869,"cat":"salah","sub":39,"ar":"اَلتَّحِيَّاتُ لِلَّهِ اَلزَّاكِيَاتُ لِلَّهِ اَلطَّيِّبَاتُ الصَّلَوَتُ لِلَّهِ اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهٗ اَلسَّلَامُ عَلَيْنَا وَعَلٰى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهٗ ورَسُولُهُ","tr":"Attahiyyaatu lillaahi ajjakiyaatu lillaahi, Attayyibaatus salawaatu lillaahi, assalaamu 'alayka 'ayyuhan-Nabiyyu wa rahmatullaahi wa barakaatuhu, assalaamu 'alaynaa wa 'alaa 'ibaadillaahis-saaliheen. 'Ash-hadu 'an laa 'ilaaha 'illAllahu wa 'ash-hadu 'anna Muhammadan 'abduhu wa Rasooluh.","ref":"Sahih (Albani). Sifatus Salah, p. 163"},{"id":229,"cat":"salah","sub":40,"ar":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَّعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيْمَ وَعَلَى آلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ اَللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَّعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيْمَ وَعَلَى آلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ","tr":"Allaahumma salli 'alaa Muhammadin wa 'alaa 'aali Muhammadin, kamaa sallayta 'alaa 'Ibraaheema wa 'alaa 'aali 'Ibraaheema, 'innaka Hameedun Majeed. Allaahumma baarik 'alaa Muhammadin wa 'alaa 'aali Muhammadin, kamaa baarakta 'alaa 'Ibraaheema wa 'alaa 'aali 'Ibraaheema, 'innaka Hameedun Majeed","ref":"Bukhari: 3370"},{"id":230,"cat":"salah","sub":40,"ar":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيْمَ وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ كَمَا بَارَكْتَ عَلَى آلِ إبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَجِيْدٌ","tr":"Allaahumma salli 'alaa Muhammadin wa 'azwaajihi wa dhurriyyatihi, kamaa sallayta 'alaa 'aali 'Ibraaheema. Wa baarik 'alaa Muhammadin wa 'azwaajihi wa dhurriyyatihi, kamaa baarakta 'alaa 'aali 'Ibraaheema. 'Innaka Hameedun Majeed","ref":"Bukhari: 3369"},{"id":231,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا وَأَصْلِحْ ذَاتَ بَيْنِنَا وَاهْدِنَا سُبُلَ السَّلَامِ وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّوْرِ وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ وَاجْعَلْنَا شَاكِرِيْنَ لِنِعْمَتِكَ مُثْنِيْنَ بِهَا قَابِلِيْهَا وَأَتِمَّهَا عَلَيْنَا","tr":"Allaahumma allif bayna quloobinaa wa aslih dhaata bayninaa wahdinaa subulas salaam, wa najjinaa minaz zulumaati ilan noor, wa jannibnal fawaa-hisha maa zahara minhaa wa maa batan, wa baarik lanaa fi asmaa’inaa wa absaarinaa wa quloobinaa wa azwaajinaa wa dhurri yaatinaa wa tub alaynaa innaka antat tawwaabur raheem waj’alnaa shaakireena lini’matika muth-neena bihaa qaabileehaa wa atimmahaa 'alaynaa","ref":"Daif (Albani). Abu Dawud: 969"},{"id":232,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","tr":"Allaahumma 'innee 'a'oodhu bika min 'adhaabi jahannam, wa min 'adhaabil-qabr, wa min fitnatil-mahyaa wal-mamaati, wa min sharri fitnatil-maseehid-dajjaal","ref":"Muslim: 588"},{"id":233,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allahum-maghfir lee maa qaddamtu, wa maa 'akhkhartu, wa maa 'asrartu, wa maa 'a'lantu, wa maa 'asraftu, wa maa 'Anta 'a'lamu bihi minnee. 'Antal-Muqaddimu, wa 'Antal-Mu'akhkhiru laa 'ilaaha 'illaa 'Anta","ref":"Muslim: 771"},{"id":234,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِيْ ظُلْمًا كَثِيْرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِيْ إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","tr":"Allaahumma 'innee dhalamtu nafsee dhulman katheeran, wa laa yaghfirudh-dhunooba 'illaa 'Anta, faghfir lee maghfiratan min 'indika warhamnee 'innaka 'Antal-Ghafoorur-Raheem","ref":"Bukhari: 834"},{"id":235,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِيْ مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي وَتَوَفَّنِيْ إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي اَللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى وَأَسْأَلُكَ نَعِيْمًا لَا يَنْفَدُ وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ اَللَّهُمَّ زَيِّنَا بِزِيْنَةِ الْإِيْمَانِ وَاجْعَلْنَا هُدَاةً مُهْتَدِيْنَ","tr":"Allaahumma bi'ilmikal-ghayba wa qudratika 'alal-khalq, 'ahyinee maa 'alimtal-hayaata khayran lee wa tawaffanee 'idhaa 'alimtal-wafaata khayran lee, Allaahumma wa 'as'aluka khashyataka fil-ghaybi wash-shahaadati, wa 'as'aluka kalimatal-haqqi fir-ridhaa wal-ghadhabi, wa 'as'alukal-qasda fil-faqri walghinaa, wa 'as'aluka na'eeman laa yanfadu, wa 'as'aluka qurrata 'aynin laa tanqati'u, wa 'as'alukar-ridhaa ba'dal-qadhaa, wa 'as'aluka bardal-'ayshi ba'dal-mawti, wa 'as'aluka ladh-dhatan-nadhari 'ilaa wajhika wash-shawqa 'ilaa liqaa'ika fee ghayri darraa'a mudirratin wa laa fitnatin mudillatin, Allaahumma zayyinnaa bizeenatil-'eemaani waj'alnaa hudaatan muhtadeen","ref":"Sahih (Albani). Nasai: 1305"},{"id":236,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَعُوْذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا","tr":"Allaahumma inni as'aluka minal-khayri kullihi, 'aajilihi wa aajilihi, maa 'alimtu minhu wa maa lam a'lam. Wa A‛oodhu bika minash-sharri kullihi, 'aajilihi wa aajilihi, maa 'alimtu minhu wa maa lam a'lam. Allaahumma inni as'aluka min khayri maa sa'alaka 'abduka wa nabiyyuka, wa A‛oodhu bika min sharri maa 'aadha bihi 'abduka wa nabiyyuka. Allaahumma inni as'alukal-jannata wa maa qarraba ilayhaa min qawlin aw 'amal, wa A‛oodhu bika minan-naari wa maa qarraba ilayhaa min qawlin aw 'amal, wa as'aluka an taj'al kulla qadaa'in qadaytahu li khayra","ref":"Sahih (Albani). Ibn Majah: 3846"},{"id":237,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْـيَا وَالْمَمَاتِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ","tr":"Allaahumma 'innee 'a'oodhu bika min 'adhaabil-qabr, wa 'a'oodhu bika min fitnatil-maseehid-dajjaal, wa 'a'oodhu bika min fitnatil-mahyaa wal-mamaat. Allaahumma 'innee 'a'oodhu bika minal-ma'thami wal-maghram","ref":"Bukhari: 832"},{"id":238,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيْحِ الدَّجَّالِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَمِنَ الْمَغْرَمِ","tr":"Allaahumma inni a`udhu bika min `adhaabi jahannam, wa a`udhu bika min `adhaabil-qabr, wa a`udhu bika min fitnatil-masihid-dajjaal, wa a`udhu bika min fitnatil-mahyaa wal-mamaat, Allaahumma inni a`udhu bika minal-ma'thami wa minal-maghram","ref":"Muslim: 1/412"},{"id":239,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","tr":"Allaahumma 'a'innee 'alaa dhikrika, wa shukrika, wahusni 'ibaadatik","ref":"Sahih (Albani). Abu Dawud: 1522"},{"id":240,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبُخْلِ وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَأَعُوْذُ بِكَ مِنْ أَنْ نُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ","tr":"Allaahumma 'innee 'a'oodhu bika minal-bukhli, wa 'a'oodhu bika minal-jubni, wa 'a'oodhu bika min 'an nuradda 'ilaa 'ardhalil-'umuri, wa 'a'oodhu bika min fitnatid-dunyaa wa 'adhaabil-qabr","ref":"Bukhari: 6374"},{"id":241,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوْذُ بِكَ مِنَ النَّارِ","tr":"Allaahumma 'innee 'as'alukal-jannata wa 'a'oodhu bika minan-naar","ref":"Sahih (Albani). Ibn Majah 3846"},{"id":242,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا أَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","tr":"Allaahumma 'innee 'as'aluka yaaAllahu bi'annakal-Waahidul-'Ahadus-Samadul-ladhee, lam yalid wa lam yoolad, wa lam yakun lahu kufuwan 'Ahad, 'an taghfira lee dhunoobee 'innaka 'Antal-Ghafoorur-Raheem","ref":"Sahih (Albani). Nasai: 1301"},{"id":243,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلاَّ أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ","tr":"Allaahumma innee as’aluka bi anna lakal-hamda laa ilaaha illaa anta al-mannaanu, badee‛-us-samawaati wal-ardi yaa dhal-jalaali wal-ikraam, yaa hayyu yaa qayyoomu, inne as’aluka","ref":"Sahih (Albani). Nasai: 1300"},{"id":244,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي اَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ","tr":"Allaahumma 'innee 'as'aluka bi'annee 'ash-hadu 'annaka 'AntAllahu laa 'ilaaha 'illaa 'Antal-'Ahadus-Samadul-ladhee lam yalid wa lam yoolad wa lam yakun lahu kufuwan 'Ahad","ref":"Sahih (Albani). Abu Dawud: 1493"},{"id":245,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ الْمَنَّانُ يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوْذُ بِكَ مِنَ النَّارِ","tr":"Allaahumma 'innee 'as'aluka bi'anna lakal-hamdu laa 'ilaaha 'illaa 'Anta wahdaka laa shareeka laka, Al-Mannaanu, yaa Badee'as-samawaati wal'ardhi yaa dhal-Jalaali wal-'Ikraam, yaa Hayyu yaa Qayyoomu 'innee 'as'alukal-jannata wa 'a'oodhu bika minan-naar","ref":"Sahih (Albani). Abu Dawud: 1493-1495"},{"id":875,"cat":"salah","sub":41,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَأَعُوْذُ بِكَ مِنَ الْهَرَمِ وَأَعُوْذُ بِكَ مِنَ الْبُخْلِ","tr":"Allaahumma innee A‛oodhu bika minal kasali, wa A‛oodhu bika minal jubni, wa A‛oodhu bika minal harami, wa A‛oodhu bika minal bukhl.","ref":"Bukhari: 6371"},{"id":246,"cat":"salah","sub":42,"ar":"اَللَّهُ أَكْبَرُ كَبِيْرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا","tr":"Allahu 'Akbar Kabiran, walhamdu lillaahi kathiran, wa Subhaanallahi bukratan wa'asila","ref":"Muslim: 601"},{"id":248,"cat":"salah","sub":43,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tr":"Laa ilaaha ill-Allahu, wa'hdahu laa shareeka lahu, lahul-mulku wa lahul-'hamdu, yu'hyee wa yumeetu, wa huwa ‛alaa kulli shay’in qadeer","ref":"Hasan (Albani). Tirmidhi: 3534"},{"id":249,"cat":"salah","sub":43,"ar":"اَللَّهُمَّ أَجِرْنِيْ مِنَ النَّارِ","tr":"Allaahumma Ajirni minan-naar","ref":"Hasan (Ibn Hajar). Al-futuhaatur Rabbaniyyah 3/69"},{"id":250,"cat":"salah","sub":44,"ar":"أَسْتَغْفِرُ اللَّهَ","tr":"Astaghfirullaah","ref":"Sahih Muslim: 591"},{"id":251,"cat":"salah","sub":44,"ar":"اَللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","tr":"Allaahumma 'Antas-Salaam wa minkas-salaam, tabaarakta yaa Dhal-Jalaali wal-'Ikraam","ref":"Muslim: 591"},{"id":252,"cat":"salah","sub":44,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِىَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","tr":"Laa ilaaha ill-Allahu wa'hdahu laa shareeka lahu, lahul-mulku wa lahul-'hamdu wa huwa ‛alaa kulli shay’in qadeer, Allaahumma laa maani‛a li maa a‛tayta, wa laa mu‛tiya li maa mana‛ta wa laa yanfa‛u dhal-jaddi minkal-jaddu","ref":"Bukhari: 844"},{"id":253,"cat":"salah","sub":44,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيْرٌ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَلَا نَعْبُدُ إِلَّا إِيَّاهُ لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِيْنَ لَهُ الدِّيْنَ وَلَوْ كَرِهَ الْكَافِرُوْنَ","tr":"Laa ilaaha ill-Allahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa huwa ‛alaa kulli shay’in qadeer, laa hawla wa laa quwwata illaa billaah, laa ilaaha ill-Allahu, wa laa na‛budu illaa iyyaahu, lahun-ni‛matu wa lahul-fadlu wa lahuth-thanaa’-ul-hasan, laa ilaaha ill-Allahu, mukhliseena lahud-deena wa law karihal-kaafiroon","ref":"Muslim: 594"},{"id":254,"cat":"salah","sub":44,"ar":"اَللّٰهُ لَآ إِلٰهَ إِلَّا هُوَ الْحَىُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى السَّمٰوٰتِ وَمَا فِى الْأَرْضِ ۗ مَنْ ذَا الَّذِى يَشْفَعُ عِنْدَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ الْعَلِىُّ الْعَظِيمُ","tr":"Allahu laa 'ilaaha 'illaa Huwal-Hayyul-Qayyoom, laa ta'khudhuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-'ardhi, man dhal-ladhee yashfa'u 'indahu 'illaa bi'idhnihi, ya'lamu maa bayna 'aydeehim wa maa khalfahum, wa laa yuheetoona bishay'im-min 'ilmihi 'illaa bimaa shaa'a, wasi'a kursiyyuhus-samaawaati wal 'ardh, wa laa ya'ooduhu hifdhuhumaa, wa Huwal-'Aliyyul- 'Adheem","ref":"Silsila Sahiha: 972"},{"id":257,"cat":"salah","sub":45,"ar":"سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ","tr":"SubhaanAllahi, walhamdu lillaahi wAllahu 'Akbar","ref":"Muslim 1/418, no.597"},{"id":258,"cat":"salah","sub":45,"ar":"رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ (تَجْمَعُ) عِبَادَكَ","tr":"Rabbi qini 'adhaabaka yawma tab'athu - [tajma'u] - 'ibaadak","ref":"Muslim: 709"},{"id":259,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ","tr":"Allaahumma inni A‛oodhu bika minal-kufri wal-faqri, wa 'adhaabil-qabr","ref":"Sahih (Albani). Nasai: 5465"},{"id":260,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ أَعِنِّى عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","tr":"Allaahumma 'a'innee 'alaa dhikrika, wa shukrika, wahusni 'ibaadatik","ref":"Sahih (Albani). Abu Dawud: 1522"},{"id":261,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ غْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allahum-maghfir lee maa qaddamtu, wa maa 'akhkhartu, wa maa 'asrartu, wa maa 'a'lantu, wa maa 'asraftu, wa maa 'Anta 'a'lamu bihi minnee. 'Antal-Muqaddimu, wa 'Antal-Mu'akhkhiru laa 'ilaaha 'illaa 'Anta","ref":"[1] Muslim: 771 [2] Sahih (Albani). Abu Dawud: 1509"},{"id":262,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ أَصْلِحْ لِي دِيْنِيَ الَّذِي جَعَلْتَهُ عِصْمَةَ أَمْرِي وَأَصْلِحْ لِي دُنْيَايَ الَّتِي جَعَلْتَ فِيهَا مَعَاشِيْ اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ وَبِعَفْوِكَ مِنْ نِقْمَتِكَ وَأَعُودُ بِكَ مِنْكَ اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","tr":"Allaahumma Aslih li dinya-lladhi ja'altahu ismata amri, wa aslih li dunyaya-llati ja'alta fihaa ma'aashi, Allaahumma inni a-udhu biridaaka min sakhatika, wabi 'afwika min niqmatika, wa a-udhu bika minka, Allaahumma laa maani'a limaa a'taita wa laa mu'tia limaa mana'ta wa laa yanfa'u dhal-jaddi minka al-jaddu","ref":"Hasan (Ibn Hajar). Alfutuhatur Rabbaniyyah 3/71"},{"id":263,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ بِكَ أُحَاوِلُ وَبِكَ أُقَاتِلُ وَبِكَ أَصَاوِلُ","tr":"Allaahumma bika o-'haa-wilu wa bika o-qaatilu wa bika asaa-wil","ref":"Sahih (Albani). Darimi: 2/217"},{"id":264,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْم (التَّوَّابُ الْغَفُورُ)","tr":"Allahum-maghfir lee wa tub `alayya innaka Antat-Tawwabur-Rahim (in another narration: Tawwabul-Ghafur)","ref":"Sahih (Albani). Sahihah: 556, Ahmad: 5564"},{"id":265,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَخَطَايَايَ كُلَّهَا اَللَّهُمَّ أَنْعِشْنِيْ وَاجْبُرْنِيْ وَاهْدِنيْ لِصَالِحِ الْأَعْمَالِ وَالْأَخْلَاقِ فَإِنَّهُ لَا يَهْدِيْ لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ","tr":"Allaahummagfirli dhunubi wa khata-ya-ya kullahaa, Allaahumma an-'ishni wajburni wahdini lisaali'hil a'maali wal akhlaaqi fa-innahu laa yahdi lisaali'hi-ha wa laa yasrifu sayyiahaa illaa anta","ref":"Hasan (Albani). Sahih Al Jame: 1266"},{"id":266,"cat":"salah","sub":45,"ar":"اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ وَوَسِّعْ لِي فِي دَارِيْ وَبَارِكْ لِي فِي رِزْقِيْ","tr":"Allaahummaghfir li dhanbi, wa wassi` li fi daari, wa baarik li fi rizqi","ref":"Hasan (Albani). Sahih Al Jame: 1265"},{"id":267,"cat":"salah","sub":45,"ar":"اَللَّهُ اَكْبَرُ","tr":"Allahu 'Akbar","ref":"Bukhari: 842"},{"id":268,"cat":"salah","sub":45,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَا نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","tr":"SubhaanAllahi wa bihamdihi 'Adada khalqihi, wa ridhaa nafsihi, wa zinata 'arshihi wa midaada kalimaatihi","ref":"Muslim: 2726"},{"id":273,"cat":"witr-and-other","sub":48,"ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ","tr":"Subhanaka Allaahumma wa bihamdika, wa tabaraka 'smuka, wa ta'ala jadduka, wa laa 'ilahaa ghayruk","ref":"Sahih (Albani). Abu Dawud: 775"},{"id":274,"cat":"witr-and-other","sub":49,"ar":"سُبْحَانَ الْمَلِكِ الْقُّدُّوْسِ","tr":"Subhaanal-Malikil-Quddoos","ref":"Sahih (Albani). Abu Dawud No. 1430; An-Nasa'i No. 1699, 1701"},{"id":275,"cat":"witr-and-other","sub":49,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَأَعُــوذُ بِكَ مِنْكَ لَا أُحْصِيْ ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ","tr":"Allaahumma 'innee 'a'oodhu biridhaaka min sakhatik, wa bimu'aafaatika min 'uqoobatik wa 'a'oodhu bika minka, laa 'uhsee thanaa'an 'alayka 'Anta kamaa 'athnayta 'alaa nafsik","ref":"Sahih. Abu Dawud: 1427"},{"id":276,"cat":"witr-and-other","sub":49,"ar":"رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","tr":"Rabbul-malaa'ikati warrooh","ref":"Sunan Daraqutni 2/31, Mu'jamul Awsat 8/108, Sunan Bayhaqi 3/40"},{"id":277,"cat":"witr-and-other","sub":50,"ar":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ١ الَّذِي خَلَقَ فَسَوَّىٰ ٢ وَالَّذِي قَدَّرَ فَهَدَىٰ ٣ وَالَّذِي أَخْرَجَ الْمَرْعَىٰ ٤ فَجَعَلَهُ غُثَاءً أَحْوَىٰ ٥ سَنُقْرِئُكَ فَلَا تَنسَىٰ ٦ إِلَّا مَا شَاءَ اللَّهُ ۚ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَىٰ ٧ وَنُيَسِّرُكَ لِلْيُسْرَىٰ ٨ فَذَكِّرْ إِن نَّفَعَتِ الذِّكْرَىٰ ٩ سَيَذَّكَّرُ مَن يَخْشَىٰ ١٠ وَيَتَجَنَّبُهَا الْأَشْقَى ١١ الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ ١٢ ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ ١٣ قَدْ أَفْلَحَ مَن تَزَكَّىٰ ١٤ وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّىٰ ١٥ بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا ١٦ وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ ١٧ إِنَّ هَٰذَا لَفِي الصُّحُفِ الْأُولَىٰ ١٨ صُحُفِ إِبْرَاهِيمَ وَمُوسَىٰ ١٩","tr":"Bismillaahir-Rahmaanir-Raheem. (1) Qul HuwAllahu 'Ahad. (2) Allahus-Samad. (3) Lam yalid wa lam yoolad. (4) Wa lam yakun lahu kufuwan 'ahad","ref":"Sahih (Albani). Abu Dawud: 1423"},{"id":278,"cat":"witr-and-other","sub":51,"ar":"اَللَّهُمَّ اهْدِنِيْ فِيمَنْ هَدَيْتَ وَعَافِنِيْ فِيمَنْ عَافَيْتَ وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِيْ شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِيْ وَلَا يُقْضَى عَلَيْكَ وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبارَكْتَ رَبَّنَا وَتَعَالَيْتَ","tr":"Allahum-mahdinee feeman hadayta, wa 'aafinee feeman 'aafayta, wa tawallanee feeman tawallayta, wa baarik lee feemaa 'a'atayta, wa qinee sharra maa qadhayta, fa'innaka taqdhee wa laa yuqdhaa 'alayka, wa 'innahu laa yathillu man waalayta, wa laa ya 'izzu man 'aadayta, tabaarakta Rabbanaa wa ta'aalayta","ref":"Sahih (Albani). Abu Dawud: 1425"},{"id":279,"cat":"witr-and-other","sub":51,"ar":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَيَّ وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَيَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَاهْدِنِيْ وَيَسِّرِ الْهُدَى لِي (إِلَيَّ) وَانْصُرْنِيْ عَلَى مَنْ بَغَى عَلَيَّ رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا لَكَ ذَكَّارًا لَكَ رَهَّابًا لَكَ مِطْوَاعًا لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيْبًا رَبِّ تَقَبَّلْ تَوْبَتِيْ وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِيْ وَثَبِّتْ حُجَّتِيْ وَسَدِّدْ لِسَانِيْ وَاهْدِ قَلْبِيْ وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","tr":"Rabbi A'inni wa laa tu'in 'alayya, wansurni wa laa tansur 'alayya, wamkurli wa laa tamkur 'alayya, wahdini wa yassiril-huda li (ilayya) wansurni 'alaa man bagha 'alayya. Rabbij'alni laka shakkaran laka dhakkaran, laka rahhaban, laka mitwaa'an, laka mukhbitan, 'ilayka awwaa'han muniban. Rabbi Taqabbal tawbati, waghsil ‘hawbati wa ajib da'wati, wa thabbit hujjati, wa saddid lisaani, wahdi qalbi, waslul sakhimata sadri","ref":"Sahih (Albani). Tirmidhi: 3551"},{"id":280,"cat":"witr-and-other","sub":51,"ar":"اَللَّهُمَّ إِيَّاكَ نَعْبُدُ وَلَكَ نُصَلِّي وَنَسْجُدُ وَإِلَيْكَ نَسْعَى وَنَحْفِدُ نَرْجُو رَحْمَتَكَ وَنَخْشَى عَذَابَكَ إِنَّ عَذَابَكَ بِالْكَافِرِينَ مُلْحَقٌ اَللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنُثْنِي عَلَيْكَ الْخَيْرَ وَلَا نَكْفُرُكَ وَنُؤْمِنُ بِكَ وَنَخْضَعُ لَكَ وَنَخْلَعُ مَنْ يَكْفُرُكَ","tr":"Allaahumma 'iyyaaka na'budu, wa laka nusallee wa nasjudu, wa 'ilayka nas'aa wa nahfidu, narjoo rahmataka, wa nakhshaa 'adhaabaka, 'inna 'adhaabaka bilkaafireena mulhaq. Allaahumma 'innaa nasta'eenuka, wa nastaghfiruka, wa nuthnee 'alaykal-khayr, wa laa nakfuruka, wa nu'minu bika, wa nakhdha'u laka, wa nakhla'u man yakfuruk","ref":"Sahih (Albani). Irwaul Galil: 2/170, Bayhaqi: As-Sunanul Kabra - 2/211"},{"id":281,"cat":"witr-and-other","sub":52,"ar":"إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ ١٩٠ الَّذِينَ يَذْكُرُونَ اللَّـهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ١٩١ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ١٩٢ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ١٩٣ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ١٩٤ فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّن بَعْضٍ ۖ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّـهِ ۗ وَاللَّـهُ عِندَهُ حُسْنُ الثَّوَابِ ١٩٥ لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ ١٩٦ مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ ۚ وَبِئْسَ الْمِهَادُ ١٩٧ لَـٰكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ اللَّـهِ ۗ وَمَا عِندَ اللَّـهِ خَيْرٌ لِّلْأَبْرَارِ ١٩٨ وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّـهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّـهِ لَا يَشْتَرُونَ بِآيَاتِ اللَّـهِ ثَمَنًا قَلِيلًا ۗ أُولَـٰئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ اللَّـهَ سَرِيعُ الْحِسَابِ ١٩٩ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّـهَ لَعَلَّكُمْ تُفْلِحُونَ ٢٠٠","tr":"Inna fee khalqis-samaawaati wal-ardi wakhtilaafil-layli wan-nahaari la-aayaatil-li-ulil-albaab. Allazeena yazkuroonallaaha qiyaaman wa qu'oodan wa 'alaa junoobihim wa yatafakkaroona fee khalqis-samaawaati wal-ardi Rabbanaa maa khalaqta haazaa baatilan Subhaanaka faqinaa 'azaaban-Naar. Rabbanaa innaka man tudkhilin-Naara faqad akhzaitahoo wa maa lizzaalimeena min ansaar. Rabbanaa innanaa sami'naa munaadiyan yunaadee lil-eemaani an aaminoo bi-Rabbikum fa-aamannaa; Rabbanaa faghfir lanaa zunoobanaa wa kaffir 'annaa sayyi-aatinaa wa tawaffanaa ma'al-abraar. Rabbanaa wa aatinaa maa wa'adtanaa 'alaa rusulika wa laa tukhzinaa Yawmal-Qiyaamah; innaka laa tukhliful-mee'aad. Fastajaaba lahum Rabbuhum annee laaa udee'u 'amala 'aamilim-minkum min zakarin aw unthaa; ba'dukum min ba'd; fallazeena haajaroo wa ukhrijoo min diyaarihim wa oozoo fee sabeelee wa qaataloo wa qutiloo la-ukaffiranna 'anhum sayyi-aatihim wa la-udkhilannahum jannaatin tajree min tahtihal-anhaar; thawaaban min 'indillaah; wallaahu 'indahoo husnuth-thawaab. Laa yaghurrannaka taqallubul-lazeena kafaroo fil-bilaad. Mataa'un qaleelun thumma ma'waahum Jahannamu wa bi'sal-mihaad. Laakinil-lazeena-ttaqaw Rabbahum lahum jannaatun tajree min tahtihal-anhaaru khaalideena feehaa nuzulan min 'indillaah; wa maa 'indallaahi khairul-lil-abraar. Wa inna min Ahlil-Kitaabi laman yu'minu billaahi wa maaa unzila ilaikum wa maaa unzila ilaihim khaashi'eena lillaahi laa yashtaroona bi-aayaatillaahi thamanan qaleelaa; ulaaa'ika lahum ajruhum 'inda Rabbihim; innallaaha saree'ul-hisaab. Yaaa ayyuhal-lazeena aamanus-biroo wa saabiroo wa raabitoo wattaqullaaha la'allakum tuflihoon.","ref":"[1] Bukhari: 992 [2] Sahih. Nasa'i: 1626"},{"id":283,"cat":"witr-and-other","sub":53,"ar":"اَللَّهُمَّ إِنِّي أَسْتَخِيْرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوْبِ اَللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ (وَيُسَمِّي حَاجَتَهُ) خَيْرٌ لِي فِي دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ. [اَللَّهُمَّ] وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِيْ بِهِ","tr":"Allaahumma inni astakhiruka bi'ilmika, Wa astaqdiruka bi-qudratika, Wa as'aluka min fadlika Al-'azim Fa-innaka taqdiru Wala aqdiru, Wa ta'lamu Wala a'lamu, Wa anta 'allamul-ghuyub. Allaahumma, in kunta ta'lamu anna hadhal-amra Khairun li fi dini wa ma'ashi wa'aqibati `Amri, Faqdurhu li wa yas-sirhu li thumma barik li Fih, (Allaahumma) Wa in kunta ta'lamu anna hadhal-amra shar-run li fi dini wa ma'ashi wa'aqibati `Amri Fasrifhu anni was-rifni anhu. Waqdur li al-khaira haithu kana Thumma ardini bih","ref":"Al-Bukhari 7/162, No. 1162, 7390"},{"id":284,"cat":"witr-and-other","sub":53,"ar":"وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَىٰ مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ١٣٥ أُولَٰئِكَ جَزَاؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ الْعَامِلِينَ ١٣٦","tr":"Wallazeena izaa fa'aloo faahishatan aw zalamooo anfusahum zakarullaaha fastaghfaroo lizunoobihim wa man yaghfiruz-zunooba illallaahu wa lam yusirroo 'alaa maa fa'aloo wa hum ya'lamoon. Ulaaa'ika jazaaa'uhum maghfiratum-mir-Rabbihim wa jannaatun tajree min tahtihal-anhaaru khaalideena feehaa; wa ni'ma ajrul-'aamileen.","ref":"Sahih (Albani). Abu Dawud: 1521"},{"id":285,"cat":"grave-funeral","sub":54,"ar":"اَللَّهُمَّ اغْفِرْ لَهُ وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِيْنَ وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِيْنَ وَافْسَحْ لَهُ فِي قَبْرِهِ وَنَوِّرْ لَهُ فِيهِ","tr":"Alla-humma'gfir lahu (person's name), warfa'a darajatahu fil mahdiyin, wa'khlufhu fi 'aqibihi fil ga-birin, wagfir lana wa lahu ya rabbal' a-lamin, wafsa'ah lahu fi qabrihi, wa nau-wir lahu fihi","ref":"Muslim: 920"},{"id":287,"cat":"grave-funeral","sub":55,"ar":"بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُوْلِ اللَّهِ (صلى الله عليه وسلم)","tr":"Bismillaahi wa 'alaa sunnati Rasulillaah","ref":"Sahih. Abu Dawud: 3213"},{"id":288,"cat":"grave-funeral","sub":55,"ar":"بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُوْلِ اللَّهِ","tr":"Bismillaahi wa 'alaa millati Rasoolillaah","ref":"Sahih. Ibn Majah: 1550"},{"id":289,"cat":"grave-funeral","sub":55,"ar":"بِسْمِ اللَّهِ وَفِي سَبِيلِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ","tr":"Bismillahi wa fi sabilillahi wa 'ala millati rasoolillah (ﷺ)","ref":"Sahih. Ibn Majah: 1270"},{"id":290,"cat":"grave-funeral","sub":56,"ar":"اَلسَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِيْنَ وَالْمُسْلِمِيْنَ إِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُوْنَ أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ","tr":"As-salamu 'alaykum ahlad diyari min al-mu'minina wal-muslimin, inna In sha' Allahu bikum lahikun, as-alullaha lana walakumul 'afiyah","ref":"Muslim: 975"},{"id":291,"cat":"grave-funeral","sub":56,"ar":"اَلسَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِيْنَ وَالْمُسْلِمِيْنَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِيْنَ مِنَّا وَالْمُسْتَأْخِرِيْنَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ","tr":"As-salamu 'ala ahlid diya-ri minal mu’minin wal muslimin, wa yarhamullahul mustaq’dimina minna-wal mustakhirin, wa inna- insa allahu bikum lala-’hiqun","ref":"Sahih. Mishkatul Masabih: 1767"},{"id":292,"cat":"grave-funeral","sub":56,"ar":"اَلسَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِيْنَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُوْنَ","tr":"As-salamu 'alaikum dara qaumin mu’minin, wa inna-insha- allahu bikum la-‘hikun","ref":"Muslim: 249"},{"id":293,"cat":"grave-funeral","sub":56,"ar":"اَلسَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِيْنَ وَأَتَاكُمْ مَا تُوعَدُونَ غَدًا مُؤَجَّلُونَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ اَللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ","tr":"As-salamu 'alaikum da-ra kaumin mu’minin, wa ata-kum ma-tu’aadun ‘gadan muajjalun, wa inna-insha- allahu bikum la-’hikun. Alla-humma’gfir liahli baki‘eil garqad.","ref":"Muslim: 974"},{"id":294,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا وَشَاهِدِنَا وَغَائِبِنَا اَللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِيمَانِ وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِسْلَامِ اَللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تُضِلَّنَا بَعْدَهُ","tr":"Allahum-maghfir lihayyinaa, wa mayyitinaa, wa sagheerinaa wa kabeerinaa, wa thakarinaa wa 'unthaanaa, wa shaahidinaa, wa ghaa'ibinaa. Allaahumma man 'ahyaytahu minnaa fa'ahyihi 'alal-'Imaan, wa man tawaffaytahu minnaa fatawaffahu 'alal-'Islam, Allaahumma laa tahrimnaa 'ajrahu wa laa tudhillanaa ba'dahu","ref":"Sahih (Albani). Abu Dawud: 3201"},{"id":295,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ وَأَكْرِمْ نُزُلَهُ وَوَسِّعْ مُدْخَلَهُ وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ وَأَدْخِلْهُ الْجَنَّةَ وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ [وَعَذَابِ النَّارِ]","tr":"Allahum-maghfir lahu warhamhu, wa 'aafihi, wa'fu 'anhu, wa 'akrim nuzulahu, wa wassi' mudkhalahu, waghsilhu bilmaa'i waththalji walbarad, wa naqqihi minal-khataayaa kamaa naqqaytath-thawbal-'abyadha minad-danas, wa 'abdilhu daaran khayran min daarihi, wa 'ahlan khayran min 'ahlihi, wa zawjan khayran min zawjihi, wa 'adkhilhul-jannata, wa 'a'idhhu min 'adhaabil-qabr (wa 'adhaabin-naar)","ref":"Muslim: 963"},{"id":296,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ (إِنَّهُ) عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُوْلُكَ وَأَنْتَ أَعْلَمُ بِهِ اَللَّهُمَّ إِنْ كَانَ مُحْسِنًا فَزِدْ فِي إِحْسَانِهِ وَإِنْ كَانَ مُسِيْئًا فَتَجَاوَزْ عَنْ سَيِّئَاتِهِ اَللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تَفْتِنَّا بَعْدَهُ","tr":"Alla-humma, (innahu) ‘abduka, wabnu‘ 'abdika, wabnu amatika, ka-na yashhadu an laa ilaaha illa anta, wa anna mu’hmmadan ‘abduka wa rasooluka, wa aanta a'laamu bihi. Alla-humma, in kaana mu'hhsinan fajid fi e'hsaa-nihi, wa in ka-na musi-an fataja-waz ‘an saiyyi-aa-tihi. Alla-humma laa-ta'harimna-ajrahu, wala-taftinna ba'adahu","ref":"Sahih Mawkuf (Albani). Al-Muwatta: 539"},{"id":297,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ اِحْتَاجَ إِلَى رَحْمَتِكَ وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ إِنْ كَانَ مُحْسِنًا فَزِدْ فِي حَسَنَاتِهِ وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزْ عَنْهُ","tr":"Allaahumma 'abduka wabnu 'amatika ihtaaja 'ilaa rahmatika, wa 'Anta ghaniyyun 'an 'adhaabihi, 'in kaana mu'hsinan fazid fee hasanaatihi, wa 'in kaana musee'an fatajaawaz 'anhu","ref":"Sahih (Albani). Al-Hakim: 1/359"},{"id":298,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ إِنَّ (فُلَانَ بْنَ فُلَانٍ) فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ اَللَّهُمَّ فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","tr":"Allaahumma 'inna (fulanabna fulan) fee dhimmatika, wa habli jiwaarika, faqihi min fitnatil-qabri wa 'adhaabin-naari, wa 'Anta 'ahlul-wafaa'i walhaqq. Allaahumma Faghfir lahu warhamhu 'innaka 'Antal-Ghafoorur-Raheem.","ref":"Sahih. Abu Dawud: 3202"},{"id":299,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا وَعَافِهَا وَاعْفُ عَنْهَا وَأَكْرِمْ نُزُلَهَا وَوَسِّعْ مُدْخَلَهَا وَاغْسِلْهَا بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ وَنَقِّهَا مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ وَأَبْدِلْهَا دَارًا خَيْرًا مِنْ دَارِهَا وَأَهْلًا خَيْرًا مِنْ أَهْلِهَا وَزَوْجًا خَيْرًا مِنْ زَوْجِهَا وَأَدْخِلْهَا الْجَنَّةَ وَأَعِذْهَا مِنْ عَذَابِ الْقَبْرِ [عَذَابِ النَّارِ]","tr":"Allahum-maghfir laha warhamha, wa 'aafiha, wa'fu 'anha, wa 'akrim nuzulaha, wa wassi' mudkhalaha, waghsilha bilmaa'i waththalji walbarad, wa naqqiha minal-khataayaa kamaa naqqaytath-thawbal-'abyadha minad-danas, wa 'abdilha daaran khayran min daariha, wa 'ahlan khayran min 'ahliha, wa zawjan khayran min zawjiha, wa 'adkhilhal-jannata, wa 'a'idh-ha min 'adhaabil-qabr [or, 'adhaabin-naar instead of 'adhaabil-qabr].","ref":"Muslim: 963"},{"id":300,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ (إِنَّهَا) أَمَتُكَ وَبِنْتُ عَبْدِكَ وَبِنْتُ أَمَتِكَ كَانَتْ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُوْلُكَ وَأَنْتَ أَعْلَمُ بِهِ اَللَّهُمَّ إِنْ كَانَتْ مُحْسِنَةً فَزِدْ فِي إِحْسَانِهَا وَإِنْ كَانَتْ مُسِيْئَةً فَتَجَاوَزْ عَنْ سَيِّئَاتِهَا اَللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهَا وَلَا تَفْتِنَّا بَعْدَهَا","tr":"Alla-humma, (innaha) ‘amatuka, wa bintu 'abdika, wa bintu amatika, kaanat yashhadu an laa ilaaha illaa anta, wa anna mu’hammadan ‘abduka wa rasooluka, wa aanta a’lamu bihi. Alla-humma, in kaanat mu'hsinatan fajid fi ehsaa-niha, wa in kaanat musi-atan fataja-waz ‘an saiyyi-aa-tiha. Alla-humma laa-ta'harimna-ajraha, wala-taftinna ba'adaha.","ref":"Sahih Mawkuf (Albani). Al-Muwatta: 539"},{"id":301,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ أَمَتُكَ وَبِنْتُ أَمَتِكَ اِحْتَاجَتْ إِلَى رَحْمَتِكَ وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهَا إِنْ كَانَتْ مُحْسِنَةً فَزِدْ فِي حَسَنَاتِهَا وَإِنْ كَانَتْ مُسِيئَةً فَتَجَاوَزْ عَنْهَا","tr":"Allaahumma ‛amatuka wabintu ‛amatika, i’htaajat ilaa ra’hmatika, wa anta ghaniyyun ‛an ‛adhaabiha, in kaanat mu’hsinatan fazid fee ‘hasanaatiha, wa in kaanat musee’atan fa tajaawaz ‛anha","ref":"Sahih (Albani). Al-Hakim: 1/359"},{"id":302,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ إِنَّ (فُلَانَةَ بِنْتُ فُلَانٍ) فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ اَللَّهُمَّ فَاغْفِرْ لَهَا وَارْحَمْهَا إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","tr":"Allaahumma 'inna (fulanata bintu fulan) fee dhimmatika, wa habli jiwaarika, faqihi min fitnatil-qabri wa 'adhaabin-naari, wa 'Anta 'ahlul-wafaa'i walhaqq. Allaahumma faghfir laha warhamha 'innaka 'Antal-Ghafoorur-Raheem","ref":"Sahih. Abu Dawud: 3202"},{"id":303,"cat":"grave-funeral","sub":57,"ar":"اَللَّهُمَّ أَنْتَ رَبُّهَا وَأَنْتَ خَلَقْتَهَا وَأَنْتَ هَدَيْتَهَا لِلْإِسْلَامِ وَأَنْتَ قَبَضْتَ رُوْحَهَا وَأَنْتَ أَعْلَمُ بِسِرِّهَا وَعَلَانِيَتِهَا جِئْنَا شُفَعَاءَ فَاغْفِرْ لَهَا","tr":"Alla-humma, anta rabbuhaa, wa anta khalaqtahaa, wa anta hadaitahaa lil islaam, wa anta qabadta ru'hahaa, wa anta a'lamu bisirriha wa 'ala-niyatihaa, ji'na shufa'a-a fagfir laha","ref":"Hasan (Ibn Hajar). Ar-rabbaniyah 4/176"},{"id":304,"cat":"grave-funeral","sub":58,"ar":"اَللَّهُمَّ اجْعَلْهُ فَرَطًا وَذُخْرًا لِوَالِدَيْهِ وَشَفِيعًا مُجَابًا اَللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا وَأَعْظِمْ بِهِ أُجُورَهُمَا وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ اَللَّهُمَّ اغْفِرْ لِأَسْلَافِنَا وَأَفْرَاطِنَا وَمَنْ سَبَقَنَا بِالْإِيمَانِ","tr":"Allahum-maj'alhu faratan wa dhukhran liwaalidayhi, wa shafee'an mujaaban. Allaahumma thaqqil bihi mawaazeenahumaa wa 'a'dhim bihi 'ujoorahumaa, wa 'alhiqhu bisaalihil-mu'mineen, waj'alhu fee kafaalati 'Ibraaheema, wa qihi birahmatika 'adhaabal-jaheem, wa 'abdilhu daaran khayran min daarihi, wa 'ahlan khayran min 'ahlihi, Allahum-maghfir li'aslaafinaa, wa 'afraatinaa wa man sabaqanaa bil'eemaan.","ref":"See Al-Mughni, Lee Ibn Kudama, 3/416; See also Ad-Durusul Muhimmah Li ‘Ammatil Ummah, Lish Sheikh Abdil Aziz Ibn Abdillah Ibn Baz, Rahemahullah, p. 15."},{"id":305,"cat":"grave-funeral","sub":58,"ar":"اَللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ الْقَبْرِ","tr":"Allaahumma 'a'idh-hu min 'adhaabil-qabr","ref":"Sahih (Shu'aib al-Arnaut). Al-Muwatta: 540"},{"id":306,"cat":"grave-funeral","sub":58,"ar":"اَللَّهُمَّ اجْعَلْهُ لَنَا سَلَفًا وَّفَرَطًا وَّأَجْرًا","tr":"Allahum-maj'alhu lanaa salafan, wa faratan, wa 'ajran","ref":"Mawquf Hasan (Albani). Ahkamul-Jana'iz, 160 Page"},{"id":307,"cat":"grave-funeral","sub":58,"ar":"اَللَّهُمَّ اغْفِرْ لَهُ وَثَبِّتْهُ","tr":"Allahum-maghfir lahu wa thabbithu","ref":"Sahih. Abu Dawud: 3221"},{"id":308,"cat":"grave-funeral","sub":58,"ar":"إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى وَكُلٌّ عِنْدَهُ بِأَجَلٍ مُسَمًّى","tr":"Inna lillaahi maa 'akhadha, wa lahu maa 'a'taa, wa kullun 'indahu bi'ajalin musamma","ref":"Bukhari: 7377"},{"id":309,"cat":"grave-funeral","sub":58,"ar":"أَعْظَمَ اللَّهُ أَجْرَكَ وَأَحْسَنَ عَزَاءَكَ وَغَفَرَ لِمَيِّتِكَ","tr":"A'dhamAllahu 'ajraka, wa 'ahsana 'azaa'aka wa ghafara limayyitik.","ref":"Al-Adhkaar lin Nawawi P. 126"},{"id":310,"cat":"fasting","sub":59,"ar":"اَللَّهُمَّ إِنَّكَ عَفُوٌّ (كَرِيْمٌ) تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","tr":"Allaahumma innaka `Afuwwun [Karimun], tu'hibbul-`afwa fa`fu `annī.","ref":"Sahih (Albani). Tirmidhi: 3513"},{"id":312,"cat":"fasting","sub":59,"ar":"اَللَّهُمَّ أَهْلِلْهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيْمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ رَبِّيْ وَرَبُّكَ اللَّهُ","tr":"Allaahumma ahlilhu `alaina bil-yumni wal-iman, was-salamati wal-Islam, rabbi wa rabbuk Allah","ref":"Sahih. Tirmidhi: 3451"},{"id":313,"cat":"fasting","sub":59,"ar":"ذَهَبَ الظَّمَاءُ وَابْتَلَّتِ الْعُرُوْقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","tr":"Dhahabadh-dhama'u wabtallatil-'urooqu, wa thabatal-'ajru 'inshaa'Allah","ref":"[1] Hasan (Albani). Abu Dawud: 2357 [2] Weak (Albany). Abu Dawud: 2358"},{"id":314,"cat":"fasting","sub":59,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ أَنْ تَغْفِرَ لِي","tr":"Allaahumma 'innee 'as'aluka birahmatikal-latee wasi'at kulla shay'in 'an taghfira lee","ref":"Hasan (Hafiz Ibn Hazar). Takhrijul Adhkar, Sharhul Adhkar: 4/342"},{"id":315,"cat":"fasting","sub":59,"ar":"إِنِّي صَائِمٌ إِنِّي صَائِمٌ","tr":"Innee saa'imun, 'innee saa'imun","ref":"Bukhari: 1894"},{"id":316,"cat":"fasting","sub":59,"ar":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","tr":"Aftara 'indakumus-saa'imoona, wa 'akala ta'aamakumul-'abraaru, wa sallat 'alaykumul-malaa'ikah.","ref":"Sahih. Abu Dawud: 3854"},{"id":318,"cat":"travel","sub":60,"ar":"اَلْحَمْدُ لِلَّهِ سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِيْنَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُوْنَ اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اَللّهُ أَكْبَرُ (لَا إِلٰهَ إِلَّا أَنْتَ) سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلاَّ أَنْتَ","tr":"Alhamdu lillaah. Subhaanal-ladhee sakhkhara lanaa haadhaa wa maa kunnaa lahu muqrineen. Wa 'innaa 'ilaa Rabbinaa lamunqaliboon. Alhamdu lillaah, alhamdu lillaah, alhamdu lillaah, Allahu 'Akbar, Allahu 'Akbar, Allahu 'Akbar, (laa ilahaa 'illaa 'Anta) subhaanaka 'innee dhalamtu nafsee faghfir lee, fa'innahu laa yaghfirudh-dhunooba 'illaa 'Anta","ref":"Sahih (Albani). Tirmidhi: 3446"},{"id":319,"cat":"travel","sub":60,"ar":"اَللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ سُبْحَانَ الَّذِيْ سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِيْنَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُوْنَ اَللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى اَللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ اَللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيْفَةُ فِي الْأَهْلِ اَللَّهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوْءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ","tr":"Allahu 'Akbar, Allahu 'Akbar, Allahu 'Akbar. Subhaanal-lathee sakhkhara lanaa haadhaa wa maa kunnaa lahu muqrineen. Wa 'innaa 'ilaa Rabbinaa lamunqaliboon. Allaahumma 'innaa nas'aluka fee safarinaa haadhal-birra wattaqwaa, waminal-'amali maa tardhaa, Allaahumma hawwin 'alaynaa safaranaa haadhaa watwi 'annaa bu'dahu, Allaahumma 'Antas-saahibu fis-safari, walkhaleefatu fil-'ahli, Allaahumma 'innee 'A'oodhu bika min wa'thaa'is-safari, wa ka-'aabatil-mandhari, wa soo'il-munqalabi fil-maali wal 'ahli","ref":"Muslim: 1342"},{"id":320,"cat":"travel","sub":60,"ar":"أَسْتَوْدِعُكَ اللَّهَ الَّذِيْ لَا تَضِيْعُ وَدَائِعُهُ","tr":"Astawdi'ukAllahal-ladhee laa tadhee'u wadaa'i'uhu","ref":"Sahih (Albani). Ibn Majah: 2825"},{"id":321,"cat":"travel","sub":60,"ar":"أَسْتَوْدِعُ اللَّهَ دِيْنَكَ وَأَمَانَتَكَ وَخَوَاتِيْمَ عَمَلِكَ","tr":"Astawdi'ullaaha deenaka, wa 'amaanataka, wa khawaateema 'amalika","ref":"Sahih (Albani). Tirmidhi: 3443"},{"id":322,"cat":"travel","sub":60,"ar":"زَوَّدَكَ اللَّهُ التَّقْوَى وَغَفَرَ لَكَ ذَنْبَكَ وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ","tr":"Zawwadakal-laahut-taqwaa, wa ghafara thanbaka, wa yassara lakal-khayra haythu maa kunta","ref":"Hasan. Tirmidhi: 3444"},{"id":324,"cat":"travel","sub":60,"ar":"اَللَّهُمَّ رَّبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ وَرَبَّ الْأَرَضِيْنَ السَّبْعِ ومَا أَقْلَلْنَ ورَبَّ الشَّيَاطِيْنِ ومَا أَضْلَلْنَ ورَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ وَخَيْرَ أَهْلِهَا (وَخَيْرَ مَا فِيهَا) وَنَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا وشَرِّ مَا فِيهَا","tr":"Allaahumma Rabbas-samaawaatis-sab'i wa maa 'adhlalna, wa Rabbal-'aradheenas-sab'i wa maa 'aqlalna, wa Rabbash-shayaateeni wa maa 'adhlalna, wa Rabbar-riyaahi wa maa tharayna. 'As'aluka khayra haathihil-qaryati wa khayra 'ahlihaa, (wa khayra maa feehaa), wa na‛oodhu bika min sharrihaa, wa sharri 'ahlihaa, wa sharri maa feehaa","ref":"Hasan Ligairihi (Albani). Sahih Ibn Khuzaimah: 2565"},{"id":325,"cat":"travel","sub":60,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِهَا وَخَيْرِ أَهْلِهَا وَأَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا","tr":"Allaahumma inni As'aluka min khayrihaa wa khayri 'ahlihaa wa 'a'oodhu bika min sharrihaa, wa sharri 'ahlihaa","ref":"Sahih (Albani). Tirmidhi: 3449"},{"id":327,"cat":"travel","sub":60,"ar":"بِسْمِ اللَّهِ","tr":"Bismillaah","ref":"Sahih. Abu Dawud: 4982"},{"id":329,"cat":"travel","sub":60,"ar":"سَمِعَ سَامِعٌ بِحَمْدِ اللَّهِ وَحُسْنِ بَلَائِهِ عَلَيْنَا رَبَّنَا صَاحِبْنَا وَأَفْضِلْ عَلَيْنَا عَائِذًا بِاللَّهِ مِنَ النَّارِ","tr":"Sami'a saami'un bihamdillaahi wa husni balaa'ihi 'alaynaa. Rabbanaa saahibnaa, wa 'afdhil 'alaynaa 'aa'ithan billaahi minan-naar.","ref":"Muslim: 2718"},{"id":331,"cat":"travel","sub":60,"ar":"بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسٰىهَآ ۚ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ","tr":"Bismillahi majraha wa mursaha inna rabbee laGhafoorur-Raheem","ref":"Surah Hu'd: 41"},{"id":334,"cat":"travel","sub":60,"ar":"اَللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ اَللَّهُمَّ اطْوِ لَنَا الْأَرْضَ وَهَوِّنْ عَلَيْنَا السَّفَرَ","tr":"Allaahumma 'Antas-saahibu fis-safari wal-khaleefatu fil-'ahli, Allaahumma 'innee 'a'oodhu bika min wa'thaa'is-safari, wa kaabatil munqalabi wa su'il manzari fil-ahli wal maali, Allaahummatwi lanal-arda wa hawwin alainas-safara","ref":"Hasan Sahih (Albani). Abu Dawud: 2598"},{"id":335,"cat":"travel","sub":60,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ فِي سَفَرِيْ هَذَا مِنَ الْبِرِّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى اَللَّهُمَّ هَوِّنْ عَلَيْنَا الْمَسِيرَ وَاطْوِ عَنَّا بُعْدَ الْأَرْضِ اَللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اَللَّهُمَّ اصْحَبْنَا فِي سَفَرِنَا وَاخْلُفْنَا فِي أَهْلِنَا","tr":"Allaahumma inni as’aluka fi safari hadha minal-birri wat-taqwa, wa minal-`amali maa tarda. Allaahumma hawwin `alainal-masira, watwi `anna bu`dal-ard. Allaahumma antas-saahibu fis safari wal-khalifatu fil-ahli. Allaahumma ashaabna fi safarina wakhlufna fi ahlina","ref":"Sahih (Albani). Tirmidhi: 3447"},{"id":879,"cat":"travel","sub":60,"ar":"اَللَّهُمَّ اطْوِ لَهُ الْأَرْضَ وَهَوِّنْ عَلَيْهِ السَّفَرَ","tr":"Allahummatwi lahul-arda wa hawwin `alaihis-safar.","ref":"Hasan. Tirmidhi: 3445"},{"id":336,"cat":"hajj-and-umrah","sub":61,"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ","tr":"Labbayk Allaahumma labbayk, labbayka laa shareeka laka labbayk, 'innal-hamda, wanni'mata, laka wal mulk, laa shareeka lak.","ref":"Bukhari, 1549, Muslim 2/841, No. 1184"},{"id":338,"cat":"hajj-and-umrah","sub":61,"ar":"رَبَّنَا اٰتِنَا فِي الدُّنْيَا حَسَنَةً وَّفِي الْاٰخِرَةِ حَسَنَةً وَّقِنَا عَذَابَ النَّارِ","tr":"Rabbanaa 'aatinaa fid-dunyaa hasanatan wa fil-'aakhirati hasanatan wa qinaa 'athaaban-naar","ref":"The hadith is Hasan. Abu Dawud, 1892"},{"id":339,"cat":"hajj-and-umrah","sub":61,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tr":"Laa 'ilaaha 'illAllahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa Huwa 'alaa kulli shay'in Qadeer","ref":"The hadith is Hasan. Tirmidhi, 3585"},{"id":342,"cat":"hajj-and-umrah","sub":61,"ar":"اَللَّهُ أَكْبَرُ","tr":"Allahu 'Akbar","ref":"Bukhari: 1613, 1632"},{"id":345,"cat":"hajj-and-umrah","sub":61,"ar":"إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ","tr":"Inna assafa wal-marwata min shaAAa-iri Allah","ref":"[1] Al-Baqarah: 158 [2] Muslim 2/888, No. 1218; And the verse is verse 158 of Surah Al-Baqara."},{"id":880,"cat":"hajj-and-umrah","sub":61,"ar":"اَللَّهُمَّ اجْعَلْهُ حَجًّا مَّبْرُورًا وَّذَنْۢبًا مَّغْفُوْرًا.","tr":"Allaahummaj alhu habbam mabru’ran wa dhambam maghfura.","ref":"Sahih Sanad. (Shuaib al-Arnaut) Musnad 7/150"},{"id":881,"cat":"hajj-and-umrah","sub":61,"ar":"اَللَّهُمَّ حَجَّةً لَا رِيَاءَ فِيْهَا وَلَا سُمْعَةَ","tr":"Allaahumma hajjatan laa riyaa’a fihaa wa laa sum’ah.","ref":"Sahih lighayrihi (Albani). Sahih Targhib: 1122"},{"id":883,"cat":"hajj-and-umrah","sub":61,"ar":"زَوَّدَكَ اللَّهُ التَّقْوَى وَغَفَرَ ذَۢنْبَكَ وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ","tr":"Zawwadakal-laahut-taqwaa, wa ghafara dhambaka, wa yassara lakal-khayra haythu maa kunta","ref":"Hasan (Albani). Sahihul Jami: 3579"},{"id":884,"cat":"hajj-and-umrah","sub":61,"ar":"رَبِّ اغْفِرْ وَارْحَمْ إِنَّكَ أَنْتَ الأَعَزُّ الأَكْرَمُ","tr":"Rabbighfir warham, innaka antal a’adh-dhul akram.","ref":"Mawquf Sahih (Ibn Hazar). Al Futuhatur Rabbaniyyah: 4/401"},{"id":885,"cat":"hajj-and-umrah","sub":61,"ar":"إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ","tr":"Inna assafa wal-marwata min shaAAa-iri Allah. Abdawu bimaa bada-allahu bihi.","ref":"Muslim: 1218"},{"id":886,"cat":"hajj-and-umrah","sub":61,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيْتُ وَهَوُ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ لَا إِلَهَ إِلَّا اَللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَةُ.","tr":"laa ilaaha illallaahu wahdahu laa sharika lahu, lahul mulku wa lahul hamdu yuh-i wa yumitu wa huwa ‘alaa kulli shayin qadir, laa ilaaha illallaahu wahdahu laa sharika lahu, anjaza wa’dahu wa nasara ‘abdahu, wa hazamal ahzaaba wa-’adah.","ref":"Sahih. Ibn Majah: 2512"},{"id":887,"cat":"hajj-and-umrah","sub":61,"ar":"لَبَّيْكَ اَللَّهمَّ بِحَجَّةٍ (لَبَّيْكَ حَجًّا)","tr":"Labbaika allaahumma bihajjah (labbaika hajja)","ref":"Manasikul Hajj, Albani, 16 p."},{"id":888,"cat":"hajj-and-umrah","sub":61,"ar":"لَبَّيْكَ اللَّهمَّ بِعُمْرَةٍ","tr":"Labbaika allaahumma bi-'Umrah","ref":"Manasikul Hajj, Albani, 16 p."},{"id":889,"cat":"hajj-and-umrah","sub":61,"ar":"اَللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْك السَّلَامُ فَحَيِّنَا رَبَّنَا بِالسَّلَامِ","tr":"Allaahumma antas salaam, wa minkas salaam, fa-hayyinaa rabbanaa bissalaam.","ref":"Hasan (Albani). Bayhaqi: 5/73"},{"id":890,"cat":"hajj-and-umrah","sub":61,"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","tr":"Rabbanaa aatinaa fid-dunyaa hasanataw, wa fil-aakhirati hasanataw, wa qinaa ‘adhaaban-Naar.","ref":"Hasan. Abu Dawud: 1892"},{"id":891,"cat":"hajj-and-umrah","sub":61,"ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ اَللَّهُمَّ إِنَّ هَذَا مِنْكَ وَلَكَ اَللَّهُمَّ تَقَبَّلْ مِنِّي","tr":"Bismillaahi wallaahu akbar, allaahumma inna haadha minka walak, allaahumma taqabbal minni.","ref":"Irwa'ul-Ghalil: 1118"},{"id":348,"cat":"sacrifice","sub":62,"ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اَللَّهُمَّ مِنْكَ وَلَكَ] اَللَّهُمَّ تَقَبَّلْ مِنِّي","tr":"Bismillaahi wAllahu 'Akbar [Allaahumma minka wa laka] Allaahumma taqabbal minnee","ref":"Ahmad 4/400, No. 19586; Abu Dawood, 4/308, No. 5040"},{"id":349,"cat":"sacrifice","sub":62,"ar":"بِسْمِ اللَّهِ اَللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ","tr":"Bismillaahi, Allah-humma Taqabbal min Muhammadin wa Al-i-Muhammadin, wa min Ummati Muhammadin","ref":"Muslim: 1967"},{"id":350,"cat":"sacrifice","sub":62,"ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي","tr":"Bismillah-hi wallahu akbaru haza 'anni wa amman lam udahh-hi min ummati","ref":"Sahih. Abu Dawud: 2810"},{"id":354,"cat":"evil-protection","sub":63,"ar":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَعُوْذُ بِكَ رَبِّ أَن يَّحْضُرُونِ","tr":"Rabbi A‛oodhu bika min hamazatish shayaateen, Wa A‛oodhu bika rabbi ay-yahduroon","ref":"Surah Al-Mu'minun 23: 97-98"},{"id":355,"cat":"evil-protection","sub":63,"ar":"أَعُوْذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْخِهِ وَنَفْثِهِ","tr":"A‛oodhu Billa-Hish Sami’il-‘Alimi Minash Shaytaanir rajeem Min Hamzihi Wa Nafkhihi Wa Nafthihi","ref":"Sahih. Abu Dawud: 775"},{"id":357,"cat":"evil-protection","sub":63,"ar":"أَعُوْذُ بِاللَّهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ وَسُلْطَانِهِ الْقَدِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"A‛oodhu Billaahil ‘Azeem, Wabi Wazhihil Kareem, Wa Sultaanihil Qadeem Minash Shaytaanir rajeem","ref":"Sahih. Abu Dawud: 466"},{"id":358,"cat":"evil-protection","sub":63,"ar":"اَللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"Allaahumma`simni min ash-shaytaanir-rajeem","ref":"Sahih. Ibn Majah: 773"},{"id":359,"cat":"evil-protection","sub":63,"ar":"اَللَّهُمَّ أَجِرْنِيْ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"Allaahumma, ajirni minash Shaytaanir rajeem","ref":"Sahih (Ibn Hibban). Ibn Hibban: 2047"},{"id":361,"cat":"evil-protection","sub":64,"ar":"بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ وَشَكَرْتَ الْوَاهِبَ وَبَلَغَ أَشُدَّهُ وَرُزِقْتَ بِرَّهُ","tr":"BaarakAllahu laka fil-mawhoobi laka, wa shakartal-waahiba, wa balagha 'ashuddahu, wa ruziqta birrahu.","ref":"Sahih (Albani). Abu Dawood: 441"},{"id":362,"cat":"evil-protection","sub":64,"ar":"بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَزَاكَ اللَّهُ خَيْرًا وَرَزَقَكَ اللَّهُ مِثْلَهُ وَأَجْزَلَ اللَّهُ ثَوَابَكَ","tr":"Baarakallahu laka wa baaraka 'alayka, wa jazaakAllahu khayran, wa razaqakAllahu mithlahu, wa 'ajzalallahu thawaabaka","ref":"This is what Imam Nawabi in his Al-Azkar text p. 256/349 mentioned"},{"id":364,"cat":"evil-protection","sub":65,"ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ مِنْ شَرِّ مَا خَلَقَ وَبَرَأَ وَذَرَأَ وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ","tr":"A'oodhu bikalimaatil-laahit-taammaatil-latee laa yujaawizuhunna barrun wa laa faajirum min sharri maa khalaqa, wa bara'a wa dhara'a, wa min sharri maa yanzilu minas-samaa'i, wa min sharri maa ya'ruju feehaa, wa min sharri maa dhara'a fil-'ardhi, wa min sharri ma yakhruju minhaa, wa min sharri fitanil-layli wannahaari, wa min sharri kulli taariqin 'illaa taariqan yatruqu bikhayrin yaa Rahmaan","ref":"Sahih (Albani). Sahih Al-Jami: 74"},{"id":365,"cat":"evil-protection","sub":65,"ar":"قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ","tr":"Qaddar-Allahu wa maa shaa’a fa‛al","ref":"Muslim: 2664"},{"id":366,"cat":"evil-protection","sub":65,"ar":"اَللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","tr":"Allaahumma laa sahla 'illaa maa ja'altahu sahlan wa 'Anta taj'alul-hazna 'ithaa shi'ta sahla","ref":"Sahih (Ibn Hazar Asqalani). Ibn Hibban: 974"},{"id":368,"cat":"evil-protection","sub":65,"ar":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيـمِ","tr":"A'oodhu billaahi minash-Shaytaanir-rajeem","ref":"[1] Bukhari: 3303 [2] Sahih. Abu Dawud: 5103"},{"id":370,"cat":"evil-protection","sub":66,"ar":"آمَنْتُ بِاللَّهِ وَرُسُلِهِ","tr":"Aamantu billaahi wa Rusulihi","ref":"Muslim: 134"},{"id":371,"cat":"evil-protection","sub":66,"ar":"اَللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ","tr":"Allahu 'Ahad. Allahus-Samad. Lam yalid wa lam yoolad. Wa lam yakun lahu kufuwan 'ahad","ref":"Hasan. Abu Dawud: 4722"},{"id":372,"cat":"evil-protection","sub":66,"ar":"هُوَ الْأوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ","tr":"Huwal-'Awwalu wal-'Aakhiru wadh-Dhaahiru wal-Baatinu, wa Huwa bikulli shay'in 'Aleem","ref":"Hasan. Abu Dawud: 5110"},{"id":373,"cat":"evil-protection","sub":67,"ar":"نَعُوذُ بِاللَّهِ مِنْ عَذَابِ النَّارِ نَعُوذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ نَعُوذُ بِاللَّهِ مِنَ الْفِتَنِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ نَعُوذُ بِاللَّهِ مِنْ فِتْنَةِ الدَّجَّالِ","tr":"NA‛oodhu billaahi min ‘adhaabin naar. NA‛oodhu billaahi min ‘adhaabil qabr. NA‛oodhu billaahi minal fitaani maa zahara minhaa wa maa batan. NA‛oodhu billaahi min fitnatid dajjaal","ref":"Sahih Muslim: 2867"},{"id":382,"cat":"forgiveness","sub":69,"ar":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِيْ وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِيْ فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","tr":"Allaahumma anta rabbee laa ilaaha illaa anta, khalaqtanee wa-ana ‘abduka, wa-ana ‘alaa ‘ahdika wawa‘dika mas-tata‘tu, a‘oothu bika min sharri maa sana‘tu, aboo-o laka bini‘matika ‘alayya, wa-aboo-o bithanbee, faghfir lee fa-innahu laa yaghfirudh dhunooba illaa anta","ref":"Bukhari: 6306"},{"id":379,"cat":"forgiveness","sub":70,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ (الْغَفُوْرُ)","tr":"Rabbighfirli Watub Alayya Innaka Antat-Tawwabul- rahim [in another narration there is al-Ghaffur instead of al-Rahim]","ref":"Sahih. Abu Dawud: 1516"},{"id":380,"cat":"forgiveness","sub":70,"ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِيْ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfirulla-hal adhemal-ladhee laa ilaaha illaa huwal hayyul qayyoomu wa atoobu ilayhi","ref":"[1] Sahih (Albani). Abu Dawud: 1517 [2] Sahih (Albani). Tirmidhi: 3579 [3] Muslim: 482 [4] Muslim: 2702"},{"id":381,"cat":"forgiveness","sub":70,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ لَا إِلَهَ إِلَّا اللَّهُ الْعَلِيُّ الْعَظِيمُ سُبْحَانَ اللَّهِ رَبِّ السَّمَوَاتِ السَّبْعِ وَرَبِّ الْعَرْشِ الْعَظِيمِ اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِيْنَ","tr":"Laa ilaha illallaahul halimul karim, laa ilaaha illallaahul ‘aliyyul ‘azim, subhaanallaahi rabbis samawaatis sab’i wa rabbil ‘arshil ‘azim, alhamdu lillaahi rabbil ‘aalamin","ref":"Sahih isnaad (Ahmad Shakir). Musnad Ahmad 2/39"},{"id":920,"cat":"forgiveness","sub":70,"ar":"اَللَّهُمَّ اغْفِرْ لِيْ جِدِّيْ وَهَزْلِيْ وَخَطَئِيْ وَعَمْدِيْ وَكُلُّ ذٰلِكَ عِنْدِيْ","tr":"Allahumm-aghfir li jiddi wa hazli, wa khata'i wa 'amdi, wa kullu dhalika 'indi.","ref":"Sahih (Shuaib al-Arnaut). Ibn Hibban 954"},{"id":921,"cat":"forgiveness","sub":70,"ar":"اَللَّهُمَّ اغْفِرْ لِيْ ذُنُوْبِيْ وَخَطَئِيْ وَعَمْدِيْ","tr":"Allahummagfirli zunubi wa khatayi wa ‘amadi","ref":"Sahih (Albani). Sahih Al-Mawarid 2059"},{"id":383,"cat":"forgiveness","sub":72,"ar":"اِسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا","tr":"Istaghfiroo Rabbakum innahoo kaana Ghaffaaraa.","ref":"Surah Nooh 71:10"},{"id":384,"cat":"forgiveness","sub":72,"ar":"وَتُوبُوٓا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ","tr":"Wa toobooo ilallaahi jamee'an ayyuhal-mu'minoona la'allakum tuflihoon.","ref":"Surah An-Noor 24:31"},{"id":385,"cat":"forgiveness","sub":72,"ar":"يٰٓأَيُّهَا الَّذِينَ ءَامَنُوا تُوبُوٓا إِلَى اللَّهِ تَوْبَةً نَّصُوحًا","tr":"Yaaa ayyuhal-lazeena aamanoo toobooo ilallaahi tawbatan nasoohaa.","ref":"Surah At-Tahrim 66:8"},{"id":386,"cat":"forgiveness","sub":72,"ar":"وَالَّذِينَ إِذَا فَعَلُوا فٰحِشَةً أَوْ ظَلَمُوٓا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلٰى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ","tr":"Wallazeena izaa fa'aloo faahishatan aw zalamooo anfusahum zakarullaaha fastaghfaroo lizunoobihim wa man yaghfiruz-zunooba illallaahu wa lam yusirroo 'alaa maa fa'aloo wa hum ya'lamoon.","ref":"Surah Ali Imran 3:135"},{"id":390,"cat":"marriage","sub":73,"ar":"إِنَّ الْحَمْدَ لِلَّهِ نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ أَشْهَدُ أَنْ لَّا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُّسْلِمُونَ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِّن نَّفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً ۚ وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ ۚ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًۭا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا","tr":"Innal-hamda lillaah nahmaduhu wa nasta‛eenuhu wa nastaghfiruhu, wa na‛oodhu billaahi min shuroori anfusinaa wa min sayyi’aati a‛maalinaa, man yahdih-illaahu fa laa mudilla lah, wa man yudlil fa laa haadiya lah, ash-hadu an laa ilaaha ill-Allaahu, wa ash-hadu anna muhammadan ‛abduhu wa rasooluh Yaa ayyuhal-ladheena aamanut-taqullaaha ‘haqqa tuqaatihi walaa tamootunna illaa wa antum muslimoon yaa ayyuhan-naasut-taqoo rabbakum-ul-ladhee khalaqakum min nafsin wa’hidatin, wa khalaqa minhaa zawjahaa, wa bath-tha minhumaa rijaalan katheeran wanisaa’-an, wat-taqullaahal-ladhee tasaa’aloona bihi wal ar’haam, inn-Allaaha kaana ‛alaykum raqeebaa Yaa ayyuhal-ladheena aamanut-taqullaaha wa qooloo qawlan sadeeda, yusli’h lakum a‛maalakum wa yaghfir lakum dhunoobakum, wa man yuti‛illaaha wa rasoolahu faqad faaza fawz-an ‛azeemaa","ref":"[1] Surah Al Imran : 3:102 [2] Sura An-nisa : 4:1 [3] Suah Al-Ahjab: 33:70-71 Sohih(albani) Timiji : 1105"},{"id":391,"cat":"marriage","sub":74,"ar":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا","tr":"Rabbanaa hab lanaa min azwaajinaa wa zurriyyaatinaa qurrata a'yunin waj'alnaa lil-muttaqeena imaamaa.","ref":"Surah Furqan 25:74"},{"id":392,"cat":"marriage","sub":74,"ar":"بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","tr":"BaarakAllaahu laka, wa baaraka 'alayka, wa jama'a baynakumaa fee khayr","ref":"Sahih (Albani). Abu Dawud: 2130"},{"id":393,"cat":"marriage","sub":74,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ وَأَعُوْذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَهَا عَلَيْهِ","tr":"Allaahumma 'innee 'as'aluka khayrahaa wa khayra ma jabaltahaa 'alayhi wa 'A'oodhu bika min sharrihaa wa min sharri maa jabaltahaa 'alayhi","ref":"Hasan. Abu Dawud: 2160"},{"id":394,"cat":"marriage","sub":74,"ar":"اَللَّهُمَّ بَارِكْ لِي فِي أَهْلِي وَبَارِكْ لِأَهْلِي فِيَّ اَللَّهُمَّ ارْزُقْهُمْ مِنِّي وَارْزُقْنِي مِنْهُمْ اَللَّهُمَّ اجْمَعْ بَيْنَنَا مَا جَمَعْتَ فِي خَيْرٍ وفَرِّقْ بَيْنَنَا إِذَا فَرَّقْتَ فِي خَيْرٍ","tr":"Allaahumma barik li fi ahli, wa barik li ahli fiyya. Allahumar-zuqhum minni, war zuqni minhum. Allahum-majma’ bainana ma jama’ta fi khairin. wa farriq bainana idha far-raqta fi khair","ref":"Sahih (Albani). Adabuj Zifaf: 24"},{"id":395,"cat":"marriage","sub":74,"ar":"بِاسْمِ اللَّهِ اَللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا","tr":"Bismillaahi, Allaahumma jannibnash-Shaytaana, wa jannibish-Shaytaana maa razaqtanaa","ref":"Bukhari: 141"},{"id":396,"cat":"marriage","sub":75,"ar":"بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوْبِ لَكَ وَشَكَرْتَ الْوَاهِبَ وَبَلَغَ أَشُدَّهُ وَرُزِقْتَ بِرَّهُ.","tr":"BaarakAllahu laka fil-mawhoobi laka, wa shakartal-waahiba, wa balagha 'ashuddahu, wa ruziqta birrahu","ref":"This is menioned as a saying of Hasan Al basri Rahimullah. See tuhfatul maodud fi Ibn Qaiiyum, Page. 20"},{"id":397,"cat":"marriage","sub":75,"ar":"بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَزَاكَ اللَّهُ خَيْرًا وَرَزَقَكَ اللَّهُ مِثْلَهُ وَأَجْزَلَ ثَوَابَكَ","tr":"Baarakallahu laka wa baaraka 'alayka, wa jazaakAllahu khayran, wa razaqakAllahu mithlahu, wa 'ajzala thawaabaka","ref":"An-Nawawi Al-Azkar Page. 349. Also see Sahih Azkar fil Nawawi, Salim al Hilali 2/713. For more details, read Az Zikr wa dua Wal Ilaj bir Ruqwa Page. 1/416"},{"id":398,"cat":"family","sub":76,"ar":"رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ ١٢٧ رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ ١٢٨","tr":"Rabbanaa taqabbal minnaa innaka Antas-Samee'ul-'Aleem. Rabbanaa waj'alnaa muslimaini laka wa min zurriyyatinaa ummatan muslimatal-laka wa arinaa manaasikanaa wa tub 'alainaa innaka Antat-Tawwaabur-Raheem.","ref":"Surah Al-Baqarah 2:127-128"},{"id":399,"cat":"family","sub":76,"ar":"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ","tr":"Rabbi hab lee mil-ladunka zurriyyatan tayyibatan innaka Samee'ud-du'aaa'.","ref":"Surah Ali-Imran 3:38"},{"id":401,"cat":"family","sub":76,"ar":"رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","tr":"Rabbir-hamhumaa kamaa rabbayaanee sagheeraa.","ref":"Sura Isra 17:24"},{"id":402,"cat":"family","sub":76,"ar":"رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا","tr":"Rabbanaa aatinaa mil-ladunka rahmatan wa hayyi' lanaa min amrinaa rashadaa.","ref":"Surah Kahf 18:10"},{"id":404,"cat":"family","sub":76,"ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ","tr":"Rabbi awzi'nee an ashkura ni'matakal-lateee an'amta 'alayya wa 'alaa waalidayya wa an a'mala saalihan tardaahu wa adkhilnee birahmatika fee 'ibaadikas-saaliheen.","ref":"Surah Naml 27:19"},{"id":405,"cat":"family","sub":76,"ar":"رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ","tr":"Rabbi hab lee minas-saaliheen.","ref":"Surah As-Saffat 37:100"},{"id":406,"cat":"family","sub":76,"ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي ۖ إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ","tr":"Rabbi awzi'nee an ashkura ni'matakal-lateee an'amta 'alayya wa 'alaa waalidayya wa an a'mala saalihan tardaahu wa aslih lee fee zurriyyatee innee tubtu ilaika wa innee minal-muslimeen.","ref":"Surah Al-Ahqaf 46:15"},{"id":407,"cat":"family","sub":76,"ar":"رَبِّ اجْعَلْ هَـٰذَا الْبَلَدَ آمِنًا وَاجْنُبْنِي وَبَنِيَّ أَن نَّعْبُدَ الْأَصْنَامَ","tr":"Rabbij-'al haazal-balada aaminan wajnubnee wa baniyya an na'budal-asnaam.","ref":"Surah Ibrahim 14:35"},{"id":408,"cat":"family","sub":76,"ar":"وَإِنِّي خِفْتُ الْمَوَالِيَ مِن وَرَائِي وَكَانَتِ امْرَأَتِي عَاقِرًا فَهَبْ لِي مِن لَّدُنكَ وَلِيًّا ٥","tr":"Wa innee khiftul-mawaaliya min waraaa'ee wa kaanatim-ra'atee 'aaqiran fahab lee mil-ladunka waliyyaa.","ref":"Surah Maryam 19:5"},{"id":409,"cat":"family","sub":76,"ar":"رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ ٧ رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ٨ وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ٩","tr":"Rabbanaa wasi'ta kulla shai'ir-rahmatan wa 'ilman faghfir lillazeena taaboo wattaba'oo sabeelaka wa qihim 'azaabal-Jaheem. Rabbanaa wa adkhilhum jannaati 'adninil-latee wa'adtahum wa man salaha min aabaaa'ihim wa azwaajihim wa zurriyyaatihim; innaka Antal-'Azeezul-Hakeem. Wa qihimus-sayyi-aat; wa man taqis-sayyi-aati Yawma'izin faqad rahimtah; wa zaalika huwal-fawzul-'azeem.","ref":"Surah Ghafir 40:7-9"},{"id":411,"cat":"family","sub":76,"ar":"رَبَّنَا لِيُقِيمُوا الصَّلاةَ فَاجْعَلْ أَفْئِدَةً مِنَ النَّاسِ تَهْوِي إِلَيْهِمْ وَارْزُقْهُمْ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ","tr":"Rabbanaa liyuqeemus-Salaata faj'al af'idatam-minan-naasi tahweee ilaihim warzuqhum minath-thamaraati la'allahum yashkuroon.","ref":"Sura Ibrahim 14:37"},{"id":892,"cat":"family","sub":76,"ar":"اَللَّهُمَّ اغْفِرْ لِيْ خَطَايَايَ وَذُنُوبِيْ كُلَّهَا اَللَّهُمَّ انْعِشْنِيْ وَأَحْيِنِيْ وَارْزُقْنِيْ وَاهْدِنِيْ لِصَالِحِ الْأَعْمَالِ وَالْأَخْلَاقِ إِنَّهٗ لَا يَهْدِيْ لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ.","tr":"Allahummaghfir lee khataayaaya wa dhunubi kullahaa, Allahumman ‘ishni wa a’hyini warzuqni wahdini lisaalihil a’maali wal akhlaaqi innahu laa yahdi li’saalihihaa wa laa yathrifu sayyiyaha illaa anta.","ref":"Hasan (Albani). Sahihul Jame 1677"},{"id":412,"cat":"debt","sub":77,"ar":"اَللَّهُمَّ اكْفِنِيْ بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","tr":"Allaahummak-finee bihalaalika 'an haraamika wa 'aghninee bifadhlika 'amman siwaak","ref":"Hasan. Tirmidhi: 3563"},{"id":413,"cat":"debt","sub":77,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","tr":"Allaahumma 'innee 'A'oodhu bika minal-hammi wal-hazani, wal'ajzi wal-kasali, wal-bukhli wal-jubni, wa dhala'id-dayni wa ghalabatir-rijaal","ref":"Bukhari: 2893"},{"id":414,"cat":"debt","sub":77,"ar":"اَللَّهُمَّ مٰلِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ رَحْمَانُ الدُّنْيَا وَالْآخِرَةِ وَرَحِيْمَهُمَا تُعْطِيْهِمَا مَنْ تَشَاءُ وَتَمْنَعُ مِنْهُمَا مَنْ تَشَاءُ ارْحَمْنِيْ رَحْمَةً تُغْنِيْنِيْ بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ","tr":"Allaahumma maalik-al-mulki tu’til-mulka man tashaa’u, wa tanzi‛-ul-mulka mimman tashaa’u, wa tu‛izzu man tashaa’u wa tudhillu man tashaa’u, bi yadik-al-khayru innaka ‛alaa kulli shay’in qadeer, ra'hmaanud-dunyaa wal-aakhirati wa ra'heemahumaa, tu‛teehimaa man tashaa’u, wa tamna‛u minhumaa man tashaa’-ur'hamnee ra'hmatan tughneenee bihaa ‛an ra'hmati man siwaak","ref":"Hasan (Albani). Sahihut Targib: 1821"},{"id":416,"cat":"debt","sub":77,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ وَفِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ وَشَرِّ فِتْنَةِ الْغِنَى وَشَرِّ فِتْنَةِ الْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ اَللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالْبَرَدِ وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَالْهَرَمِ وَالْمَأْثَمِ وَالْمَغْرَمِ","tr":"Allaahumma inni a`udhu bika min fitnatin-nar, wa `adhabin-nar, wa fitnatil-qabr, wa `adhabil-qabr, wa sharri fitnatil-ghina, wa sharri fitnatil-faqr, Allaahumma inni a`udhu bika min fitnatil- masihid-dajjal. Allaahummaghsil qalbi bi-ma’ith-thalji wal-barad, wa naqqi qalbi minal-khataaya kamaa naqqaitath-thawbal-abyada minad-danas, wa ba`id baini wa baina khaatayaaya kamaa ba`adta bainal-mashriqi wal maghrib, Allaahumma inni a`udhu bika min al-kasali wal-harami wal-ma’thami wal-maghram","ref":"Sahih. Tirmidhi: 3495"},{"id":417,"cat":"debt","sub":77,"ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ فَالِقَ الْحَبِّ وَالنَّوَى وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","tr":"Allaahumma Rabbas-samaawaatis-sab'i, wa Rabbal-Ardi, wa Rabbal-'Arshil-'Adheem, Rabbanaa wa Rabba kulli shay'in, faaliqal-habbi wannawaa, wa munzilat-Tawraati wal-'Injeeli, wal-Furqaan, 'A'oodhu bika min sharri kulli shay'in 'Anta 'aakhithun binaasiyatihi. Allaahumma 'Antal-'Awwalu falaysa qablaka shay'un, wa 'Antal-'Aakhiru falaysa ba'daka shay'un, wa 'Antadh-Dhaahiru falaysa fawqaka shay'un, wa 'Antal-Baatinu falaysa doonaka shay'un, iqdhi 'annad-dayna wa 'aghninaa minal-faqr","ref":"Muslim: 2713, Sahih. Tirmidhi: 3481"},{"id":418,"cat":"debt","sub":77,"ar":"اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَغَلَبَةِ الْعَدُوِّ وَشَمَاتَةِ الْأَعْدَاءِ","tr":"Allaahumma inni A‛oodhu bika min ghalabatid-daini, wa ghalabatil-'aduwwi, wa shamaatatil-a'da'i","ref":"Sahih. Nasa'i: 5475"},{"id":419,"cat":"debt","sub":77,"ar":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالْأَدَاءُ","tr":"BaarakAllahu laka fee 'ahlika wa maalika, 'innamaa jazaa'us-salafil-hamdu wal' adaa'u","ref":"Sahih. Nasa'i: 4683"},{"id":458,"cat":"debt","sub":77,"ar":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ","tr":"BaarakAllahu laka fee 'ahlika wa maalika","ref":"Bukhari: 3780, 5167"},{"id":899,"cat":"debt","sub":77,"ar":"أَوْفَيْتَنِيْ أَوْفَى اللَّهُ بِكَ","tr":"Aw’faitani awfallahu bik","ref":"Bukhari: 2305"},{"id":420,"cat":"anxiety","sub":78,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيْمُ الْحَلِيْمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيْمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ","tr":"Laa 'ilaaha 'illAllaahul-'Adheemul-Haleem, laa 'ilaaha 'illAllaahu Rabbul-'Arshil-'Adheem, laa 'ilaaha 'illAllaahu Rabbus-samaawaati wa Rabbul-'ardi wa Rabbul-'Arshil-Kareem","ref":"[1] Bukhari: 6346 [2] Sahih Ibn Hibban 3/147, Musnad Ahmad 194"},{"id":421,"cat":"anxiety","sub":78,"ar":"اَللَّهُ اَللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","tr":"Allahu Allahu Rabbee laa 'ushriku bihi shay'an.","ref":"Abu Dawud : 1525"},{"id":422,"cat":"anxiety","sub":78,"ar":"اَللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُــــلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي وَنُورَ صَدْرِي وَجَلَاءَ حُزْنِي وَذَهَابَ هَمِّي","tr":"Allaahumma 'innee 'abduka, wabnu 'abdika, wabnu 'amatika, naasiyatee biyadika, maadhin fiyya hukmuka, 'adlun fiyya qadhaa'uka, 'as'aluka bikulli ismin huwa laka, sammayta bihi nafsaka, 'aw 'anzaltahu fee kitaabika, 'aw 'allamtahu 'ahadan min khalqika, 'awista'tharta bihi fee 'ilmil-ghaybi 'indaka, 'an taj'alal-Qur'aana rabee'a qalbee, wa noora sadree, wa jalaa'a huznee, wa thahaaba hammee","ref":"Sahih (Albani) Silsila Sahihah: 1/337"},{"id":424,"cat":"anxiety","sub":78,"ar":"اَللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ وَأَصْلِحْ لِي شَأْنِي كُلَّهُ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allaahumma rahmataka 'arjoo falaa takilnee 'ilaa nafsee tarfata 'ayen, wa 'aslih lee sha'nee kullahu, laa 'ilaaha 'illaa 'Anta","ref":"[1] Hasan. Abu Dawud: 5090 [2] Bukhari: 2893"},{"id":425,"cat":"anxiety","sub":78,"ar":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","tr":"Laa 'ilaaha 'illaa 'Anta subhaanaka 'innee kuntu minadh-dhaalimeen","ref":"[1] Surah Ambia: 87 [2] At-Tirmidhi: 3505"},{"id":426,"cat":"anxiety","sub":78,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا","tr":"Alhamdu lillaahil-lathee 'aafaanee mimmab-talaaka bihi wa fadhdhalanee 'alaa katheerin mimman khalaqa tafdheela","ref":"Sahih. Tirmidhi: 3432"},{"id":427,"cat":"anxiety","sub":78,"ar":"يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ","tr":"Ya ‘hayyi-u ya qayyumu bira’hmatika astagith","ref":"Hasan (Albani). Tirmidhi: 3524"},{"id":893,"cat":"anxiety","sub":78,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ اَللَّهُمَّ عِنْدَكَ أَحْتَسِبُ مُصِيْبَتِيْ فَأْجُرْنِيْ فِيْهَا وَأَبْدِلْنِيْ مِنْهَا خَيْرًا.","tr":"Inna lillaahi wa inna ilayhi raaji`un, Allaahumma `indaka ahtasibu musibati fa’jurni fihaa wa abdilni minhaa khair.","ref":"Sahih. Tirmidhi: 3511"},{"id":894,"cat":"anxiety","sub":78,"ar":"اَللَّهُمَّ رَادَّ الضَّالَّةِ وَهَادِيَ الضَّلَالَةِ أَنْتَ تَهْدِيْ مِنَ الضَّلَالَةِ اُرْدُدْ عَلَيَّ ضَالَّتِيْ بِقُدْرَتِكَ وَسُلْطَانِكَ فَإِنَّهَا مِنْ عَطَائِكَ وَفَضْلِكَ.","tr":"Allaahumma raaddad daallati wa haadiyad dalaalati anta tahdi minad dalaalah, urdud alayya daallati biqudratika wa sultaanika fainnahaa min ataaika wa fadlik.","ref":"Mauquf Hasan (Bayhaqi). Ad-Dawatul Kabir 2/18"},{"id":895,"cat":"anxiety","sub":78,"ar":"لَا إِلٰهَ إِلَّا اللَّهُ الْحَلِيْمُ الْكَرِيْمُ سُبْحَانَ اللَّهِ رَبِّ السَّمٰوَاتِ السَّبْعِ وَرَبِّ الْعَرْشِ الْعَظِيْمِ اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِيْنَ","tr":"Laa ilaha illallaahul halimul karim, subhaanallaahi rabbis samawaatis sab’i wa rabbil ‘arshil ‘azim, alhamdu lillaahi rabbil ‘aalamin.","ref":"Hasan (Shuaib al-Arnaut). Takhrij Siyaru ‘Alam An-Nubala 16/551"},{"id":428,"cat":"danger","sub":79,"ar":"قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ","tr":"Qadarullaahi wa maa shaa'a fa'al","ref":"Muslim: 2664"},{"id":430,"cat":"danger","sub":80,"ar":"اَللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ","tr":"Allaahumma 'innaa naj'aluka fee nuhoorihim wa nA'oodhu bika min shuroorihim","ref":"Sahih. Abu Dawud: 1537"},{"id":431,"cat":"danger","sub":80,"ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيْمِ كُنْ لِي جَارًا مِنْ فُلَانِ بْنِ فُلَانٍ وَأَحْزَابِهِ مِنْ خَلَائِقِكَ (وَمِنْ شَرِّ خَلْقِكَ كُلِّهِمْ جَمِيْعًا) أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى عَزَّ جَارُكَ وَجَلَّ ثَنَاؤُكَ وَلَا إِلٰهَ إِلَّا أَنْتَ","tr":"Allaahumma Rabbas-samawaatis-sab'i, wa Rabbal-'Arshil-'Adheem, kun lee jaaran min [here you mention the person's name], wa 'ahzaabihi min khalaa'iqika, (wa min sharri khalqika kullihim jami'an) 'an yafruta 'alayya 'ahadun minhum 'aw yatghaa, 'azza jaaruka, wajalla thanaa'uka, wa laa 'ilaaha 'illaa 'Anta","ref":"Sahih (Albani). Sahih Al-Targhib: 2237, Adabul Mufrad: 707"},{"id":432,"cat":"danger","sub":80,"ar":"اَللَّهُمَّ اكْفِنِيْهِمْ بِمَا شِئْتَ","tr":"Allaahummak-fineehim bimaa shi'ta","ref":"Muslim 4/2300, 3005"},{"id":433,"cat":"danger","sub":81,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِنْهَا","tr":"Innaa lillaahi wa 'innaa 'ilayhi raaji'oon, Allaahumma'-jurni fee museebatee wa 'akhlif lee khayran minhaa","ref":"Muslim: 918"},{"id":434,"cat":"danger","sub":81,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِيْ مِمَّا ابْتَلَاكَ بِهِ وَفَضَّلَنِيْ عَلَى كَثِيْرٍ مِمَّنْ خَلَقَ تَفْضِيْلًا","tr":"Al-hamdu lil-laahil-ladhee ‘aafaanee mim-mab-ta-laaka bihi, wa fad-dala-nee ‛alaa kathee-rin mim-man khalaqa taf-deelaa","ref":"Sahih. Tirmidhi: 3431, 3432"},{"id":435,"cat":"danger","sub":81,"ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","tr":"A‛oodhu bikalimaatil-laahit-taammaati min sharri maa khalaq","ref":"Muslim: 2709"},{"id":436,"cat":"danger","sub":81,"ar":"يَا حَيُّ يَا قَيُّوْمُ","tr":"Yaa Hayyu yaa Qayyoom","ref":"Hasan (Haisami). Tabarani: 4817"},{"id":437,"cat":"danger","sub":81,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيْمُ الْحَلِيْمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيْمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","tr":"Laa 'ilaaha 'illAllaahul-'Adheemul-Haleem, laa 'ilaaha 'illAllaahu Rabbul-'Arshil-'Adheem, laa 'ilaaha 'illAllaahu Rabbus-samaawaati wa Rabbul-'ardhi wa Rabbul-'Arshil-Kareem","ref":"Bukhari 7431"},{"id":438,"cat":"danger","sub":81,"ar":"اَللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","tr":"Allahu Rabbee laa 'ushriku bihi shay'an","ref":"Sahih. Ibn Majah: 3882"},{"id":439,"cat":"danger","sub":81,"ar":"اَللَّهُمَّ أَنْتَ عَضُدِي وَأَنْتَ نَصِيرِي بِكَ أَحُولُ وَبِكَ أَصُولُ وَبِكَ أُقَاتِلُ","tr":"Allaahumma 'Anta 'adhudee, wa 'Anta naseeree, bika 'a'hoolu, wa bika 'asoolu, wa bika 'uqaatilu","ref":"Hasan Gharib. Abu Dawud: 2632"},{"id":440,"cat":"danger","sub":81,"ar":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ","tr":"HasbunAllahu wa ni'amal-wakeel","ref":"Bukhari: 4563"},{"id":441,"cat":"danger","sub":81,"ar":"اَللَّهُ أَكْبَرُ اَللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعًا اَللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ أَعُوْذُ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ إِلَّا بِإِذْنِهِ مِنْ شَرِّ عَبْدِكَ فُلَانٍ وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ مِنَ الْجِنِّ وَالْإِنْسِ اَللَّهُمَّ كُنْ لِي جَارًا مِنْ شَرِّهِمْ جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ وَتَبَارَكَ اسْمُكَ وَلَا إِلَهَ غَيْرُكَ","tr":"Allahu 'Akbar, Allahu 'a'azzu min khalqihi jamee'an, Allahu 'a'azzu mimmaa 'akhaafu wa 'ahdharu, 'A'oodhu billaahil-ladhee laa 'ilaaha 'illaa Huwa almumsikis-samaawaatis-sab'i 'an yaqa'na 'alal-'ardhi 'illaa bi'idhnihi, min sharri 'abdika (name of the person), wa junoodihi wa 'atbaa'ihi wa 'ashyaa'ihi, minal-jinni wal'insi, Allaahumma kun lee jaaran min sharrihim, jalla thanaa'uka wa 'azza jaaruka, wa tabaarakasmuka, wa laa 'ilaaha ghayruk","ref":"Sahih. Adabul Mufrad: 708"},{"id":442,"cat":"danger","sub":81,"ar":"اَللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ اِهْزِمِ الْأَحْزَابَ اَللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ","tr":"Allaahumma munzilal-kitaabi, saree'al-hisaabi, ihzimil-'ahzaaba, Allaahummah zimhum wa zalzilhum","ref":"Bukhari: 2818, 2833, 2933"},{"id":443,"cat":"danger","sub":81,"ar":"اَللَّهُمَّ مَتِّعْنِي بِسَمْعِي وَبَصَرِي وَاجْعَلْهُمَا الْوَارِثَ مِنِّي وَانْصُرْنِي عَلَى مَنْ ظَلَمَنِي وَخُذْ مِنْهُ بِثَأْرِي","tr":"Allaahumma matti‛ni bi sam‛i wa basari waj-‛alhumal-waaritha minni, wan-surni ‛alaa man zalamani, wa khudh minhu bi tha’ri","ref":"Sahih. Bukhari, Al-Adabul Mufrad 1/226"},{"id":444,"cat":"danger","sub":81,"ar":"رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ","tr":"Rabbanaa laa taj'alnaa ma'al-qawmiz-zaalimeen.","ref":"Surah A'raf 7:47"},{"id":445,"cat":"danger","sub":81,"ar":"اَللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","tr":"Allaahummak-finee bi 'halaalika ‛an 'haraamika, wa aghninee bi fadlika ‛amman siwaak","ref":"Hasan Gharib. Tirmidhi: 3563"},{"id":447,"cat":"danger","sub":81,"ar":"أُعِيْذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَّهَامَّةٍ وَّمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tr":"U'eethukumaa bikalimaatil-laahit-taammati min kulli shaytaanin wa haammah, wa min kulli 'aynin laammah","ref":"Bukhari: 3371"},{"id":448,"cat":"danger","sub":81,"ar":"لَا إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّى كُنْتُ مِنَ الظَّالِمِيْنَ","tr":"Laa Ilaaha Illaaa Anta Subh’aanaka Innee Kuntu Minaz” Z’aalimeen","ref":"Sahih. Tirmidhi: 3505"},{"id":449,"cat":"danger","sub":81,"ar":"لَا إِلَهَ إِلَّا اللَّهُ","tr":"Laa Ilaaha Illaallah","ref":"Bukhari: 3346"},{"id":896,"cat":"danger","sub":82,"ar":"اَللَّهُمَّ بِكَ أُقَاتِلُ وَبِكَ أُصَاوِلُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Allaahumma bika uqaatilu wabika usaawilu wa laa hawla wa laa quwwata illaa billaah.","ref":"Sahih (Albani). Silsilatul Sahiha: 1061"},{"id":897,"cat":"danger","sub":82,"ar":"اُغْزُوا بِاسْمِ اللَّهِ فِي سَبِيْلِ اللَّهِ قَاتِلُوا مَنْ كَفَرَ بِاللَّهِ اُغْزُوا وَلَا تَغُلُّوا وَلَا تَغْدِرُوا وَلَا تَمْثُلُوا وَلَا تَقْتُلُوا وَلِيْدًا","tr":"Ughzu bismillaahi fi sabilillaahi qaatilu man kafara billaahi. Ughzu wa laa tagullu wa laa tagdiru wa laa tamthulu wa laa taqtulu walida.","ref":"Muslim: 1731"},{"id":900,"cat":"danger","sub":82,"ar":"يَا أَيُّهَا النَّاسُ لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ وَسَلُوْا اللَّهَ الْعَافِيَةَ فَإِذَا لَقِيْتُمُوْهُمْ فَاصْبِرُوْا وَاعْلَمُوْا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ.","tr":"Yaa ayyuhan naas, laa tatamannaw liqaa’al ‘aduyyi wa salullaahal ‘aafiyah, faa idhaa laqitumuhum faasbiru waa’lamu annal jannata tahta zilaalis suyyuf.","ref":"Bukhari: 2966"},{"id":901,"cat":"danger","sub":82,"ar":"اَللَّهُمَّ مُنْزِلَ الْكِتَابِ وَمُجْرِيَ السَّحَابِ وَهَازِمَ الْأَحْزَابِ اِهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ.","tr":"Allaahumma munzilal kitaab, wa muj’riyas sahaab wa haazimal ahzaab, ihzimhum wansurnaa alayhim.","ref":"Bukhari: 2966"},{"id":902,"cat":"danger","sub":82,"ar":"إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِيْنَ","tr":"Inna idhaa nazalnaa bisaahati qawm, fasaa’a sabaahul mundharin.","ref":"Bukhari: 4197"},{"id":451,"cat":"condemnationpraise","sub":83,"ar":"أَحْسِبُ فُلَانًا وَاللَّهُ حَسِيبُهُ وَلَا أُزَكِّي عَلَى اللَّهِ أَحَدًا أَحْسِبُهُ كَذَا وَكَذَا","tr":"Ahsibu fulaanan wAllaahu haseebuhu wa laa 'uzakkee 'alAllaahi 'ahadan ahsibuhu kadha wa kadha","ref":"Bukhari: 2662"},{"id":452,"cat":"condemnationpraise","sub":83,"ar":"اَللَّهُمَّ لَا تُؤَاخِذْنِي بِمَا يَقُولُونَ وَاغْفِرْ لِي مَا لَا يَعْلَمُونَ وَاجْعَلْنِي خَيْرًا مِمَّا يَظُّنُّونَ","tr":"Allaahumma laa tu'aakhidhnee bimaa yaqooloon, waghfir lee maa laa ya'lamoon waj'alnee khayram-mimmaa yadhunnoon","ref":"Sahih. Adabul Mufrad: 589"},{"id":453,"cat":"condemnationpraise","sub":84,"ar":"غَفَرَ اللَّهُ لَكَ","tr":"Ghafar-Allahu lak","ref":"[1] Riyadus Salehin: 1843 [2] Muslim: 2346"},{"id":457,"cat":"condemnationpraise","sub":84,"ar":"أُحِبُّكَ فِي اللَّهِ","tr":"U'hibbuka fill-aah","ref":"Hasan (Albani). Abu Dawud: 5125"},{"id":898,"cat":"condemnationpraise","sub":84,"ar":"أَضْحَكَ اللَّهُ سِنَّكَ","tr":"Adh’haka allahu sinnak","ref":"Bukhari: 3294"},{"id":469,"cat":"manners","sub":86,"ar":"اَلْحَمْدُ لِلَّهِ (عَلَى كُلِّ حَالٍ)","tr":"Alhamdu lillaahi ('alaa kulli haal)","ref":"Sahih. Tirmidhi: 2741"},{"id":470,"cat":"manners","sub":86,"ar":"يَرْحَمُكَ اللَّهُ","tr":"Yarhamuk-Allah","ref":"Bukhari: 1240, 6224"},{"id":471,"cat":"manners","sub":86,"ar":"يَهْدِيْكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ","tr":"Yahdeekum-ullaahu wa yuslihu baalakum","ref":"Sahih. Tirmidhi: 2741"},{"id":472,"cat":"manners","sub":86,"ar":"يَرْحَمُنَا اللَّهُ وَإِيَّاكُمْ وَيَغْفِرُ لَنَا وَلَكُمْ","tr":"yar'hamunallahu wa iyyakum wa yaghfiru lanaa walakum","ref":"Adabul Mufrad: 941"},{"id":473,"cat":"manners","sub":86,"ar":"يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُم","tr":"Yahdeekum-ullaahu wa yuslihu baalakum","ref":"Sahih (Albani). Tirmidhi: 2739"},{"id":474,"cat":"manners","sub":87,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ","tr":"Rabbighfir lee watub 'alayya 'innaka 'Antat-Tawwaabul-Ghafoor","ref":"Sahih. Tirmidhi: 3434"},{"id":475,"cat":"manners","sub":87,"ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","tr":"Subhaanaka Allaahumma wa bihamdika, 'ash-hadu 'an laa 'ilaaha 'illaa 'Anta, 'astaghfiruka wa 'atoobu 'ilayka","ref":"Hasan Sahih. Abu Dawud: 4859"},{"id":476,"cat":"manners","sub":88,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِيْ بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ","tr":"Alhamdu lillaahil-lathee bini'matihi tatimmus-saalihaat","ref":"Hasan. Ibn Majah: 3803"},{"id":477,"cat":"manners","sub":88,"ar":"اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ","tr":"Alhamdu lillaahi 'alaa kulli haal","ref":"Hasan. Ibn Majah: 3803"},{"id":478,"cat":"manners","sub":89,"ar":"أَحْسِبُ فُلَانًا وَاللَّهُ حَسِيْبُهُ وَلَا أُزَكِّيْ عَلَى اللَّهِ أَحَدًا أَحْسِبُهُ كَذَا وَكَذَا","tr":"A’hsibu fulanan wallahu ‘hasiibuhu wa laa ‘uzakkii ‘alAllahi a’hadan a’hsibuhu kaza wa kaza","ref":"Bukhari: 2662"},{"id":479,"cat":"manners","sub":89,"ar":"اَللَّهُمَّ لَا تُؤَاخِذْنِيْ بِمَا يَقُوْلُوْنَ وَاغْفِرْ لِي مَا لَا يَعْلَمُوْنَ (وَاجْعَلْنِيْ خَيْرًا مِمَّا يَظُنُّوْنَ)","tr":"Allaahumma laa tu'aakhidhnee bimaa yaqooloona, waghfir lee maa laa ya'lamoona [waj'alnee khayram-mimmaa yadhunnoon]","ref":"Sahih. Adabul Mufrad: 761, Bracketed part (Shu'abul Iman 4/288)"},{"id":480,"cat":"manners","sub":90,"ar":"اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ","tr":"As-salaamu 'alaykum wara'hmatullaahi wa barakaatuh","ref":"[1] Musnad Ahmad 1430 [2] Sahih Bukhari (Fathul Bari) 1/82 [3] Sahih Bukhari (Fathul Bari) 1/55"},{"id":481,"cat":"manners","sub":90,"ar":"وَعَلَيْكُمْ","tr":"Wa 'alaykum","ref":"Bukhari: 6258"},{"id":904,"cat":"manners","sub":90,"ar":"اَلسَّلَامُ عَلَيْكُمْ","tr":"assalaamu ‛alaykum","ref":"Sahih (Albani). Abu Dawud: 5195"},{"id":482,"cat":"manners","sub":91,"ar":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيْمِ","tr":"A'oodhu billaahi minash-Shaytaanir-rajeem","ref":"Bukhari: 3282"},{"id":483,"cat":"manners","sub":91,"ar":"اَللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ","tr":"Allaahumma fa'ayyumaa mu'minin sababtuhu faj'al thaalika lahu qurbatan 'ilayka yawmal-qiyaamah","ref":"Bukhari: 6361"},{"id":484,"cat":"manners","sub":91,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَا إِلَهَ إِلَّا اللَّهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ لَا إِلَهَ إِلَّا اللَّهُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Laa 'ilaaha 'illAllahu wAllahu 'Akbar, laa 'ilaaha 'illAllahu wahdahu, laa 'ilaaha 'illAllahu wahdahu laa shareeka lahu, laa 'ilaaha 'illAllahu lahul-mulku wa lahul-hamdu, laa 'ilaaha 'illAllahu wa laa hawla wa laa quwwata 'illaa billaah","ref":"Sahih. Tirmidhi: 3430"},{"id":485,"cat":"manners","sub":91,"ar":"اَللَّهُمَّ رَبَّ جِبْرَائِيْلَ وَمِيْكَائِيْلَ وَإِسْرَافِيلَ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ اهْدِنِيْ لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِيْ مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيْمٍ","tr":"Allaahumma rabba jibra-eel, wameeka-eel, wa-israafeel faatiras-samawaati wal-ardi, AAalimal-ghaybi washshahaadah, anta tahkumu bayna ibaadika feemaa kanoo feehi yakhtalifoon ihdinee limakh-tulifa feehi minal-haqqi bi-idhnika, innaka tahdee man tashaa-o ilaa siraatin mustaqeem","ref":"Muslim: 770"},{"id":488,"cat":"manners","sub":91,"ar":"أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ","tr":"Ahabbakal-ladhee 'ahbabtanee lahu","ref":"Hasan. Abu Dawud: 5125"},{"id":489,"cat":"manners","sub":91,"ar":"بَارَكَ اللَّهُ فِيكُمْ","tr":"BaarakAllahu feekum","ref":"Zayid (Nasai). Amalul Yawm wal Laila: 303, Zayed (Albani). Kalema tvayyabah: 239"},{"id":491,"cat":"manners","sub":91,"ar":"اَللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا وَضَعْ عَنِّيْ بِهَا وِزْرًا وَاجعَلْهَا لِي عِنْدَكَ ذُخْرًا وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ","tr":"Allahum-maktub lee bihaa 'indaka 'ajran, wad'a 'annee bihaa wizran, waj'alhaa lee 'indaka thukhran, wa taqabbalhaa minnee kamaa taqabbaltahaa min 'abdika Daawood","ref":"Hasan. Tirmidhi: 3424"},{"id":903,"cat":"manners","sub":91,"ar":"اَللَّهُمَّ انْفَعْنِيْ بِمَا عَلَّمْتَنِيْ وَعَلِّمْنِيْ مَا يَنْفَعُنِيْ وَارْزُقْنِيْ عِلْمًا تَنْفَعُنِيْ بِهِ.","tr":"Allaahumman fa’ni bimaa allamtani wa allimni ma yanfayuni war’zuqni ilman tanfayuni bihi.","ref":"Sahih (Albani). Silsilatus Sahihah 3151"},{"id":494,"cat":"gathering","sub":92,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ","tr":"Rabbighfir lee watub 'alayya 'innaka 'Antat-Tawwaabur-rahim","ref":"Sahih. Abu Dawud: 1516"},{"id":495,"cat":"gathering","sub":92,"ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ","tr":"Subhaanaka Allaahumma wa bihamdika, 'ash-hadu 'an laa 'ilaaha 'illaa 'Anta, 'astaghfiruka wa 'atoobu 'ilayka","ref":"Sahih. Tirmidhi: 3433"},{"id":496,"cat":"gathering","sub":92,"ar":"اَللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيْكَ وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ وَمِنَ الْيَقِيْنِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيْبَاتِ الدُّنْيَا وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا وَاجْعَلْهُ الْوَارِثَ مِنَّا وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا وَانْصُرْنَا عَلَى مَنْ عَادَانَا وَلَا تَجْعَلْ مُصِيْبَتَنَا فِي دِيْنِنَا وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا","tr":"Allaahum-maq-sim la-naa min khash-yatika maa ya'hoolu baynanaa wa bayna ma‛aa-seeka, wa min taa‘a-tika maa tuballi-ghunaa bihi jan-nataka, wa mi-nal-yaqee-ni maa tu-hauwinu bihi ‛alaynaa musib-atid-dunyaa, wa matt'iena bi asmaa‛i-naa, wa absaa-rinaa, wa qoo-wati-naa maa a'h-yay-tanaa, waj‛al-hul-waaritha min-naa, waj‛al tha’ra-naa ‛alaa man zala-manaa, wan-sur-naa ‛alaa man ‛aa-daa-naa, wa laa taj‛al mu-seeba-ta-naa fee dee-ni-naa, wa laa taj‛a-lid-dunyaa akbara ham-minaa, wa laa mab-lagha ‛il-minaa, wa laa tusal-lit ‛alay-naa man laa yar-'hamunaa","ref":"Hasan. Tirmidhi: 3502"},{"id":499,"cat":"food","sub":94,"ar":"بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ","tr":"Bismillaahi 'awwalahu wa 'aakhirah","ref":"Sahih. Abu Dawud: 3767"},{"id":500,"cat":"food","sub":95,"ar":"بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ","tr":"Bismillahi fi-awwalihi wa akhirihi","ref":"Sahih. Tirmidhi: 1858"},{"id":503,"cat":"food","sub":97,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِيْ هَذَا وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","tr":"Alhamdu lillaahil-lathee 'at'amanee haathaa, wa razaqaneehi, min ghayri hawlin minnee wa laa quwwah","ref":"Hasan. Ibn Majah: 3285"},{"id":504,"cat":"food","sub":97,"ar":"اَللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ","tr":"Allaahumma baarik lanaa feehi wa zidnaa minhu","ref":"Hasan. Ibn Majah: 3322"},{"id":505,"cat":"food","sub":97,"ar":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا","tr":"Alhamdu lillaahi hamdan katheeran tayyiban mubaarakan feehi, ghayra [makfiyyin wa laa] muwadda'in, wa laa mustaghnan 'anhu Rabbanaa","ref":"Bukhari: 5458, Sahih. Tirmidhi: 3456"},{"id":506,"cat":"food","sub":97,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَ وَسَقَى وَسَوَّغَهُ وَجَعَلَ لَهُ مَخْرَجًا","tr":"Alhamdu lillahilladhi at'ama wasaqa wasawwagahu waza'ala lahu makhrazaa","ref":"Sahih. Abu Dawud: 3851"},{"id":905,"cat":"food","sub":97,"ar":"اَلْحَمْدُ لِلَّهِ الَّذِيْ يُطْعِمُ وَلَا يُطْعَمُ مَنَّ عَلَيْنَا فَهَدَانَا وَأَطْعَمَنَا وَسَقَانَا وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا اَلْحَمْدُ لِلَّهِ غَيرَ مُوَدَّعٍ وَّلَا مُكَافَأٍ وَّلَا مُكَافَأٍ وَّلَا مَكْفُوْرٍ وَّلَا مُسْتَغْنًى عَنْهُ اَلْحَمْدُ لِلَّهِ الَّذِيْ أَطْعَمَ مِنَ الطَّعَامِ وَسَقٰى مِنَ الشَّرَابِ وَكَسٰی مِنَ العُرْيِ وَهَدٰى مِنَ الضَّلَالَةِ وَبَصَّرَ مِنَ العَمْيِ وَفَضَّلَ عَلٰى كَثِيْرٍ مِمَّنْ خَلَقَ تَفْضِيلًا اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","tr":"Alhamdulillaa-hilladhi ut’emu wa laa ut’amu, manna alaynaa fahadaanaa wa at’amanaa wa saqaanaa wa kulla blaa’in hasanin ablaanaa, Alhamdu lillahi gayra muwaddain wa laa mukaafain wa laa mukaafain wa laa makfu’rin wa laa mustaghnan anhu, Alhamdulillaa-hilladhi at’ama minat-ta’aama minat-ta’aami wasaqa minash sharaabi wa kasaa minaal wuryee wa-hada minad dalaalati wa bassara minal amyee wa faddala mimman khalaqa tafdillan, alhamdulillahi rabbil alaamin.","ref":"Sahih (Ahmad Shakir). ‘Umdatut Tafsir 1/865"},{"id":906,"cat":"food","sub":97,"ar":"اَللَّهُمَّ أَطْعَمْتَ وَأَسْقَيْتَ وَأَغْنَيْتَ وَأَقْنَيْتَ وَهَدَيْتَ وَأَحْيَيْتَ فَلَكَ الْحَمْدُ عَلَى مَا أَعْطَيْتَ","tr":"Allaahumma at‛amta wa asqayta, wa aghnayta wa aqnayta, wa hadayta wa ahyayta, fa lakal hamdu ‛alaa maa a‛tayta.","ref":"Sahih (Albani). Kalimut Tayyib: 190"},{"id":507,"cat":"food","sub":98,"ar":"اَللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِيْ وَاسْقِ مَنْ سَقَانِيْ (وَأَسْقِ مَنْ أَسْقَانِي)","tr":"Allaahumma 'at'im man 'at'amanee wasqi man saqaanee (in another narration: wa asqee man asqaani)","ref":"Muslim: 2055"},{"id":508,"cat":"food","sub":98,"ar":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُوْنَ وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","tr":"Aftara 'indakumus-saa'imoon, wa 'akala ta'aamakumul-'abraar, wa sallat 'alaykumul-malaa'ikah","ref":"Sahih. Abu Dawud: 3854"},{"id":509,"cat":"food","sub":98,"ar":"اَللَّهُمَّ بَارِكْ لَهُمْ فِي مَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","tr":"Allaahumma baarik lahum feemaa razaqtahum, waghfir lahum warhamhum","ref":"Muslim: 2042"},{"id":513,"cat":"animals","sub":99,"ar":"اَلْحَمْدُ لِلَّهِ سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ اَلْحَمْدُ لِلَّهِ اَللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ (لَا إِلَهَ إِلَّا أَنْتَ) سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلَّا أَنْتَ","tr":"Alhamdu lillaah. Subhaanal-ladhee sakhkhara lanaa haadhaa wa maa kunnaa lahu muqrineen. Wa 'innaa 'ilaa Rabbinaa lamunqaliboon. Alhamdu lillaah, alhamdu lillaah, alhamdu lillaah, Allahu 'Akbar, Allahu 'Akbar, Allahu 'Akbar, (laa ilaaha illaa 'Anta) subhaanaka 'innee dhalamtu nafsee faghfir lee, fa'innahu laa yaghfirudh-dhunooba 'illaa 'Anta","ref":"Sahih. Tirmidhi: 3446"},{"id":515,"cat":"animals","sub":99,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","tr":"Allaahumma innee as’aluka min fadlik","ref":"Bukhari: 3303"},{"id":517,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ وَأَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ","tr":"Allaahumma 'innee 'as'aluka khayrahaa, wa khayra maa feehaa, wa khayra maa 'ursilat bihi wa A'oodhu bika min sharrihaa, wa sharri maa feehaa, wa sharri maa 'ursilat bihi","ref":"Muslim: 899"},{"id":519,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ إِنِّي اَعُوذُبِكَ مِنْ شَرِّهَا","tr":"Allaahumma inni A‛oodhu bika min sarrihaa","ref":"Sahih. Abu Dawud: 5099"},{"id":520,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ صَيِّبًا نَافِعًا","tr":"Allaahumma sayyiban naafi'an","ref":"Bukhari: 1032"},{"id":522,"cat":"rainnature","sub":100,"ar":"سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيْفَتِهِ","tr":"Subhaanal-lathee yusabbihur-ra'du bihamdihi wal-malaa'ikatu min kheefatihi","ref":"Sahih. Adabul Mufrad: 560"},{"id":523,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ لَا تَقْتُلْنَا بِغَضَبِكَ وَلَا تُهْلِكْنَا بِعَذَابِكَ وَعَافِنَا قَبْلَ ذَلِكَ","tr":"Allaahumma Laa taqtulna bi-ghadabika Wa laa tuhlikna bi-adhaabika Wa aafina qabla dhalik","ref":"Sahihul Isnad (Ahmad Shakir). Musnad Ahmad: 8/98"},{"id":524,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ لَا طَيْرَ إِلاَّ طَيْرُكَ وَلَا خَيْرَ إِلَّا خَيْرُكَ وَلَا إِلَهَ غَيْرُكَ","tr":"Allaahumma laa tayra illaa tayruka, wa laa khayra illaa khayruka, wa laa ilaaha ghayruk","ref":"Sahih (Albani). Silsila Sahiha: 1065, Musnad Ahmad: 7045"},{"id":525,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ عَلَى ظُهُوْرِ الْجِبَالِ وَالْآكَامِ وَبُطُوْنِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ","tr":"Allaahumma ‘alaa dhuhuril jibaali wal aakaami wa butunil awdiyati wa manaabitish shajari","ref":"Bukhari: 1019"},{"id":526,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ اسْقِنَا غَيْثًا مُغِيْثًا مَرِيْئًا مَرِيْعًا نَافِعًا غَيْرَ ضَارٍّ عَاجِلًا غَيْرَ آجِلٍ","tr":"Allaahumma 'asqinaa ghaythan mugheethan maree-an maree'an, naafi'an ghayra dhaarrin, 'aajilan ghayra 'aajil","ref":"Sahih (Albani). Abu Dawud: 1169"},{"id":527,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ أَغِثْنَا اَللَّهُمَّ أَغِثْنَا اَللَّهُمَّ أَغِثْنَا","tr":"Allaahumma 'aghithnaa. Allaahumma 'aghithnaa. Allaahumma 'aghithnaa","ref":"Bukhari: 1014"},{"id":528,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ اسْقِ عِبَادَكَ وَبَهَائِمَكَ وَانْشُرْ رَحْمَتَكَ وَأَحْيِي بَلَدَكَ الْمَيِّتَ","tr":"Allahum-masqi 'ibaadaka, wa bahaa'imaka, wanshur rahmataka, wa 'ahyi baladakal-mayyita","ref":"Hasan (Albani). Abu Dawud: 1176"},{"id":529,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا اَللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ وَبُطُونِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ","tr":"Allaahumma hawaalaynaa wa laa 'alaynaa. Allaahumma 'alal-'aakaami wadh-dhiraabi, wa butoonil-'awdiyati, wa manaabitish-shajar","ref":"Hasan (Albani). Abu Dawud: 1/218"},{"id":530,"cat":"rainnature","sub":100,"ar":"مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ","tr":"Mutirnaa bifadhlillaahi wa rahmatihi","ref":"Bukhari: 846"},{"id":907,"cat":"rainnature","sub":100,"ar":"اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَٰنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ لَا إِلٰهَ إِلَّا اللَّهُ يَفْعَلُ مَا يُرِيْدُ اَللَّهُمَّ أَنْتَ اللَّهُ لَا إِلٰهَ إِلَّا أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ أَنْزِلْ عَلَيْنَا الْغَيْثَ وَاجْعَلْ مَا أَنْزَلْتَ لَنَا قُوَّةً وَّبَلَاغًا إِلٰى حِيْنٍ.","tr":"Alhamdu lillaahi rabbil-‛aalameen, ar-rahmaan-ir-raheem, maaliki yawm-id-deen, laa ilaaha illaallahu yaf‛alu maa yureed, Allaahumma ant-allaahu laa ilaaha illaa antal-ghaniyyu wa nahnul-fuqaraa, anzil ‛alaynal-ghaytha, waj‛al maa anzalta lanaa quwwataw wa balaaghan ilaa heen.","ref":"Hasan. Abu Dawud: 1173"},{"id":908,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ شَرِّ مَا أُرْسِلَ بِهِ اَللَّهُمَّ سَيْبًا نَافِعًا.","tr":"Allahumma inna nA‛oodhu bika min sharri ma ursila bihi, Allahumma sayiban naafi’an.","ref":"Sahih. Ibn Majah: 3889"},{"id":909,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ هٰذِهِ الرِّيْحِ وَخَيْرِ مَا فِيْهَا وَخَيْرِ مَا أُمِرَتْ بِهِ وَنَعُوْذُ بِكَ مِنْ شَرِّ هٰذِهِ الرِّيْحِ وَشَرِّ مَا فِيْهَا وَشَرِّ مَا أُمِرَتْ بِهِ","tr":"Allahumma inna nas-aluka min khairi hadhihir-rih, wa khairi ma fiha wa khairi ma umirat bihi wa nA‛oodhu bika min sharri hadhihir-rih wa sharri ma fiha wa sharri ma umirat bihi.","ref":"Sahih. Tirmidhi: 2252"},{"id":910,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ لَقْحًا لَا عَقِيْمًا","tr":"Allaahumma laqha laa aqima.","ref":"Hassan (Albani). Silsilatul Sahiha: 2058"},{"id":911,"cat":"rainnature","sub":100,"ar":"اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ خَيْرِ مَا أُمِرَتْ بِهِ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا أُمِرَتْ بِهِ","tr":"Allaahumma inni asaluka min khayri maa umirat bihi, wa A‛oodhu bika min sharri maa umirat bihi.","ref":"Sahih (Ibn Hazar al-Asqalani). Fathul Bari: 2/604, Sahih (Wadi). Sahih Musnad: 73"},{"id":912,"cat":"rainnature","sub":100,"ar":"اللَّهُمَّ صَيِّبًا هَنِيْئًا","tr":"Allaahumma sayyiban hanee-a","ref":"Sahih. Abu Dawud: 5099"},{"id":531,"cat":"sickness","sub":101,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ ١ الْحَمْدُ لِلَّـهِ رَبِّ الْعَالَمِينَ ٢ الرَّحْمَـٰنِ الرَّحِيمِ ٣ مَالِكِ يَوْمِ الدِّينِ ٤ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ٥ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ٦ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ٧","tr":"(1) Bismillaahir Rahmaanir Raheem. (2) Alhamdu lillaahi Rabbil 'aalameen. (3) Ar-Rahmaanir-Raheem. (4) Maaliki Yawmid-Deen. (5) Iyyaaka na'budu wa lyyaaka nasta'een. (6) Ihdinas-Siraatal-Mustaqeem. (7) Siraatal-lazeena an'amta 'alaihim ghayril-maghdoobi 'alaihim wa lad-daaalleen","ref":"Bukhari: 5741"},{"id":532,"cat":"sickness","sub":101,"ar":"بَارَكَ اللَّهُ لَكَ","tr":"Barakallahu lak","ref":"Sahih (Albani). Ibn Majah: 3508, 3509"},{"id":534,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ اِشْفِ وَأَنْتَ الشَّافِي لَا شِفَاءَ إِلاَّ شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا","tr":"Allaahumma Rabban-nas Adhhibil-ba’s, Ishfi wa Antash-Shafi, laa shifa’a illaa shifaa’uka, shifaa’an laa yughadiru saqama","ref":"Bukhari: 5743"},{"id":535,"cat":"sickness","sub":101,"ar":"باِسْمِ اللَّهِ تُرْبَةُ أَرْضِنَا بِرِيْقَةِ بَعْضِنَا يُشْفَى (بِهِ) سَقِيْمُنَا بِإِذْنِ رَبِّنَا","tr":"Bismil-laahi, turbatu ardina, biriqati ba`dina, yushfa (bihi) saqimuna, bi 'idhni Rabbina","ref":"Bukhari: 5745, Muslim : 2194"},{"id":537,"cat":"sickness","sub":101,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ هُوَ اللَّـهُ أَحَدٌ ١ اللَّـهُ الصَّمَدُ ٢ لَمْ يَلِدْ وَلَمْ يُولَدْ ٣ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ","tr":"Bismillaahir-Rahmaanir-Raheem. (1) Qul HuwAllahu 'Ahad. (2) Allahus-Samad. (3) Lam yalid wa lam yoolad. (4) Wa lam yakun lahu kufuwan 'ahad","ref":"Bukhari: 5735"},{"id":540,"cat":"sickness","sub":101,"ar":"أَذْهِبِ الْبَأْسَ رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا","tr":"Adhhibil-ba’s Rabban-naas, washfi Antash-Shaafi, laa shifaa’a illaa shifaa’uka, shifaa’an laa yughadiru saqama","ref":"Bukhari: 5675"},{"id":541,"cat":"sickness","sub":101,"ar":"لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ","tr":"Laa ba'sa tahoorun 'inshaa'Allah.","ref":"Bukhari: 3616"},{"id":542,"cat":"sickness","sub":101,"ar":"أَسْأَلُ اللَّهَ الْعَظِيْمَ رَبَّ الْعَرْشِ الْعَظِيْمِ أَنْ يَشْفِيَكَ","tr":"As'alullaahal-'Adheem Rabbal-'Arshil-'Adheem 'an yashfiyak","ref":"Sahih. Tirmidhi: 2083"},{"id":543,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى","tr":"Allahum-maghfir lee warhamnee wa 'alhiqnee bir-rafeeqil-'a'laa","ref":"Sahih (Albani) Sahih Al Jame: 1267"},{"id":544,"cat":"sickness","sub":101,"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ","tr":"Laa ilaaha ill-Allahu wAllahu akbar","ref":"Sahih (Albani). Tirmidhi: 3430"},{"id":547,"cat":"sickness","sub":101,"ar":"لَا إِلَهَ إِلَّا اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ","tr":"Laa 'ilaaha 'illAllahu 'inna lilmawti sakaraat","ref":"Bukhari: 4449"},{"id":549,"cat":"sickness","sub":101,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اَللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا","tr":"Innaa lillaahi wa innaa ilayhi raaji‛oon, Allaahumma’ jurnee fee museebatee, wakhlif lee khayran minhaa","ref":"Muslim: 918"},{"id":550,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَلَهُ وَأَعْقِبْنِي مِنْهُ عُقْبٰى حَسَنَةً","tr":"Allaahummaghfir li walahu, wa a’qibni minhu ‘uqba hasanah","ref":"Muslim: 919"},{"id":913,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","tr":"Allaahumma ahyinee maa kaanatil hayaatu khayran lee, wa tawaffanee idhaa kaanatil wafaatu khayran lee.","ref":"Bukhari: 5671"},{"id":914,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ اشْفِ عَبْدَكَ يَنْكَأُ لَكَ عَدُوًّا أَوْ يَمْشِيْ لَكَ إِلٰى جَنَازَةٍ.","tr":"Allaahummashfi abdaka yankau laka aduyya, aw yamshi laka ilaa janaazah.","ref":"Sahih. Abu Dawud: 3107"},{"id":915,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ ارْزُقْنِيْ شَهَادَةً فِيْ سَبِيْلِكَ وَاجْعَلْ مَوْتِيْ فِي بَلَدِ رَسُوْلِكَ (صلى الله عليه وسلم).","tr":"Allaahummar zuqni shahaadatan fee sabilik, waj’al mawti fee baladi rasulik (ﷺ).","ref":"Bukhari: 1890"},{"id":916,"cat":"sickness","sub":101,"ar":"أَعُوْذُ بِعِزَّةِ اللَّهِ وَقُدْرَتَهٖ مِنْ شَرِّ مَا أَجِدُ مِنْ وَجَعِي هٰذَا","tr":"A`udhu bi-`izzatillahi wa qudratihi min sharri ma ajidu min waja`i hadhaa.","ref":"Sahih. Tirmidhi: 3588"},{"id":917,"cat":"sickness","sub":101,"ar":"اَللَّهُمَّ إِنَّكَ قُلْتَ : اُدْعُوْنِيْ أَسْتَجِبْ لَكُمْ وَإِنَّكَ لَا تُخْلِفُ الْمِيعَادَ وَإِنِّيْ أَسْأَلُكَ كَمَا هَدَيْتَنِيْ لِلْإِسْلَامِ أَنْ لَّا تَنْزِعَهُ مِنِّيْ حَتّٰى تَتَوَفَّانِيْ وَأَنَا مُسْلِمٌ","tr":"Allaahumma innaka qulta: ud’uni astajib lakum, wa ainnaka laa tukhliful miyaada, wa inni as’aluka kamaa hadaytani leel-islaami an’laa tanzi’ahu minni hatta tatawaffaani wa annaa muslimun.","ref":"Zayyid Sanad (Muhammad ibn Abdil Wahhab). Al-Hadith Libni Abdil Wahhab 3/145"},{"id":918,"cat":"sickness","sub":101,"ar":"أَعُوْذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهٖ عَلٰى كُلِّ شَيْءٍ مِّنْ شَرِّ مَا أَجِدُ","tr":"A‛oodhu bi-'izzatillahi wa qudratihi alaa kulli shayyin min sharri maa 'ajidu.","ref":"Sahih ligairih (Albani). Silsilatus Sahihah 1415"},{"id":552,"cat":"sickness","sub":102,"ar":"اَللَّهُمَّ اغْفِرْ لَهَا وَارْفَعْ دَرَجَتَهَا فِي الْمَهْدِيِّيْنَ وَاخْلُفْهَآ فِي عَقِبِهَا فِي الْغَابِرِيْنَ وَاغْفِرْ لَنَا وَلَهَا يَا رَبَّ الْعَالَمِيْنَ وَافْسَحْ لَهَا فِي قَبْرِهَا وَنَوِّرْ لَهَا فِيهِ","tr":"Allahumm-aghfir laha [mention the person's name] warfa‛ darajataha fil-mahdiyyin, wakhlufha fee ‛aqibiha fil-ghaabireen, waghfir lanaa wa laha yaa rabbal-‛aalameen, wafsah laha fee qabriha wa nawwir laha feeh","ref":"Muslim: 920"},{"id":553,"cat":"sickness","sub":103,"ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَّامَّةٍ","tr":"A'oodhu bi kalimaat-illaahit-taammati min kulli shaytaanin, wa haammah, wa min kulli 'aynin laammah","ref":"Bukhari: 3371"},{"id":554,"cat":"sickness","sub":103,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ أَعُوْذُ بِرَبِّ الْفَلَقِ ١ مِن شَرِّ مَا خَلَقَ ٢ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ٣ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ٤ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ٥","tr":"Bismillaahir-Rahmaanir-Raheem. (1) Qul 'A'oodhu birabbil-falaq. (2) Min sharri maa khalaq. (3) Wa min sharri ghaasiqin 'ithaa waqab. (4) Wa min sharrin-naffaathaati fil-'uqad. (5) Wa min sharri haasidin 'ithaa hasad","ref":"[1] Surah Falaq: 1-5 [2] Surah Nas: 1-6 [3] Sahih (Albani). Ibn Majah: 3511"},{"id":555,"cat":"sickness","sub":103,"ar":"بِسْمِ اللَّهِ أَرْقِيْكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيْكَ مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنٍ حَاسِدٍ اَللَّهُ يَشْفِيكْ بِسْمِ اللَّهِ أَرْقِيْكَ","tr":"Bismillaahi arqik, min kulli shay’in yu’dhik, min sharri kulli nafsin aw ‘aynin haasidin. Allahu yashfik, bismillaahi arqik","ref":"Muslim: 2186"},{"id":556,"cat":"sickness","sub":103,"ar":"اَللَّهُمَّ أَذْهِبْ حَرَّهَا وَبَرْدَهَا وَوَصَبَهَا","tr":"Allaahumma adh-hib harrahaa wa bardahaa wa wa-sabahaa","ref":"Jayyid/Good chain of narration (Hussein Saleem Asad). Musnad Abi Ya’la al-Mawsili: 8195"},{"id":919,"cat":"sickness","sub":103,"ar":"مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Maa shaa allaahu laa quwwata illaa billaah.","ref":"Surah Al-Kahf: 39"},{"id":560,"cat":"jinndiseases","sub":104,"ar":"الم ١ ذَٰلِكَ الْكِتَابُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ ٢ الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ٣ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ٤ أُولَـٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُولَـٰئِكَ هُمُ الْمُفْلِحُونَ ٥","tr":"Alif-Laam-Meem. Zaalikal-Kitaabu laa raiba feeh; hudal-lil-muttaqeen. Allazeena yu'minoona bil-ghaibi wa yuqeemoonas-Salaata wa mimmaa razaqnaahum yunfiqoon. Wallazeena yu'minoona bimaaa unzila ilaika wa maaa unzila min qablika wa bil-Aakhirati hum yooqinoon. Ulaaa'ika 'alaa hudam-mir-Rabbihim wa ulaaa'ika humul-muflihoon.","ref":"Surah Baqarah 2: 1-5"},{"id":561,"cat":"jinndiseases","sub":104,"ar":"وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ ۖ وَمَا كَفَرَ سُلَيْمَانُ وَلَـٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ ۚ وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّـهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ ۚ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ ۚ لَوْ كَانُوا يَعْلَمُونَ ١٠٢","tr":"Wattaba'oo maa tatlush-Shayaateenu 'alaa mulki Sulaimaan; wa maa kafara Sulaimaanu wa laakinnash-Shayaateena kafaroo yu'allimoonan-naasas-sihra wa maaa unzila 'alal-malakaini bi-Baabila Haaroota wa Maaroot; wa maa yu'allimaani min ahadin hattaa yaqoolaaa innamaa nahnu fitnatun falaa takfur. Fayata'allamoona minhumaa maa yufarriqoona bihee bainal-mar'i wa zawjih; wa maa hum bi-daaarreena bihee min ahadin illaa bi-iznillaah; wa yata'allamoona maa yadurruhum wa laa yanfa'uhum; wa laqad 'alimoo lamanishtaraahu maa lahoo fil-Aakhirati min khalaaq; wa labi'sa maa sharaw biheee anfusahum; law kaanoo ya'lamoon.","ref":"Surah Baqarah 2: 102"},{"id":562,"cat":"jinndiseases","sub":104,"ar":"وَإِلَـٰهُكُمْ إِلَـٰهٌ وَاحِدٌ ۖ لَّا إِلَـٰهَ إِلَّا هُوَ الرَّحْمَـٰنُ الرَّحِيمُ ١٦٣ إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِمَا يَنفَعُ النَّاسَ وَمَا أَنزَلَ اللَّـهُ مِنَ السَّمَاءِ مِن مَّاءٍ فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ ١٦٤","tr":"Wa ilaahukum ilaahun Waahid; laaa ilaaha illaa Huwar-Rahmaanur-Raheem. Inna fee khalqis-samaawaati wal-ardi wakhtilaafil-layli wan-nahaari wal-fulkil-latee tajree fil-bahri bimaa yanfa'un-naasa wa maaa anzalallaahu minas-samaaa'i mim-maaa'in fa-ahyaa bihil-arda ba'da mawtihaa wa baththa feehaa min kulli daaabbatin wa tasreefir-riyaahi was-sahaabil-musakhkhari bainas-samaaa'i wal-ardi la-aayaatil-liqawmil-ya'qiloon.","ref":"Surah Baqarah 2: 163-164"},{"id":563,"cat":"jinndiseases","sub":104,"ar":"اللّٰهُ لَآ إِلٰهَ إِلَّا هُوَ الْحَىُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى السَّمٰوٰتِ وَمَا فِى الْأَرْضِ ۗ مَن ذَا الَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ الْعَلِىُّ الْعَظِيمُ","tr":"Allaahu laaa ilaaha illaa Huwal-Hayyul-Qayyoom; laa ta'khuzuhoo sinatun wa laa nawm; lahoo maa fis-samaawaati wa maa fil-ard; man zal-lazee yashfa'u 'indahooo illaa bi-iznih; ya'lamu maa baina aydeehim wa maa khalfahum wa laa yuheetoona bishai'im-min 'ilmihee illaa bimaa shaaa'; wasi'a Kursiyyuhus-samaawaati wal-arda wa laa ya'ooduhoo hifzuhumaa; wa Huwal-'Aliyyul-'Azeem.","ref":"Surah Baqarah 2: 255"},{"id":564,"cat":"jinndiseases","sub":104,"ar":"لِّلَّـهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ وَإِن تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللَّـهُ ۖ فَيَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ ۗ وَاللَّـهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ ٢٨٤ آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّـهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ٢٨٥ لَا يُكَلِّفُ اللَّـهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ٢٨٦","tr":"Lillaahi maa fis-samaawaati wa maa fil-ard; wa in tubdoo maa feee anfusikum aw tukhfoohu yuhaasibkum bihil-laah; fayaghfiru liman yashaaa'u wa yu'azzibu man yashaaa'; wallaahu 'alaa kulli shai'in Qadeer. Aamanar-Rasoolu bimaaa unzila ilaihi mir-Rabbihee wal-mu'minoon; kullun aamana billaahi wa malaaa'ikatihee wa Kutubihee wa Rusulihee laa nufarriqu baina ahadim-mir-Rusulih; wa qaaloo sami'naa wa ata'naa ghufraanaka Rabbanaa wa ilaikal-maseer. Laa yukallifullaahu nafsan illaa wus'ahaa; lahaa maa kasabat wa 'alaihaa maktasabat; Rabbanaa laa tu'aakhiznaaa in naseenaaa aw akhta'naa; Rabbanaa wa laa tahmil 'alainaa isran kamaa hamaltahoo 'alal-lazeena min qablinaa; Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih; wa'fu 'annaa waghfir lanaa warhamnaa; Anta Mawlaanaa fansurnaa 'alal-qawmil-kaafireen.","ref":"Surah Baqarah 2: 284-286"},{"id":565,"cat":"jinndiseases","sub":104,"ar":"شَهِدَ اللَّـهُ أَنَّهُ لَا إِلَـٰهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ ۚ لَا إِلَـٰهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ ١٨ إِنَّ الدِّينَ عِندَ اللَّـهِ الْإِسْلَامُ ۗ وَمَا اخْتَلَفَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِآيَاتِ اللَّـهِ فَإِنَّ اللَّـهَ سَرِيعُ الْحِسَابِ ١٩","tr":"Shahidallaahu annahoo laaa ilaaha illaa Huwa wal-malaaa'ikatu wa ulul-'ilmi qaaa'imam-bilqist; laaa ilaaha illaa Huwal-'Azeezul-Hakeem. Innad-deena 'indallaahil-Islaam; wa makhtalafal-lazeena ootul-Kitaaba illaa mim-ba'di maa jaaa'ahumul-'ilmu baghyam-bainahum; wa man yakfur bi-aayaatillaahi fa-innallaaha saree'ul-hisaab.","ref":"Surah Ali-Imran 3: 18-19"},{"id":566,"cat":"jinndiseases","sub":104,"ar":"إِنَّ رَبَّكُمُ اللَّـهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ ۗ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ ۗ تَبَارَكَ اللَّـهُ رَبُّ الْعَالَمِينَ ٥٤ ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ ٥٥ وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا ۚ إِنَّ رَحْمَتَ اللَّـهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ ٥٦","tr":"Inna Rabbakumullaahul-lazee khalaqas-samaawaati wal-arda fee sittati ayyaamin thummastawaa 'alal-'Arshi yughshil-laylan-nahaara yatlubuhoo hatheethan wash-shamsa wal-qamara wan-nujooma musakhkharaatim-bi-amrih; alaa lahul-khalqu wal-amr; tabaarakallaahu Rabbul-'aalameen. Ud'oo Rabbakum tadarru'an wa khufyah; innahoo laa yuhibbul-mu'tadeen. Wa laa tufsidoo fil-ardi ba'da islaahihaa wad'oohu khawfan wa tama'aa; inna rahmatallaahi qareebum-minal-muhsineen.","ref":"Surah A'raf 7: 54-56"},{"id":567,"cat":"jinndiseases","sub":104,"ar":"وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ١١٧ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ١١٨ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ ١١٩ وَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ ١٢٠ قَالُوا آمَنَّا بِرَبِّ الْعَالَمِينَ ١٢١ رَبِّ مُوسَىٰ وَهَارُونَ ١٢٢","tr":"Wa awhainaaa ilaa Moosaaa an alqi 'asaaka fa-izaa hiya talqafu maa ya'fikoon. Fawqa'al-haqqu wa batala maa kaanoo ya'maloon. Faghuliboo hunaalika wanqalaboo saaghireen. Wa ulqiyas-saharatu saajideen. Qaaloo aamannaa bi-Rabbil-'aalameen. Rabbi Moosaa wa Haaroon.","ref":"Surah A'raf 7: 117-122"},{"id":568,"cat":"jinndiseases","sub":104,"ar":"فَلَمَّا أَلْقَوْا قَالَ مُوسَىٰ مَا جِئْتُم بِهِ السِّحْرُ ۖ إِنَّ اللَّـهَ سَيُبْطِلُهُ ۖ إِنَّ اللَّـهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ٨١ وَيُحِقُّ اللَّـهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ ٨٢","tr":"Falammaaa alqaw qaala Moosaa maa ji'tum bihis-sihr; innallaaha sayubtiluh; innallaaha laa yuslihu 'amalal-mufsideen. Wa yuhiqqullaahul-haqqa bikalimaatihee wa law karihal-mujrimoon.","ref":"Surah Yunus 10: 81-82"},{"id":569,"cat":"jinndiseases","sub":104,"ar":"وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا ۖ إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ ۖ وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَىٰ ٦٩","tr":"Wa alqi maa fee yameenika talqaf maa sana'oo; innamaa sana'oo kaidu saahir; wa laa yuflihus-saahiru haithu ataa.","ref":"Surah Ta Ha 20:69"},{"id":570,"cat":"jinndiseases","sub":104,"ar":"أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ ١١٥ فَتَعَالَى اللَّـهُ الْمَلِكُ الْحَقُّ ۖ لَا إِلَـٰهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ ١١٦ وَمَن يَدْعُ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ ۚ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ ١١٧ وَقُل رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ ١١٨","tr":"Afahasibtum annamaa khalaqnaakum 'abathan wa annakum ilainaa laa turja'oon. Fata'aalallaahul-Malikul-Haqqu laaa ilaaha illaa Huwa Rabbul-'Arshil-Kareem. Wa man yad'u ma'allaahi ilaahan aakhara laa burhaana lahoo bihee fa-innamaa hisaabuhoo 'inda Rabbih; innahoo laa yuflihul-kaafiroon. Wa qul Rabbigh-fir warham wa Anta khairur-raahimeen.","ref":"Surah Muminun 23: 115-118"},{"id":571,"cat":"jinndiseases","sub":104,"ar":"وَالصَّافَّاتِ صَفًّا ١ فَالزَّاجِرَاتِ زَجْرًا ٢ فَالتَّالِيَاتِ ذِكْرًا ٣ إِنَّ إِلَـٰهَكُمْ لَوَاحِدٌ ٤ رَّبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ الْمَشَارِقِ ٥ إِنَّا زَيَّنَّا السَّمَاءَ الدُّنْيَا بِزِينَةٍ الْكَوَاكِبِ ٦ وَحِفْظًا مِّن كُلِّ شَيْطَانٍ مَّارِدٍ ٧ لَّا يَسَّمَّعُونَ إِلَى الْمَلَإِ الْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ ٨ دُحُورًا ۖ وَلَهُمْ عَذَابٌ وَاصِبٌ ٩ إِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَأَتْبَعَهُ شِهَابٌ ثَاقِبٌ ١٠","tr":"Wus-saaaaffafati saffaa. Faz-zaajiraati zajraa. Fat-taaliyaati zikraa. Inna Ilaahakum la-Waahid. Rabbus-samaawaati wal-ardi wa maa bainahumaa wa Rabbul-macaariq. Innaa zaiyannas-samaaa'ad-dunyaa bizeenatinil-kawaakib. Wa hifzam-min kulli shaitaanim-maarhid. Laa yassamma'oona ilal-mala'il-a'laa wa yuqzafoona min kulli jaanib. Duhooran wa lahum 'azaabun waasib. Illaa man khatifal-khatfata fa-atba'ahoo shihaabun thaaqib.","ref":"Surah As-Saffat 37: 1-10"},{"id":572,"cat":"jinndiseases","sub":104,"ar":"وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنصِتُوا ۖ فَلَمَّا قُضِيَ وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ ٢٩ قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنزِلَ مِن بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ ٣٠ يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّـهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ ٣١ وَمَن لَّا يُجِبْ دَاعِيَ اللَّـهِ فَلَيْسَ بِمُعْجِزٍ فِي الْأَرْضِ وَلَيْسَ لَهُ مِن دُونِهِ أَوْلِيَاءُ ۚ أُولَـٰئِكَ فِي ضَلَالٍ مُّبِينٍ ٣٢","tr":"Wa iz sarafnaaa ilaika nafaram-minal-jinni yastami'oonal-Qur-aana falammaa hadaroohu qaalooo ansitoo falammaa qudiya wallaw ilaa qawmihim-munzireen. Qaaloo yaa qawmanaaa innaa sami'naa Kitaaban unzila mim-ba'di Moosaa musaddiqal-limaa baina yadaihi yahdeee ilal-haqqi wa ilaa Tareeqim-Mustaqeem. Yaa qawmanaaa ajeeboo daa'iyallaahi wa aaminoo bihee yaghfir lakum-min zunoobikum wa yujirkum-min 'azaabin aleem. Wa mal-laa yujib daa'iyallaahi falaisa bimu'jizin fil-ardi wa laisa lahoo min dooniheee awliyaaa'; ulaaa'ika fee dalaalim-mubeen.","ref":"Surah Ahqaf 46: 29-32"},{"id":573,"cat":"jinndiseases","sub":104,"ar":"يَا مَعْشَرَ الْجِنِّ وَالْإِنسِ إِنِ اسْتَطَعْتُمْ أَن تَنفُذُوا مِنْ أَقْطَارِ السَّمَاوَاتِ وَالْأَرْضِ فَانفُذُوا ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَانٍ ٣٣ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ٣٤ يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ ٣٥ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ٣٦","tr":"Yaa ma'sharal-jinni wal-insi inistata'tum an tanfuzoo min aqtaaris-samaawaati wal-ardi fanfuzoo; laa tanfuzoona illaa bisultaan. Fabi-ayyi aalaaa'i Rabbikumaa tukazzibaan. Yursalu 'alaikumaa shuwaazum-min naarin wa nuhaasun falaa tantasiraan. Fabi-ayyi aalaaa'i Rabbikumaa tukazzibaan.","ref":"Surah Rahman 55: 33-36"},{"id":574,"cat":"jinndiseases","sub":104,"ar":"لَوْ أَنزَلْنَا هَـٰذَا الْقُرْآنَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ اللَّـهِ ۚ وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ ٢١ هُوَ اللَّـهُ الَّذِي لَا إِلَـٰهَ إِلَّا هُوَ ۖ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ ۖ هُوَ الرَّحْمَـٰنُ الرَّحِيمُ ٢٢ هُوَ اللَّـهُ الَّذِي لَا إِلَـٰهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ ۚ سُبْحَانَ اللَّـهِ عَمَّا يُشْرِكُونَ ٢٣ هُوَ اللَّـهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ ۖ لَهُ الْأَسْمَاءُ الْحُسْنَىٰ ۚ يُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ ٢٤","tr":"Law anzalnaa haazal-Qur-aana 'alaa jabalil-lara-aitahoo khaashi'am-mutasaddi'am-min khashyatillaah; wa tilkal-amthaalu nadribuhaa linnaasi la'allahum yatafakkaroon. Huwallaahul-lazee laaa ilaaha illaa Huwa 'Aalimul-ghaibi wash-shahaadah; Huwar-Rahmaanur-Raheem. Huwallaahul-lazee laaa ilaaha illaa Huwal-Malikul-Quddoosus-Salaamul-Mu'minul-Muhaiminul-'Azeezul-Jabbaarul-Mutakabbir; Subhaanallaahi 'ammaa yushrikoon. Huwallaahul-Khaaliqul-Baari'ul-Musawwiru lahul-Asmaaa'ul-Husnaa; yusabbihu lahoo maa fis-samaawaati wal-ard; wa Huwal-'Azeezul-Hakeem.","ref":"Surah Hashr 59: 21-24"},{"id":575,"cat":"jinndiseases","sub":104,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا ١ يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ ۖ وَلَن نُّشْرِكَ بِرَبِّنَا أَحَدًا ٢ وَأَنَّهُ تَعَالَىٰ جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَلَا وَلَدًا ٣ وَأَنَّهُ كَانَ يَقُولُ سَفِيهُنَا عَلَى اللَّـهِ شَطَطًا ٤ وَأَنَّا ظَنَنَّا أَن لَّن تَقُولَ الْإِنسُ وَالْجِنُّ عَلَى اللَّـهِ كَذِبًا ٥ وَأَنَّهُ كَانَ رِجَالٌ مِّنَ الْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا ٦ وَأَنَّهُمْ ظَنُّوا كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ اللَّـهُ أَحَدًا ٧ وَأَنَّا لَمَسْنَا السَّمَاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا ٨ وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ الْآنَ يَجِدْ لَهُ شِهَابًا رَّصَدًا ٩","tr":"Bismillaahir-Rahmaanir-Raheem. Qul oohiya ilaiya annahustama'a nafarum-minal-jinni faqaalooo innaa sami'naa Qur-aanan 'ajabaa. Yahdeee ilar-rushdi fa-aamannaa bihee wa lan nushrika bi-Rabbinaaa ahadaa. Wa annahoo ta'aalaa jaddu Rabbinaa mattakhaza saahibatan wa laa waladaa. Wa annahoo kaana yaqoolu safeehunaa 'alallaahi shatataa. Wa annaa zanannaaa al-lan taqoolal-insu wal-jinnu 'alallaahi kazibaa. Wa annahoo kaana rijaalum-minal-insi ya'oozoona birijaalim-minal-jinni fazaadoohum rahaqaa. Wa annahum zannoo kamaa zanantum al-lan yab'athallaahu ahadaa. Wa annaa lamasnas-samaaa'a fawajadnaahaa muli'at harasan shadeedan wa shuhubaa. Wa annaa kunnaa naq'udu minhaa maqaa'ida lis-sam'i faman yastami'il-aana yajid lahoo shihaabar-rasadaa.","ref":"Surah Jinn 72: 1-9"},{"id":578,"cat":"jinndiseases","sub":104,"ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ أَعُوْذُ بِرَبِّ النَّاسِ ١ مَلِكِ النَّاسِ ٢ إِلَـٰهِ النَّاسِ ٣ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ٤ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ٥ مِنَ الْجِنَّةِ وَالنَّاسِ ٦","tr":"Bismillaahir-Rahmaanir-Raheem. Qul a'oozu bi-Rabbin-naas. Malikin-naas. Ilaahin-naas. Min sharril-waswaasil-khannaas. Allazee yuwaswisu fee sudoorin-naas. Minal-jinnati wannaas.","ref":"Surah Nas 114"},{"id":579,"cat":"jinndiseases","sub":105,"ar":"إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّـهِ قَدْ ضَلُّوا ضَلَالًا بَعِيدًا ١٦٧ إِنَّ الَّذِينَ كَفَرُوا وَظَلَمُوا لَمْ يَكُنِ اللَّـهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا ١٦٨ إِلَّا طَرِيقَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا ۚ وَكَانَ ذَٰلِكَ عَلَى اللَّـهِ يَسِيرًا ١٦٩ يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمُ الرَّسُولُ بِالْحَقِّ مِن رَّبِّكُمْ فَآمِنُوا خَيْرًا لَّكُمْ ۚ وَإِن تَكْفُرُوا فَإِنَّ لِلَّـهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۚ وَكَانَ اللَّـهُ عَلِيمًا حَكِيمًا ١٧٠ يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللَّـهِ إِلَّا الْحَقَّ ۚ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللَّـهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَآمِنُوا بِاللَّـهِ وَرُسُلِهِ ۖ وَلَا تَقُولُوا ثَلَاثَةٌ ۚ انتَهُوا خَيْرًا لَّكُمْ ۚ إِنَّمَا اللَّـهُ إِلَـٰهٌ وَاحِدٌ ۖ سُبْحَانَهُ أَن يَكُونَ لَهُ وَلَدٌ ۘ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ وَكَفَىٰ بِاللَّـهِ وَكِيلًا ١٧١ لَّن يَسْتَنكِفَ الْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّـهِ وَلَا الْمَلَائِكَةُ الْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا ١٧٢ فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِ ۖ وَأَمَّا الَّذِينَ اسْتَنكَفُوا وَاسْتَكْبَرُوا فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّـهِ وَلِيًّا وَلَا نَصِيرًا ١٧٣","tr":"Innal-lazeena kafaroo wa saddoo 'an sabeelillaahi qad dalloo dalaalam-ba'eedaa. Innal-lazeena kafaroo wa zalamoo lam yakunillaahu liyaghfira lahum wa laa liyahdiyahum tareeqaa. Illaa tareeqa Jahannama khaalideena feehaaa abadaa; wa kaana zaalika 'alallaahi yaseeraa. Yaaa ayyuhan-naasu qad jaaa'akur-Rasoolu bil-haqqi mir-Rabbikum fa-aaminoo khairal-lakum; wa in takfuroo fa-inna lillaahi maa fis-samaawaati wal-ard; wa kaanallaahu 'Aleeman Hakeemaa. Yaaa Ahlal-Kitaabi laa taghloo fee deenikum wa laa taqooloo 'alallaahi illal-haqq; innamal-Maseehu 'Eesab-nu Maryama Rasoolullaahi wa Kalimatuhoo alqaahaaa ilaa Maryama wa Roohum-minh; fa-aaminoo billaahi wa Rusulihee wa laa taqooloo thalaathah; intahoo khairal-lakum; innamallaahu Ilaahun Waahid; Subhaanahoo an yakoona lahoo walad; lahoo maa fis-samaawaati wa maa fil-ard; wa kafaa billaahi Wakeelaa. Lan yastankifal-Maseehu an yakoona 'abdal-lillaahi wa lal-malaaa'ikatul-muqarraboon; wa man yastankif 'an 'ibaadatihee wa yastakbir fasayahshuruhum ilaihi jamee'aa. Fa-ammal-lazeena aamanoo wa 'amilus-saalihaati fayuwaffeehim ujoorahum wa yazeeduhum-min fadlih; wa ammal-lazeena-stankafoo wastakbaroo fayu'azzibuhum 'azaaban aleeman wa laa yajidoona lahum-min doonillaahi waliyyan wa laa naseeraa.","ref":"Surah Nisa: 4: 167-173"},{"id":580,"cat":"jinndiseases","sub":105,"ar":"إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّـهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَن يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَافٍ أَوْ يُنفَوْا مِنَ الْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا ۖ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ ٣٣ إِلَّا الَّذِينَ تَابُوا مِن قَبْلِ أَن تَقْدِرُوا عَلَيْهِمْ ۖ فَاعْلَمُوا أَنَّ اللَّـهَ غَفُورٌ رَّحِيمٌ ٣٤","tr":"Innamaa jazaaa'ul-lazeena yuhaariboonallaaha wa Rasoolahoo wa yas'awna fil-ardi fasaadan an yuqattalooo aw yusallabooo aw tuqatta'a aideehim wa arjuluhum-min khilaafin aw yunfaw minal-ard; zaalika lahum khizyun fid-dunyaa wa lahum fil-Aakhirati 'azaabun 'azeem. Illal-lazeena taaboo min qabli an taqdiroo 'alaihim fa'lamooo annallaaha Ghafoorur-Raheem.","ref":"Surah Al-Ma'ida 5: 33-34"},{"id":581,"cat":"jinndiseases","sub":105,"ar":"إِذْ يُوحِي رَبُّكَ إِلَى الْمَلَائِكَةِ أَنِّي مَعَكُمْ فَثَبِّتُوا الَّذِينَ آمَنُوا ۚ سَأُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ فَاضْرِبُوا فَوْقَ الْأَعْنَاقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنَانٍ ١٢","tr":"Iz yoohee Rabbuka ilal-malaaa'ikati annee ma'akum fathabbitul-lazeena aamanoo; sa-ulqee fee quloobil-lazeena kafarur-ru'ba fadriboo fawqal-a'naaqi wadriboo minhum kulla banaan.","ref":"Sura Anfal 8:12"},{"id":582,"cat":"jinndiseases","sub":105,"ar":"وَلَقَدْ جَعَلْنَا فِي السَّمَاءِ بُرُوجًا وَزَيَّنَّاهَا لِلنَّاظِرِينَ ١٦ وَحَفِظْنَاهَا مِن كُلِّ شَيْطَانٍ رَّجِيمٍ ١٧ إِلَّا مَنِ اسْتَرَقَ السَّمْعَ فَأَتْبَعَهُ شِهَابٌ مُّبِينٌ ١٨","tr":"Wa laqad ja'alnaa fis-samaaa'i buroojan wa zaiyannaahaa lin-naazireen. Wa hafiznaahaa min kulli shaitaanir-rajeem. Illaa manis-taraqas-sam'a fa-atba'ahoo shihaabum-mubeen.","ref":"Sura Al-Hijr 15: 16-18"},{"id":583,"cat":"jinndiseases","sub":105,"ar":"قُلِ ادْعُوا اللَّـهَ أَوِ ادْعُوا الرَّحْمَـٰنَ ۖ أَيًّا مَّا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا ١١٠ وَقُلِ الْحَمْدُ لِلَّـهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ ۖ وَكَبِّرْهُ تَكْبِيرًا ١١١","tr":"Qulid'ullaaha awid'ur-Rahmaana ayyam-maa tad'oo falahul-Asmaaa'ul-Husnaa; wa laa tajhar bi-Salaatika wa laa tukhaafit bihaa wabtaghi baina zaalika sabeelaa. Wa qulil-Hamdu lillaahil-lazee lam yattakhiz waladan wa lam yakul-lahoo shareekun fil-mulki wa lam yakul-lahoo waliyyum-minaz-zulli wa kabbirhu takbeeraa.","ref":"Surah Isra 17: 110-111"},{"id":584,"cat":"jinndiseases","sub":105,"ar":"وَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَخْسَرِينَ ٧٠","tr":"Wa araadoo bihee kaidan faja'alnaahumul-akhsareen.","ref":"Surah Ambiya 21:70"},{"id":585,"cat":"jinndiseases","sub":105,"ar":"هَـٰذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ ۖ فَالَّذِينَ كَفَرُوا قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ الْحَمِيمُ ١٩ يُصْهَرُ بِهِ مَا فِي بُطُونِهِمْ وَالْجُلُودُ ٢٠ وَلَهُم مَّقَامِعُ مِنْ حَدِيدٍ ٢١ كُلَّمَا أَرَادُوا أَن يَخْرُجُوا مِنْهَا مِنْ غَمٍّ أُعِيدُوا فِيهَا وَذُوقُوا عَذَابَ الْحَرِيقِ ٢٢","tr":"Haazaani khasmaanikh-tasamoo fee Rabbihim fallazeena kafaroo qutti'at lahum thiyaabum-min naarin yusabbu min fawqi ru'oosihimul-hameem. Yusharu bihee maa fee butoonihim wal-julood. Wa lahum maqaami'u min hadeed. Kullamaaa araadooo an yakhrujoo minhaa min ghammin u'eedoo feehaa wa zooqoo 'azaabal-hareeq.","ref":"Surah Hajj 22: 19-22"},{"id":586,"cat":"jinndiseases","sub":105,"ar":"وَالَّذِينَ كَفَرُوا أَعْمَالُهُمْ كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمْآنُ مَاءً حَتَّىٰ إِذَا جَاءَهُ لَمْ يَجِدْهُ شَيْئًا وَوَجَدَ اللَّـهَ عِندَهُ فَوَفَّاهُ حِسَابَهُ ۗ وَاللَّـهُ سَرِيعُ الْحِسَابِ ٣٩","tr":"Wallazeena kafarooo a'maaluhum kasaraabim-biqee'atin yahsabuhu-zam'aanu maaa'an hattaaa izaa jaaa'ahoo lam yajidhu shai'an wa wajadallaaha 'indahoo fawaffaahu hisaabah; wallaahu saree'ul-hisaab.","ref":"Sura Noor 24:39"},{"id":587,"cat":"jinndiseases","sub":105,"ar":"وَقَدِمْنَا إِلَىٰ مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَّنثُورًا ٢٣","tr":"Wa qadimnaaa ilaa maa 'amiloo min 'amalin faja'alnaahu habaaa'am-manthooraa.","ref":"Surah Furqan 25:23"},{"id":588,"cat":"jinndiseases","sub":105,"ar":"فَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَسْفَلِينَ ٩٨","tr":"Fa-araadoo bihee kaidan faja'alnaahumul-asfaleen.","ref":"Surah As-Saffat 37:98"},{"id":589,"cat":"jinndiseases","sub":105,"ar":"وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ ۗ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّـهِ ۚ فَإِذَا جَاءَ أَمْرُ اللَّـهِ قُضِيَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ ٧٨","tr":"Wa laqad arsalnaa rusulam-min qablika minhum-man qasasnaa 'alaika wa minhum-mal-lam naqsus 'alaik; wa maa kaana li-Rasoolin an ya'tiya bi-aayatin illaa bi-iznillaah; fa-izaa jaaa'a amrullaahi qudiya bil-haqqi wa khasira hunaalikal-mubtiloon.","ref":"Surah Ghafir 40:78"},{"id":590,"cat":"jinndiseases","sub":105,"ar":"وَلَوْ جَعَلْنَاهُ قُرْآنًا أَعْجَمِيًّا لَّقَالُوا لَوْلَا فُصِّلَتْ آيَاتُهُ ۖ أَأَعْجَمِيٌّ وَعَرَبِيٌّ ۗ قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ ۖ وَالَّذِينَ لَا يُؤْمِنُونَ فِي آذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى ۚ أُولَـٰئِكَ يُنَادَوْنَ مِن مَّكَانٍ بَعِيدٍ ٤٤","tr":"Wa law ja'alnaahu Qur-aanan a'jamiyyal-laqaaloo lawlaa fussilat aayaatuhoo 'a-a'jamiyyun wa 'Arabiyy; qul huwa lillazeena aamanoo hudan wa shifaaa'; wallazeena laa yu'minoona feee aazaanihim waqrun wa huwa 'alaihim 'amaa; ulaaa'ika yunaadawna mim-makaanim-ba'eed.","ref":"Surah Fussilat 41:44"},{"id":591,"cat":"jinndiseases","sub":105,"ar":"إِنَّ شَجَرَتَ الزَّقُّومِ ٤٣ طَعَامُ الْأَثِيمِ ٤٤ كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ ٤٥ كَغَلْيِ الْحَمِيمِ ٤٦ خُذُوهُ فَاعْتِلُوهُ إِلَىٰ سَوَاءِ الْجَحِيمِ ٤٧ ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ ٤٨ ذُقْ إِنَّكَ أَنتَ الْعَزِيزُ الْكَرِيمُ ٤٩ إِنَّ هَـٰذَا مَا كُنتُم بِهِ تَمْتَرُونَ ٥٠","tr":"Inna shajarataz-zaqqoom. Ta'aamul-atheem. Kalmuhli yaghlee fil-butoon. Kaghalyil-hameem. Khuzoohu fa'tiloohu ilaa sawaaa'il-jaheem. Thumma subboo fawqa ra'sihee min 'azaabil-hameem. Zuq innaka antal-'Azeezul-Kareem. Inna haazaa maa kuntum bihee tamtaroon.","ref":"Sura Dukhan 44: 43-50"},{"id":592,"cat":"jinndiseases","sub":105,"ar":"وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ ٧ يَسْمَعُ آيَاتِ اللَّـهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ ٨","tr":"Wailul-likulli affaakin atheem. Yasma'u aayaatillaahi tutlaa 'alaihi thumma yusirru mustakbiran ka-al-lam yasma'haa fabashshirhu bi-'azaabin aleem.","ref":"Surah Jathiya 45: 7-8"},{"id":593,"cat":"jinndiseases","sub":105,"ar":"يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْوَاجِكُمْ وَأَوْلَادِكُمْ عَدُوًّا لَّكُمْ فَاحْذَرُوهُمْ ۚ وَإِن تَعْفُوا وَتَصْفَحُوا وَتَغْفِرُوا فَإِنَّ اللَّـهَ غَفُورٌ رَّحِيمٌ ١٤ إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ ۚ وَاللَّـهُ عِندَهُ أَجْرٌ عَظِيمٌ ١٥ فَاتَّقُوا اللَّـهَ مَا اسْتَطَعْتُمْ وَاسْمَعُوا وَأَطِيعُوا وَأَنفِقُوا خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَـٰئِكَ هُمُ الْمُفْلِحُونَ ١٦","tr":"Yaaa ayyuhal-lazeena aamanooo inna min azwaajikum wa awlaadikum 'aduwwal-lakum fahzaroohum; wa in ta'foo wa tasfahoo wa taghfiroo fa-innallaaha Ghafoorur-Raheem. Innamaaa amwaalukum wa awlaadukum fitnah; wallaahu 'indahooo ajrun 'azeem. Fattaqullaaha mastata'tum wasma'oo wa atee'oo wa anfiqoo khairal-li-anfusikum; wa man yooqa shuhha nafsihee fa-ulaaa'ika humul-muflihoon.","ref":"Surah Tagabun 64: 14-16"},{"id":594,"cat":"quranic-dua","sub":106,"ar":"رَبَّنَا أَخْرِجْنَا مِنْ هَـٰذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا وَاجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَاجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا","tr":"Rabbanaaa akhrijnaa min haazihil-qaryatiz-zaalimi ahluhaa waj'al lanaa mil-ladunka waliyyan waj'al lanaa mil-ladunka naseeraa.","ref":"Surah Nisa 4:75"},{"id":595,"cat":"quranic-dua","sub":106,"ar":"عَلَى اللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنتَ خَيْرُ الْفَاتِحِينَ","tr":"'Alallaahi tawakkalnaa; Rabbanaftah bainanaa wa baina qawminaa bil-haqqi wa Anta Khairul-Faatiheen.","ref":"Surah A'raf 7:89"},{"id":596,"cat":"quranic-dua","sub":106,"ar":"عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ ٨٥ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ ٨٦","tr":"'Alallaahi tawakkalnaa Rabbanaa laa taj'alnaa fitnatal-lil-qawmiz-zaalimeen. Wa najjinaa birahmatika minal-qawmil-kaafireen.","ref":"Surah Yunus 10: 85-86"},{"id":597,"cat":"quranic-dua","sub":106,"ar":"رَبِّ انصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ","tr":"Rabbin-surnee 'alal-qawmil-mufsideen.","ref":"Surah Ankabut 29:30"},{"id":599,"cat":"quranic-dua","sub":106,"ar":"رَبِّ نَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ","tr":"Rabbi najjinee minal-qawmiz-zaalimeen.","ref":"Surah Al-Qasas 28:21"},{"id":600,"cat":"quranic-dua","sub":106,"ar":"رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ","tr":"Rabbis-sijnu ahabbu ilaiya mimmaa yad'oonaneee ilaih; wa illaa tasrif 'annee kaidahunna asbu ilaihinna wa akum-minal-jaahileen.","ref":"Surah Yusuf 12:33"},{"id":601,"cat":"quranic-dua","sub":106,"ar":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ","tr":"Annee massaniyad-durru wa Anta Arhamur-Raahimeen.","ref":"Surah Al-Ambiya 21:83"},{"id":602,"cat":"quranic-dua","sub":106,"ar":"رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ","tr":"Rabbi najjinee wa ahlee mimmaa ya'maloon.","ref":"Surah Ash-Shu'ara 26:169"},{"id":603,"cat":"quranic-dua","sub":106,"ar":"أَنِّي مَغْلُوبٌ فَانتَصِرْ","tr":"Annee maghloobun fantasir.","ref":"Surah Qamar 54:10"},{"id":604,"cat":"quranic-dua","sub":107,"ar":"رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي","tr":"Rabbi innee zalamtu nafsee faghfir lee.","ref":"Surah Qasas 28:16"},{"id":605,"cat":"quranic-dua","sub":107,"ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ ٤٠ رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ ٤١","tr":"Rabbij-'alnee muqeemas-Salaati wa min zurriyyatee Rabbanaa wa taqabbal du'aaa'. Rabbanagh-fir lee wa liwaalidayya wa lil-mu'mineena Yawma yaqoomul-hisaab.","ref":"Surah Ibrahim 14:40-41"},{"id":606,"cat":"quranic-dua","sub":107,"ar":"رَبِّ ٱغْفِرْ لِى","tr":"Rabbigh-fir lee.","ref":"Surah Soad 38:35"},{"id":607,"cat":"quranic-dua","sub":107,"ar":"رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ","tr":"Rabbanaa waj'alnaa muslimaini laka wa min zurriyyatinaa ummatan muslimatal-laka wa arinaa manaasikanaa wa tub 'alainaa innaka Antat-Tawwaabur-Raheem.","ref":"Surah Al-Baqara 2:128"},{"id":608,"cat":"quranic-dua","sub":107,"ar":"رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ","tr":"Rabbanaaa aamannaa faghfir lanaa warhamnaa wa Anta Khairur-Raahimeen.","ref":"Surah Muminun 23:109"},{"id":609,"cat":"quranic-dua","sub":107,"ar":"رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ","tr":"Rabbigh-fir warham wa Anta Khairur-Raahimeen.","ref":"Surah Muminun 23:118"},{"id":610,"cat":"quranic-dua","sub":107,"ar":"رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ ۖ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ","tr":"Rabbigh-fir lee wa li-akhee wa adkhilnaa fee rahmatika wa Anta Arhamur-Raahimeen.","ref":"Surah Al-A'raf 7:151"},{"id":611,"cat":"quranic-dua","sub":107,"ar":"سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ","tr":"Sami'naa wa ata'naa ghufraanaka Rabbanaa wa ilaikal-maseer.","ref":"Surah Baqara 2:285"},{"id":612,"cat":"quranic-dua","sub":107,"ar":"رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ","tr":"Rabbanaaa innanaaa aamannaa faghfir lanaa zunoobanaa wa qinaa 'azaaban-Naar.","ref":"Surah Ali-Imran 3:16"},{"id":613,"cat":"quranic-dua","sub":107,"ar":"رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","tr":"Rabbanagh-fir lanaa zunoobanaa wa israafanaa feee amrinaa wa thabbit aqdaamanaa wansurnaa 'alal-qawmil-kaafireen.","ref":"Surah Ali-Imran 3:147"},{"id":614,"cat":"quranic-dua","sub":107,"ar":"رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ","tr":"Rabbanaa zalamnaaa anfusanaa wa il-lam taghfir lanaa wa tarhamnaa lanakoonanna minal-khaasireen.","ref":"Surah A'raf 7:23"},{"id":615,"cat":"quranic-dua","sub":107,"ar":"رَبِّ إِنِّي أَعُوْذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ ۖ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُن مِّنَ الْخَاسِرِينَ","tr":"Rabbi innee a'oozu bika an as'alaka maa laisa lee bihee 'ilm; wa illaa taghfir lee wa tarhamneee akum-minal-khaasireen.","ref":"Surah Hud 11:47"},{"id":616,"cat":"quranic-dua","sub":107,"ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ","tr":"Rabbanagh-fir lanaa wa li-ikhwaaninallazeena sabaqoonaa bil-eemaani wa laa taj'al fee quloobinaa ghillal-lillazeena aamanoo Rabbanaaa innaka Ra'oofur-Raheem.","ref":"Surah Hashr 59:10"},{"id":617,"cat":"quranic-dua","sub":107,"ar":"رَّبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَن دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَلَا تَزِدِ الظَّالِمِينَ إِلَّا تَبَارًا","tr":"Rabbigh-fir lee wa liwaalidayya wa liman dakhala baitiya mu'minan wa lil-mu'mineena wal-mu'minaat; wa laa tazidiz-zaalimeena illaa tabaaraa.","ref":"Surah Nooh 71:28"},{"id":924,"cat":"quranic-dua","sub":107,"ar":"اَللَّهُمَّ اغْفِرْ لِي خَطِيْئَتِي وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي اَللَّهُمَّ اغْفِرْ لِي هَزْلِي وَجِدِّي وَخَطَايَايَ وَعَمْدِي وَكُلُّ ذَلِكَ عِنْدِي","tr":"Allaahummaghfir lee khatee a-tee wa jahlee, wa israafee fee amree, wa maa anta a‛lamu bihi minnee, Allaahumma-ghfir lee hazlee wa jiddee wa khataayaaya wa ‛amdee, wa kullu dhaalika ‛indee.","ref":"Bukhari: 6399"},{"id":618,"cat":"quranic-dua","sub":108,"ar":"رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ١٩١ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ١٩٢ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ١٩٣ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ١٩٤","tr":"Rabbanaa maa khalaqta haazaa baatilan Subhaanaka faqinaa 'azaaban-Naar. Rabbanaa innaka man tudkhilin-Naara faqad akhzaitahoo wa maa lizzaalimeena min ansaar. Rabbanaa innanaa sami'naa munaadiyan yunaadee lil-eemaani an aaminoo bi-Rabbikum fa-aamannaa; Rabbanaa faghfir lanaa zunoobanaa wa kaffir 'annaa sayyi-aatinaa wa tawaffanaa ma'al-abraar. Rabbanaa wa aatinaa maa wa'adtanaa 'alaa rusulika wa laa tukhzinaa Yawmal-Qiyaamah; innaka laa tukhliful-mee'aad.","ref":"Surah Ali-Imran 3:191-194"},{"id":619,"cat":"quranic-dua","sub":108,"ar":"رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ ٨٣ وَاجْعَل لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ ٨٤ وَاجْعَلْنِي مِن وَرَثَةِ جَنَّةِ النَّعِيمِ ٨٥","tr":"Rabbi hab lee hukman wa alhiqnee bis-saaliheen. Waj'al lee lisaana sidqin fil-aakhireen. Waj'alnee min warathati Jannatin-Na'eem.","ref":"Surah Shu'ara 26:83-85"},{"id":620,"cat":"quranic-dua","sub":108,"ar":"وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ ٨٧ يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ ٨٨ إِلَّا مَنْ أَتَى اللَّـهَ بِقَلْبٍ سَلِيمٍ ٨٩","tr":"Wa laa tukhzinee Yawma yub'athoon. Yawma laa yanfa'u maalun wa laa banoon. Illaa man atallaaha biqalbin saleem.","ref":"Surah Shu'ara 26:87-89"},{"id":621,"cat":"quranic-dua","sub":108,"ar":"رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ ٤ رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا ۖ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ٥","tr":"Rabbanaa 'alaika tawakkalnaa wa ilaika anabnaa wa ilaikal-maseer. Rabbanaa laa taj'alnaa fitnatal-lillazeena kafaroo waghfir lanaa Rabbanaa innaka Antal-'Azeezul-Hakeem.","ref":"Surah Mumtahina 60:4-5"},{"id":622,"cat":"quranic-dua","sub":108,"ar":"رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا ۖ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ","tr":"Rabbanaaa atmim lanaa nooranaa waghfir lanaa innaka 'alaa kulli shai'in Qadeer.","ref":"Surah Tahrim 66:8"},{"id":623,"cat":"quranic-dua","sub":108,"ar":"رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ","tr":"Rabbi laa tazarnee fardan wa Anta Khairul-waaritheen.","ref":"Surah Ambiya 21:89"},{"id":625,"cat":"quranic-dua","sub":108,"ar":"لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ","tr":"Laaa ilaaha illaa Anta Subhaanaka innee kuntu minaz-zaalimeen.","ref":"Surah Al-Ambiya 21:87"},{"id":626,"cat":"quranic-dua","sub":108,"ar":"رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","tr":"Rabbanaa laa tu'aakhiznaaa in naseenaaa aw akhta'naa; Rabbanaa wa laa tahmil 'alainaa isran kamaa hamaltahoo 'alal-lazeena min qablinaa; Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih; wa'fu 'annaa waghfir lanaa warhamnaa; Anta Mawlaanaa fansurnaa 'alal-qawmil-kaafireen.","ref":"Surah Al-Baqara 2:286"},{"id":628,"cat":"quranic-dua","sub":108,"ar":"رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِدِينَ","tr":"Rabbanaaa aamannaa faktubnaa ma'ash-shaahideen.","ref":"Surah Al-Maidah 5:83"},{"id":629,"cat":"quranic-dua","sub":108,"ar":"حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ","tr":"Hasbiyallaahu laaa ilaaha illaa Huwa 'alaihi tawakkaltu wa Huwa Rabbul-'Arshil-'Azeem.","ref":"Surah At-Tawbah 9:129"},{"id":630,"cat":"quranic-dua","sub":108,"ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ","tr":"Rabbanaaa afrigh 'alainaa sabran wa tawaffanaa muslimeen.","ref":"Surah Al-A'raf 7:126"},{"id":631,"cat":"quranic-dua","sub":108,"ar":"رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّايَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا ۖ إِنْ هِيَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَاءُ وَتَهْدِي مَن تَشَاءُ ۖ أَنتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا ۖ وَأَنتَ خَيْرُ الْغَافِرِينَ ١٥٥ وَاكْتُبْ لَنَا فِي هَـٰذِهِ الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ إِنَّا هُدْنَا إِلَيْكَ ۚ ١٥٦","tr":"Rabbi law shi'ta ahlaktahum-min qablu wa iyyaay; atuhlikunaa bimaa fa'alas-sufahaaa'u minnaa; in hiya illaa fitnatuka tudillu bihaa man tashaaa'u wa tahdee man tashaaa'; Anta waliyyunaa faghfir lanaa warhamnaa wa Anta Khairul-Ghaafireen. Waktub lanaa fee haazihid-dunyaa hasanatan wa fil-Aakhirati innaa hudnaaa ilaik.","ref":"Surah Al-A'raf 7:155-156"},{"id":632,"cat":"quranic-dua","sub":108,"ar":"رَبِّ إِنِّى وَهَنَ الْعَظْمُ مِنِّى وَاشْتَعَلَ الرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا","tr":"Rabbi innee wahanal-'azmu minnee washta'alar-ra'su shaiban wa lam akum-bidu'aaa'ika Rabbi Shaqiyyaa.","ref":"Surah Maryam 19:4"},{"id":633,"cat":"quranic-dua","sub":108,"ar":"رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ","tr":"Rabbanaa wasi'ta kulla shai'ir-rahmatan wa 'ilman faghfir lillazeena taaboo wattaba'oo sabeelaka wa qihim 'azaabal-Jaheem.","ref":"Surah Ghafir 40:7"},{"id":634,"cat":"quranic-dua","sub":108,"ar":"رَبِّ بِمَا أَنْعَمْتَ عَلَيَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ","tr":"Rabbi bimaaa an'amta 'alayya falan akoona zaheeral-lil-mujrimeen.","ref":"Surah Al-Qasas - 28:17"},{"id":636,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","tr":"Rabbanaaa aatinaa fid-dunyaa hasanatan wa fil-Aakhirati hasanatan wa qinaa 'azaaban-Naar.","ref":"Surah Baqara 2:201"},{"id":637,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَّدُنْكَ رَحْمَةً ۚ إِنَّكَ أَنْتَ الْوَهَّابُ","tr":"Rabbanaa laa tuzigh quloobanaa ba'da iz hadaitanaa wa hab lanaa mil-ladunka rahmah; innaka Antal-Wahhaab.","ref":"Surah Ali-Imran 3:8"},{"id":638,"cat":"quranic-dua","sub":109,"ar":"اللَّـهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ ۖ بِيَدِكَ الْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ","tr":"Allaahumma Maalikul-mulki tu'til-mulka man tashaaa'u wa tanzi'ul-mulka mimman tashaaa'u wa tu'izzu man tashaaa'u wa tuzillu man tashaaa'u biyadikal-khair; innaka 'alaa kulli shai'in Qadeer.","ref":"Surah Ali-Imran 3:26"},{"id":639,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ","tr":"Rabbanaaa aamannaa bimaaa anzalta wattaba'nar-Rasoola faktubnaa ma'ash-shaahideen.","ref":"Surah Ali-Imran 3:53"},{"id":641,"cat":"quranic-dua","sub":109,"ar":"رَّبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا","tr":"Rabbi adkhilnee mudkhala sidqin wa akhrijnee mukhraja sidqin waj'al lee mil-ladunka sultaanan naseeraa.","ref":"Surah Isra 17:80"},{"id":642,"cat":"quranic-dua","sub":109,"ar":"رَبِّ اشْرَحْ لِي صَدْرِي ٢٥ وَيَسِّرْ لِي أَمْرِي ٢٦ وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي ٢٧ يَفْقَهُوا قَوْلِي ٢٨","tr":"Rabbish-rah lee sadree. Wa yassir leee amree. Wahlul 'uqdatam-mil-lisaanee. Yafqahoo qawlee.","ref":"Surah Ta Ha 20:25-28"},{"id":643,"cat":"quranic-dua","sub":109,"ar":"رَّبِّ زِدْنِي عِلْمًا","tr":"Rabbi zidnee 'ilmaa.","ref":"Surah Ta Ha 20:114"},{"id":644,"cat":"quranic-dua","sub":109,"ar":"رَبِّ احْكُم بِالْحَقِّ ۗ وَرَبُّنَا الرَّحْمَـٰنُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ","tr":"Rabbih-kum bil-haqq; wa Rabbunar-Rahmaanul-Musta'aanu 'alaa maa tasifoon.","ref":"Surah Ambiya 21:112"},{"id":645,"cat":"quranic-dua","sub":109,"ar":"رَّبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ ٩٧ وَأَعُوْذُ بِكَ رَبِّ أَن يَحْضُرُونِ ٩٨","tr":"Rabbi a'oozu bika min hamazaatish-Shayaateen. Wa a'oozu bika Rabbi ay-yahduroon.","ref":"Surah Muminun 23:97-98"},{"id":646,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ٦٥ إِنَّهَا سَاءَتْ مُسْتَقَرًّا وَمُقَامًا ٦٦","tr":"Rabbanas-rif 'annaa 'azaaba Jahannama inna 'azaabahaa kaana gharaamaa. Innahaa saaa'at mustaqarran wa muqaamaa.","ref":"Surah Furqan 25:65-66"},{"id":647,"cat":"quranic-dua","sub":109,"ar":"رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ","tr":"Rabbi innee limaaa anzalta ilaiya min khairin faqeer.","ref":"Surah Qasas 28:24"},{"id":648,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ","tr":"Rabbanaa taqabbal minnaa innaka Antas-Samee'ul-'Aleem.","ref":"Surah Al-Baqara 2:127"},{"id":649,"cat":"quranic-dua","sub":109,"ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ","tr":"Rabbij-'alnee muqeemas-Salaati wa min zurriyyatee Rabbanaa wa taqabbal du'aaa'.","ref":"Surah Ibrahim 14:40"},{"id":650,"cat":"quranic-dua","sub":109,"ar":"رَبِّ هَبْ لِى مِنَ الصّٰلِحِينَ","tr":"Rabbi hab lee minas-saaliheen.","ref":"Surah As-Saffat 37:100"},{"id":654,"cat":"quranic-dua","sub":109,"ar":"عَسَىٰ رَبِّي أَن يَهْدِيَنِي سَوَاءَ السَّبِيلِ","tr":"'Asaa Rabbeee ay-yahdiyanee sawaaa'as-sabeel.","ref":"Surah Al-Qasas 28:22"},{"id":655,"cat":"quranic-dua","sub":109,"ar":"أَعُوْذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ","tr":"A'oozu billaahi an akoona minal-jaahileen.","ref":"Surah Al-Baqara 2:67"},{"id":656,"cat":"quranic-dua","sub":109,"ar":"رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ","tr":"Rabbij-'al haazaa baladan aaminan warzuq ahlahoo minath-thamaraati man aamana minhum billaahi wal-Yawmil-Aakhir.","ref":"Surah Al-Baqara 2:126"},{"id":657,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى القَوْمِ الكَافِرِينَ","tr":"Rabbanaaa afrigh 'alainaa sabran wa thabbit aqdaamanaa wansurnaa 'alal-qawmil-kaafireen.","ref":"Surah Al-Baqara 2:250"},{"id":658,"cat":"quranic-dua","sub":109,"ar":"فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ","tr":"Fafruq bainanaa wa bainal-qawmil-faasiqeen.","ref":"Surah Al-Maidah 5:25"},{"id":659,"cat":"quranic-dua","sub":109,"ar":"وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ","tr":"Warzuqnaa wa Anta Khairur-Raaziqeen.","ref":"Surah Al-Maidah 5:114"},{"id":660,"cat":"quranic-dua","sub":109,"ar":"لَئِنْ آتَيْتَنَا صَالِحًا لَّنَكُونَنَّ مِنَ الشَّاكِرِينَ","tr":"La'in aataitanaa saalihan lanakoonanna minash-shaakireen.","ref":"Surah Al-A'raf 7:189"},{"id":661,"cat":"quranic-dua","sub":109,"ar":"لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ","tr":"La'in anjaitanaa min haazihee lanakoonanna minash-shaakireen.","ref":"Surah Yunus 10:22"},{"id":662,"cat":"quranic-dua","sub":109,"ar":"بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآۚ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ","tr":"Bismillaahi majraihaa wa mursaahaa; inna Rabbee la-Ghafoorur-Raheem.","ref":"Surah Hud 11:41"},{"id":663,"cat":"quranic-dua","sub":109,"ar":"مَعَاذَ اللَّهِ ۖ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ ۖ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ","tr":"Ma'aazallaahi innahoo Rabbeee ahsana mathwaay; innahoo laa yuflihuz-zaalimoon.","ref":"Surah Yusuf 12:23"},{"id":664,"cat":"quranic-dua","sub":109,"ar":"فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ ۖ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","tr":"Faatiras-samaawaati wal-ardi Anta Waliyyee fid-dunyaa wal-Aakhirah; tawaffanee musliman wa alhiqnee bis-saaliheen.","ref":"Surah Yusuf 12:101"},{"id":665,"cat":"quranic-dua","sub":109,"ar":"وَإِنِّي خِفْتُ الْمَوَالِيَ مِن وَرَائِي وَكَانَتِ امْرَأَتِي عَاقِرًا فَهَبْ لِي مِن لَّدُنكَ وَلِيًّا","tr":"Wa innee khiftul-mawaaliya min waraaa'ee wa kaanatim-ra'atee 'aaqiran fahab lee mil-ladunka waliyyaa.","ref":"Surah Maryam 19:5"},{"id":666,"cat":"quranic-dua","sub":109,"ar":"رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","tr":"Rabbir-hamhumaa kamaa rabbayaanee sagheeraa.","ref":"Surah Al-Isra 17:24"},{"id":667,"cat":"quranic-dua","sub":109,"ar":"رَبِّ انصُرْنِي","tr":"Rabbin-surnee.","ref":"Surah Al-Mu'minun 23:26"},{"id":668,"cat":"quranic-dua","sub":109,"ar":"رَّبِّ أَنزِلْنِي مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ الْمُنزِلِينَ","tr":"Rabbi anzilnee munzalam-mubaarakan wa Anta Khairul-munzileen.","ref":"Surah Al-Mu'minun 23:29"},{"id":669,"cat":"quranic-dua","sub":109,"ar":"رَبِّ فَلَا تَجْعَلْنِي فِي الْقَوْمِ الظَّالِمِينَ","tr":"Rabbi falaa taj'alnee fil-qawmiz-zaalimeen.","ref":"Surah Al-Mu'minun 23:94"},{"id":670,"cat":"quranic-dua","sub":109,"ar":"فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا وَنَجِّنِي وَمَن مَّعِيَ مِنَ الْمُؤْمِنِينَ","tr":"Faftah bainee wa bainahum fat-han wa najjinee wa man ma'iya minal-mu'mineen.","ref":"Surah Ash-Shu'ara 26:118"},{"id":671,"cat":"quranic-dua","sub":109,"ar":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ","tr":"Rabbanaa wa adkhilhum jannaati 'adninil-latee wa'adtahum wa man salaha min aabaaa'ihim wa azwaajihim wa zurriyyaatihim; innaka Antal-'Azeezul-Hakeem.","ref":"Surah Ghafir 40:8"},{"id":672,"cat":"quranic-dua","sub":109,"ar":"وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ","tr":"Wa qihimus-sayyi-aat; wa man taqis-sayyi-aati Yawma'izin faqad rahimtah; wa zaalika huwal-fawzul-'azeem.","ref":"Surah Ghafir 40:9"},{"id":673,"cat":"quranic-dua","sub":109,"ar":"إِنِّي عُذْتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ الْحِسَابِ","tr":"Innee 'uztu bi-Rabbee wa Rabbikum-min kulli mutakabbiril-laa yu'minu bi-Yawmil-Hisaab.","ref":"Surah Ghafir 40:27"},{"id":674,"cat":"quranic-dua","sub":109,"ar":"وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ ۚ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ","tr":"Wa ufawwidu amreee ilallaah; innallaaha baseerum-bil-'ibaad.","ref":"Surah Ghafir 40:44"},{"id":675,"cat":"quranic-dua","sub":109,"ar":"رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ","tr":"Rabbib-ni lee 'indaka baitan fil-Jannati.","ref":"Surah At-Tahrim 66:11"},{"id":676,"cat":"quranic-dua","sub":109,"ar":"رَّبِّ لَا تَذَرْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّارًا","tr":"Rabbi laa tazar 'alal-ardi minal-kaafireena dayyaaraa.","ref":"Surah Nooh 71:26"},{"id":677,"cat":"greatest-name-of-allah","sub":110,"ar":"اَللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ أَنْزَلْتَهُ فِي كِتَبِكَ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِي وَنُوْرَ بَصَرِيْ (وَنُورَ صَدْرِي) وَجَلَاءَ حُزْنِيْ وَذَهَابَ هَمِّيْ","tr":"Allaahumma 'innee 'abduka, wabnu 'abdika, wabnu 'amatika, naasiyatee biyadika, maadhin fiyya hukmuka, 'adlun fiyya qadhaa'uka, 'as'aluka bikulli ismin huwa laka, sammayta bihi nafsaka, 'aw 'anzaltahu fee kitaabika, 'aw 'allamtahu 'ahadan min khalqika, 'aw ista'tharta bihi fee 'ilmil-ghaybi 'indaka, 'an taj'alal-Qur'aana rabee'a qalbee, wa noora basaree (in another narration it is 'sadree' instead of 'basaree'), wa jalaa'a huznee, wa dhahaaba hammee","ref":"[1] Ahmad 1/391, and Al-Albani graded it authentic in Sahihah 1/337 [2] Sahih Ibn Hibban 3/253"},{"id":678,"cat":"greatest-name-of-allah","sub":110,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اَللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ اَلَّذِي لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","tr":"Allaahumma 'innee 'as'aluka bi'anni 'ash-hadu 'annaka 'AntAllahu laa 'ilaaha 'illaa 'Antal-'Ahadus-Samadul-ladhee lam yalid wa lam youlad wa lam yakun lahu kufuwan 'Ahad","ref":"Sahih. Tirmidhi: 3475"},{"id":679,"cat":"greatest-name-of-allah","sub":110,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ","tr":"Allaahumma inni as'aluka bi-anna lakal-hamda, laa ilaaha illaa antal-mannaanu badi'us-samaawaati wal-ardi, yaa dhal-jalaali wal-ikraam! Yaa ‘hayyu yaa qayyum inni as aluk","ref":"Sahih (Albani). Nasai: 1300"},{"id":680,"cat":"greatest-name-of-allah","sub":110,"ar":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِيْنَ","tr":"Laa 'ilaaha 'illaa 'Anta sub’haanaka 'innee kuntu minadh-dhaalimeen","ref":"Sahih. Tirmidhi: 3505"},{"id":681,"cat":"greatest-name-of-allah","sub":110,"ar":"وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لَا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ","tr":"Wa ilaahukum ilaahun wa-hidun laa ilaaha illaa huwar-rahmaanur raheem","ref":"Sunan Abu Dawud: 1496"},{"id":682,"cat":"greatest-name-of-allah","sub":110,"ar":"الم. اَللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ","tr":"Alif-Lam-Mim. Allahu Laa ilaaha illaa Huwa Al-Haiyyul-Qaiyyum","ref":"Sunan Abu Dawud: 1496"},{"id":683,"cat":"greatest-name-of-allah","sub":110,"ar":"وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ","tr":"Wa 'anatil wujoohu lilhayyil qayyoom","ref":"Sahih (Albani). Sahih Al Jami: 1025"},{"id":685,"cat":"prophets-dua","sub":111,"ar":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ","tr":"Annee massaniyad-durru wa Anta Arhamur-Raahimeen.","ref":"Surah Al-Ambiya 21:83"},{"id":686,"cat":"prophets-dua","sub":111,"ar":"لَا إِلَـٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ","tr":"Laaa ilaaha illaa Anta Subhaanaka innee kuntu minaz-zaalimeen.","ref":"Surah Al-Ambiya 21:87"},{"id":689,"cat":"prophets-dua","sub":111,"ar":"فَاللَّـهُ خَيْرٌ حَافِظًا ۖ وَهُوَ أَرْحَمُ الرَّاحِمِينَ","tr":"Fallaahu khairun haafizaa; wa Huwa Arhamur-Raahimeen.","ref":"Surah Yusuf 12:64"},{"id":690,"cat":"prophets-dua","sub":111,"ar":"فَصَبْرٌ جَمِيلٌ ۖ عَسَى اللَّـهُ أَن يَأْتِيَنِي بِهِمْ جَمِيعًا ۚ إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ","tr":"Fasabrun jameel; 'asallaahu ay-ya'tiyanee bihim jamee'aa; innahoo Huwal-'Aleemul-Hakeem.","ref":"Surah Yusuf 12:83"},{"id":691,"cat":"prophets-dua","sub":111,"ar":"رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ الْجَاهِلِينَ","tr":"Rabbis-sijnu ahabbu ilaiya mimmaa yad'oonaneee ilaih; wa illaa tasrif 'annee kaidahunna asbu ilaihinna wa akum-minal-jaahileen.","ref":"Surah Yusuf 12:33"},{"id":694,"cat":"prophets-dua","sub":111,"ar":"رَبِّ بِمَا أَنْعَمْتَ عَلَيَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ","tr":"Rabbi bimaaa an'amta 'alayya falan akoona zaheeral-lil-mujrimeen.","ref":"Surah Al-Qasas 28:17"},{"id":695,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","tr":"Allaahumma aatinaa fid-dunyaa hasanatan, wa fil-aakhirati hasanatan, wa qinaa ‘adhaaban-Naar","ref":"Muslim: 2690"},{"id":696,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ وَفِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ وَشَرِّ فِتْنَةِ الْغِنَى وَشَرِّ فِتْنَةِ الْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ اَللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالْبَرَدِ وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَاىَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَالْمَأْثَمِ وَالْمَغْرَمِ","tr":"Allaahumma inni A‛oodhu bika min fitnatin-naar, wa 'adhaabin-naar, wa fitnatil-qabr wa 'adhaabil-qabr, wa sharri fitnatil-ghina, wa sharri fitnatil-faqr, Allaahumma inni A‛oodhu bika min sharri fitnatil-masihid-dajjaal. Allaahummaghsil qalbi bimaa'ith-thalji wal-barad, wa naqqi qalbi minal-khata-yaa kamaa naqqaytath-thawbal-abyada minad-danas. Wa baa'id bayni wa bayna khata-ya-ya kamaa baa'adta baynal-mashriqi wal-maghrib. Allaahumma inni A‛oodhu bika minal-kasali wal-ma'thami wal-maghram","ref":"Bukhari: 6377"},{"id":697,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْهَرَمِ وَالْبُخْلِ وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ","tr":"Allaahumma inni A‛oodhu bika minal-'ajzi, wal-kasali, wal-jubni, wal-harami, wal-bukhli, wa A‛oodhu bika min 'adhaabil-qabr, wa min fitnatil-mahyaa wal-mamaat","ref":"Bukhari: 6367, Muslim: 2706"},{"id":699,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ اَللَّهُمَّ آتِ نَفْسِيْ تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا","tr":"Allaahumma innee a‛oodhu bika minal-‛ajzi wal-kasali, wal-jubni wal-bukhli, wal-harami wa ‛adhaabil-qabr, Allaahumma aati nafsee taqwaahaa wa zakkihaa anta khairu man zakkaahaa anta waliyuhaa wa mawlaahaa, Allaahumma inni a‛oodhu bika min ‛ilmin laa yanfa‛u, wa min qalbin laa yakh-sha‛u, wa min nafsin laa tashba‛u, wa min da‛wat-in laa yustajaabu lahaa","ref":"Muslim: 2722"},{"id":700,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ","tr":"Allaahumma inni A‛oodhu bika min zawaali ni'matika, wa tahawwuli 'aafiyatika, wa fuja-aati niqmatika, wa jami'i sakhatik","ref":"Muslim: 2739"},{"id":701,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ","tr":"Allaahumma, inni A‛oodhu bika min sharri maa 'amiltu, wa min sharri maa lam a'mal","ref":"Muslim: 2716"},{"id":703,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","tr":"Allaahumma, inni as'alukal-hudaa wat- tuqaa wal-'afaafa wal-ghinaa","ref":"Muslim: 2721"},{"id":704,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اهْدِنِيْ وَسَدِّدْنِي","tr":"Allaahummah dini wa-saddidni","ref":"Muslim: 2725"},{"id":705,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالسَّدَادَ","tr":"Allaahumma inni as'alukal huda was-sadaad","ref":"Muslim: 2725"},{"id":706,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ","tr":"Allaahumma Akthir Maalahu Wa waladahu wa baarik lahu Fimaa a'taitahu","ref":"Bukhari: 6344"},{"id":707,"cat":"duas-of-hadith","sub":112,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيْمُ الْحَلِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","tr":"Laa ilaaha illallahul 'azimul halim Laa ilaaha illaallahu Rabbul 'arshil-'azim, Laa ilaaha illaallahu Rabbu-s-samaawaati wa Rabbul ardi, wa Rabbul 'arsh-il-Karim","ref":"Bukhari: 6346"},{"id":708,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ عَافِنِيْ فِي بَدَنِي اَللَّهُمَّ عَافِنِيْ فِي سَمْعِيْ اَللَّهُمَّ عَافِنِيْ فِي بَصَرِيْ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allaahumma 'aafinee fee badanee, Allaahumma 'aafinee fee sam'ee, Allaahumma 'aafinee fee basaree, laa 'ilaaha 'illaa 'Anta","ref":"Hasan. Abu Dawud: 5090"},{"id":709,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allaahumma 'innee 'a'oodhu bika minal-kufri, wal-faqr, Allaahumma 'innee 'a'oodhu bika min 'adhaabil-qabr, laa 'ilaaha 'illaa 'Anta","ref":"Hasan. Abu Dawud: 5090"},{"id":710,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ لَا إِلَهَ إِلاَّ أَنْتَ","tr":"Allaahumma rahmataka 'arjoo falaa takilnee 'ilaa nafsee tarfata 'aynin, wa 'aslih lee sha'nee kullahu, laa 'ilaaha 'illaa 'Anta","ref":"Hasan. Abu Dawud: 5090"},{"id":712,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُلِّ اِسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِي وَنُورَ صَدْرِي وَجَلَاءَ حُزْنِيْ وَذَهَابَ هَمِّيْ","tr":"Allaahumma 'innee 'abduka, wabnu 'abdika, wabnu 'amatika, naasiyatee biyadika, maadhin fiyya hukmuka, 'adlun fiyya qadhaa'uka, 'as'aluka bikulli ismin huwa laka, sammayta bihi nafsaka, 'aw 'allamtahu 'ahadan min khalqika, 'aw 'anzaltahu fee kitaabika, 'aw ‘ista'tharta bihi fee 'ilmil-ghaybi 'indaka, 'an taj'alal-Qur'aana rabee'a qalbee, wa noora sadree, wa jalaa'a huznee, wa dhahaaba hammee","ref":"Sahih (Albani). Silsilatul Sahiha: 199"},{"id":713,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ مُصَرِّفَ الْقُلُوْبِ صَرِّفْ قُلُوْبَنَا عَلَى طَاعَتِكَ","tr":"Allaahumma musarrifal-qulubi, sarrif qulubanaa 'alaa taa'atik","ref":"Muslim: 2655"},{"id":714,"cat":"duas-of-hadith","sub":112,"ar":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِيْنِكَ","tr":"Ya Muqallibal-qulub, thabbit qalbi 'alaa dinik","ref":"Sahih. Tirmidhi: 3522"},{"id":716,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْاَخِرَةِ","tr":"Allaahumma a’hsin ‘aqibatanaa fil-umuri kullihaa, wa a'jirnaa min khizy'id dunyaa wa adhaabil akhirah","ref":"Sahih (Suyuti). Jami' as-Sagir: 1450"},{"id":717,"cat":"duas-of-hadith","sub":112,"ar":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَىَّ وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَىَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَىَّ وَاهْدِنِيْ وَيَسِّرِ الْهُدَى لِي وَانْصُرْنِيْ عَلَى مَنْ بَغَى عَلَىَّ رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا لَكَ ذَكَّارًا لَكَ رَهَّابًا لَكَ مِطْوَاعًا لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيبًا رَبِّ تَقَبَّلْ تَوْبَتِيْ وَاغْسِلْ حَوْبَتِيْ وَأَجِبْ دَعْوَتِيْ وَثَبِّتْ حُجَّتِيْ وَسَدِّدْ لِسَانِيْ وَاهْدِ قَلْبِيْ وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","tr":"Rabbi! A'inni wa laa tu'in 'alayya, wansurni wa laa tansur 'alayya, wamkurli wa la tamkur 'alayya, wahdini wa yassiril-huda li, wansurni 'alaa man bagha 'alayya. Rabbij'alni laka shakkaran laka dhakkaran, laka rahhaban, laka mitwaa'an, laka mukhbitan, 'ilayka awwaahan muniban. Rabbi! Taqabbal tawbati, waghsil ‘hawbati wa ajib da'wati, wa thabbit hujjati, wa saddid lisaani, wahdi qalbi, waslul sakhimata sadri","ref":"Sahih. Tirmidhi: 3551"},{"id":718,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ وَنَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَ بِكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ وَأَنْتَ الْمُسْتَعَانُ وَعَلَيْكَ الْبَلَاغُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Allaahumma inna nas’aluka min khairi maa sa’alaka minhu nabiyyuka Muhammadun, wa nA‛oodhu bika min sharri masta 'aadha bika minhu nabiyyuka Muhammadun, wa antal-musta'aanu wa 'alaikal-balagh, wa laa hawla wa laa quwwata illaa billaah","ref":"Hasan (Ash-Shawkani). Tuhfatuz Zakirin: 489"},{"id":720,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ سَمْعِيْ وَمِنْ شَرِّ بَصَرِيْ وَمِنْ شَرِّ لِسَانِيْ وَمِنْ شَرِّ قَلْبِيْ وَمِنْ شَرِّ مَنِيِّيْ","tr":"Allaahumma innee A‛oodhu bika min sharri sam‛ee, wa min sharri basaaree, wa min sharri lisaanee, wa min sharri qalbee, wa min sharri mani-yee","ref":"Sahih. Tirmidhi: 3492"},{"id":721,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبَرَصِ وَالْجُنُوْنِ وَالْجُذَامِ وَمِنْ سَيِّئِ الْأَسْقَامِ","tr":"Allaahumma inni A‛oodhu bika minal-barasi wal-jununi wal-judhaami, wamin sayy'il-asqaam","ref":"Sahih. Abu Dawud: 1554"},{"id":722,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ وَالْأَدْوَاءِ","tr":"Allaahumma inni a`udhu bika min munkaraatil-akhlaaqi wal-a`maali wal-ahwaa'i wal-adwaa'i","ref":"Sahih. Mishkat: 2405"},{"id":723,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","tr":"Allaahumma innaka `Afuwwun Karimun, tuhibbul-`afwa fa`fu `anni","ref":"Sahih. Tirmidhi: 3513"},{"id":724,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ وَتَرْكَ الْمُنْكَرَاتِ وَحُبَّ الْمَسَاكِيْنِ وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي وَإِذَا أَرَدْتَ فِتْنَةَ قَوْمٍ فَتَوَفَّنِيْ غَيْرَ مَفْتُوْنٍ وَأَسْأَلُكَ حُبَّكَ وَحُبَّ مَنْ يُحِبُّكَ وَحُبَّ عَمَلٍ يُقَرِّبُ إِلَى حُبِّكَ","tr":"Allaahumma innee as’aluka fi’lal-khairaati, wa tarkal-munkaraati, wa hubbal-masaakeeni, wa ‘an taghfira lee wa tar’hamanee wa idhaa aradta fitnata qawmin fa-tawaffanee ghaira maf-toon, Wa as’aluka ’hubbaka wa ’hubba man yu’hibbuka, wa ’hubba ‛amalin yuqarribu ilaa h‛ubbik","ref":"[1] That is: the deeds by which sins are forgiven [2] Sahih. Tirmidhi: 3235"},{"id":725,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ احْفَظْنِيْ بِالْإِسْلَامِ قَائِمًا وَاحْفَظْنِيْ بِالْإِسْلَامِ قَاعِدًا وَاحْفَظْنِيْ بِالْإِسْلَامِ رَاقِدًا وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَاسِدًا اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ وَأَعُوْذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ","tr":"Allaahumma’h-fazni bil’islaami qaa’iman, wa’h-fazni bil’islaami qaa‛idan, wa’h-fazni bil’islaami raa-qidan, wa laa tushmit bee ‛adu-wan wa laa ’haasidan, Allaahumma innee as’aluka min kulli khayrin khazaa’inuhu bi-yadik, wa a‛oodhu bika min kulli sharrin khazaa’inuhu biyadik","ref":"Hasan (Albani). Silsilatul Sahiha: 1540"},{"id":726,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُوْلُ بَيْنَنَا وَبَيْنَ مَعَاصِيْكَ وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ وَمِنَ الْيَقِيْنِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيْبَاتِ الدُّنْيَا وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا وَاجْعَلْهُ الْوَارِثَ مِنَّا وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا وَانْصُرْنَا عَلَى مَنْ عَادَانَا وَلَا تَجْعَلْ مُصِيْبَتَنَا فِي دِيْنِنَا وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا","tr":"Allaahumma-qsim lanaa min khashyatika maa ya’hulu, bainanaa wa baina ma’aasika wa min taa’atika maa tuballighunaa bihi jannataka, wa minal-yaqini maa tuhawwinu bihi ‘alainaa musibaatid-dunyaa, wa matti’naa bi-asmaa’inaa wa absarinaa wa quwwatinaa maa a’hyaytanaa, waj’alhul-waaritha minnaa, waj’al tha’ranaa ‘alaa man zalamanaa, wansurnaa ‘alaa man ‘aadaanaa, wa laa taj’al musibatanaa fi dininaa, wa laa taj’alid-dunyaa akbara hamminaa wa laa mablagha ‘ilminaa, wa laa tusallit ‘alainaa man laa yar’hamunaa","ref":"Hasan. Tirmidhi: 3502"},{"id":727,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبُخْلِ وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَأَعُوْذُ بِكَ مِنْ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ","tr":"Allaahumma 'innee 'a'oodhu bika minal-bukhli, wa 'a'oodhu bika minal-jubni, wa 'a'oodhu bika min 'an 'uradda 'ilaa 'ardhalil-'umuri, wa 'a'oodhu bika min fitnatid-dunyaa wa 'a'oodhu bika min 'adhaabil-qabr","ref":"Bukhari: 6370"},{"id":728,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اغْفِرْ لِي خَطِيْئَتِيْ وَجَهْلِيْ وَإِسْرَافِي فِي أَمْرِيْ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي اَللَّهُمَّ اغْفِرْ لِي جِدِّيْ وَهَزَلِيْ وَخَطَئِيْ وَعَمْدِيْ وَكُلُّ ذَلِكَ عِنْدِيْ اَللَّهُمَ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ","tr":"Allahumm-aghfir li khati'ati, wa jahli, wa israafi fi amri, wa maa Anta a'lamu bihi minni. Allahumm-aghfir li jiddi wa hazali, wa khata'i wa 'amdi, wa kullu dhalika 'indi. Allahumm-aghfir li maa qaddamtu wa maa akhkhartu, wa maa asrartu, wa maa a'lantu, wa maa Anta a'lamu bihi minni. Antal-Muqaddimu, wa Antal-Mu'akhkhiru; wa Anta 'alaa kulli shai'in Qadir","ref":"Muslim: 2719"},{"id":729,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيْرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِّنْ عِنْدِكَ وَارْحَمْنِيْ إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","tr":"Allaahumma inni zalamtu nafsi zulman kathiran wa laa yaghfirudh-dhunuba illaa Anta, faghfir li maghfiratan min 'indika warhamni, innaka Antal-Ghafurur-Rahim","ref":"Bukhari: 834"},{"id":730,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ اَللَّهُمَّ إِنِّي أَعُوْذُ بِعِزَّتِكَ لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِيْ أَنْتَ الْحَيُّ الَّذِيْ لَا يَمُوْتُ وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ","tr":"Allaahumma laka aslamtu, wabika aamantu, wa ‘alayka tawakkaltu, wa ilayka anabtu, wabika khaasamtu, Allaahumma Innee a‘oodhu bi‘izzatika, laa ’ilaaha ’illaa anta an tu’dillanee, antal-‘haiyyul-ladhee laa yamootu, wal-jinnu wal-’insu ya-mootoon","ref":"Muslim: 2717"},{"id":731,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنَّا نَسْأَلُكَ مُوْجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ وَالْغَنِيْمَةَ مِنْ كُلِّ بِرٍّ وَالْفَوْزَ بِالْجَنَّةِ وَالنَّجَاةَ بِعَوْنِكَ مِنَ النَّارِ","tr":"Allaahumma inna nas'aluka mu-jibaati ra’hmatika, wa 'azaa'ima maghfiratika, was-salaamata min kulli ithmin, wal-ghanimata min kulli birrin, wal-fawza bil- jannati, wan najaata bi ‘awnika minan-naar","ref":"Hasan (Arnaut) . Al-Adhkar 1/340"},{"id":732,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّيْ وَانْقِطَاعِ عُمُرِيْ","tr":"Allaahummaj-‘al awsa’a rizqika ‘alayya ‘inda kibari sinni wan-qitaa’i ‘umuri","ref":"Sahih (Suyuti). Jami' as-Sagir: 1485"},{"id":734,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ","tr":"Allaahumma inni as'aluka min fadlika wa rahmatika fa innahu laa yamlikuhaa illaa anta","ref":"Sahih (Albani). Silsilatul Sahiha: 1543"},{"id":735,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْهَدْمِ وَأَعُوْذُ بِكَ مِنَ التَّرَدِّيْ وَأَعُوْذُ بِكَ مِنَ الْغَرَقِ وَالْحَرَقِ وَالْهَرَمِ وَأَعُوْذُ بِكَ أَنْ يَتَخَبَّطَنِيَ الشَّيْطَانُ عِنْدَ الْمَوْتِ وَأَعُوْذُ بِكَ أَنْ أَمُوْتَ فِي سَبِيْلِكَ مُدْبِرًا وَأَعُوْذُ بِكَ أَنْ أَمُوْتَ لَدِيْغًا","tr":"Allaahumma inni a‛oodhu bika minal-hadmi, wa a‛oodhu bika minat-taraddi, wa a‛oodhu bika minal-gharaqi, wal-‘haraqi wal-harami, Wa a‛oodhu bika an yata-khabbataniyash-shaitaanu ‛indal-mauti, wa a‛oodhu bika an amoota fee sabeelika mudbiran, wa a‛oodhu bika min an amoota la-deegha","ref":"Sahih. Abu Dawud: 1552"},{"id":736,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْجُوْعِ فَإِنَّهُ بِئْسَ الضَّجِيْعُ وَأَعُوْذُ بِكَ مِنَ الْخِيَانَةِ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ","tr":"Allaahumma inni a‛oodhu bika minal-joo‛i, fa-’innahu bi-’saddajee‛u, wa a‛oodhu bika minal-khiyaanati, fa-innahaa bi’satil-bitaanah","ref":"Hasan. Abu Dawud: 1547"},{"id":737,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ وَأَعُوْذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ","tr":"Allaahumma inni a‛oodhu bika minal-faqri, wal-qillati, wadh-dhillati, wa a‛oodhu bika min an azlima aw uzlama","ref":"Sahih. Abu Dawud: 1544"},{"id":738,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ جَارِ السُّوْءِ فِي دَارِ الْمُقَامَةِ فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ","tr":"Allaahumma inni A‛oodhu bika min jaaris-su'i fi daril-muqaamah fa’inna jaaral-baadiyati yata’hawwal","ref":"Hasan (Albani). Sahihul Jami: 1290"},{"id":739,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَقَلْبٍ لَا يَخْشَعُ وَدُعَاءٍ لَا يُسْمَعُ وَنَفْسٍ لَا تَشْبَعُ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ","tr":"Allaahumma inni A‛oodhu bika min 'ilmin laa yanfa'u, wa qalbin laa yakhsha'u, wa du'a'in laa yasma'u, wa nafsin laa tashba'u. Allaahumma inni A‛oodhu bika min ha'ula'il-arbae'","ref":"Sahih. Nasa'i: 5470"},{"id":740,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ يَوْمِ السُّوْءِ وَمِنْ لَيْلَةِ السُّوْءِ وَمِنْ سَاعَةِ السُّوْءِ وَمِنْ صَاحِبِ السُّوْءِ وَمِنْ جَارِ السُوْءِ فِي دَارِ الْمُقَامَةِ","tr":"Allaahumma inni A‛oodhu bika min yawmis-su’i, wa min laylatis-su’i, wa min sa’atis-su’i, wa min saahibis-su'i, wa min jaaris-su’i fi daaril-muqaamah","ref":"Hasan (Albani). Sahihul Jami: 1299"},{"id":742,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ فَقِّهْهُ فِي الدِّيْنِ","tr":"Allaahumma faqqih-hu fid deen","ref":"Bukhari: 143"},{"id":743,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ","tr":"Allaahumma inna nau'dhu bika min an nushrika bika shay'an na'lamuhu wa nastaghfiruka lima laa na'lamuh","ref":"Hasan Ligairihi (Albani). Sahih at-Targib: 36"},{"id":744,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ انْفَعْنِيْ بِمَا عَلَّمْتَنِيْ وَعَلِّمْنِيْ مَا يَنْفَعُنِيْ وَارْزُقْنِيْ عِلْمًا تَنْفَعُنِيْ بِهِ","tr":"Allaahumman fa'ni bimaa allamtani wa allimni maa yanfauni war-zuqni ilman tanfauni bihi","ref":"Sahih. Silsilatus Sahihah: 3151, Tirmidhi: 3599"},{"id":746,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوْبِيْ إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","tr":"Allaahumma inni as'aluka yaa Allahu! Bi'annakal-Waahidul-'Ahadus-Samadul-ladhi lam yalid wa lam yoolad, wa lam yakun lahu kufuwan 'Ahad, 'an taghfirali dhunubi, 'innaka 'Antal-Ghafoorur-Raheem","ref":"Sahih. An-Nasa'i: 1301"},{"id":747,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيْعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ","tr":"Allaahumma inni as'aluka bi-anna lakal-hamdu, laa ilaaha illaa antal-mannaanu badi'us-samawaati wal-ardi, yaa dhal-jalaali wal-ikram! Yaa ‘hayyu yaa qayyum! Inni as'aluka","ref":"Sahih. An-Nasa'i: 1300"},{"id":748,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَّنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ اَلَّذِي لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ","tr":"Allaahumma 'innee 'as'aluka bi'anni 'ash-hadu 'annaka 'AntAllahu laa 'ilaaha 'illaa 'Antal-'Ahadus-Samadul-ladhi lam yalid wa lam yoolad wa lam yakun lahu kufuwan 'Ahad","ref":"Sahih. Abu Dawud: 1493"},{"id":749,"cat":"duas-of-hadith","sub":112,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ","tr":"Rabbighfirli wa tub `alayya innaka Antat-Tawwabur-Rahim","ref":"Sahih. Abu Dawud: 1516"},{"id":750,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِيْ وَتَوَفَّنِيْ إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي اَللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ وأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ وَأَسْأْلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ اَللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ","tr":"Allaahumma bi 'ilmikal-ghaiba wa qudratika 'alal-khalqi a’hyini maa 'alimtal-‘hayaata khairan li, wa tawaffani idhaa 'alimtal-wafata khairan li. Allaahumma wa as'aluka khashyataka fil-ghaibi wash-shahaadati wa as'aluka kalimatal-haqqi fir-ridaa wal ghadabi, wa as'alukal-qasda fil faqri wal-ghinaa, wa as'aluka na'iman laa yanfadu wa as'aluka qurrata ‘ainin laa tanqati'u wa as'alukar-ridaa ba'dal-qadaa'i, wa as'aluka bardal 'aishi ba'dal-mawti, wa as'aluka ladh dhatan-nazari ilaa wajhika wash-shawqa ilaa liqaa'ika fi ghayri darraa'a mudirratin, wala fitnatin mudillatin, Allaahumma zayyinnaa bizinatil-imani waj'alna hudaatam muhtadin","ref":"Sahih. Nasa'i: 1305"},{"id":751,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ ارْزُقْنِيْ حُبَّكَ وَحُبَّ مَنْ يَنْفَعُنِيْ حُبُّهُ عِنْدَكَ اَللَّهُمَّ مَا رَزَقْتَنِيْ مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُحِبُّ اَللَّهُمَّ وَمَا زَوَيْتَ عَنِّيْ مِمَّا أُحِبُّ فَاجْعَلْهُ لِي فَرَاغًا فِيمَا تُحِبُّ","tr":"Allaahummar-zuqni ‘hubbuka, wa ‘hubba man yanfa`uni ‘hubbuhu ‘indaka. Allaahumma maa razaqtani mimmaa u’hibbu faj’alhu quwwatan li fimaa tu’hibbu. Allaahumma wa maa zawaita ‘anni mimmaa u’hibbu faj’alhu faraaghan li fimaa tu’hibbu","ref":"Hasan (Ibn Hajar). Takhrij Mishkat: 3/31"},{"id":752,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ طَهِّرْنِيْ مِنَ الذُّنُوبِ وَالْخَطَايَا اَللَّهُمَّ نَقِّنِيْ مِنْهَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ اَللَّهُمَّ طَهِّرْنِيْ بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ","tr":"Allaahumma tahhirni minadh-dhunubi wal-khataayaa. Allaahumma naqqini minhaa kamaa yunaqqath thawbul-abyadu minad-danasi, Allaahumma tahhirni bith-thalji wal-barad wal-maa'i al-baarid","ref":"Sahih. An-Nasa'i: 402"},{"id":753,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَسُوْءِ الْعُمُرِ وَفِتْنَةِ الصَّدْرِ وَعَذَابِ الْقَبْرِ","tr":"Allaahumma inni A‛oodhu bika minal-jubni, wal-bukhli, wa suw'il-'umuri, wa fitnatis-sadri wa 'adhaabil qabr","ref":"Sahih. Abu Dawud: 1376"},{"id":754,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ رَبَّ جِبْرَائِيْلَ وَمِيْكَائِيْلَ ورَبَّ إِسْرَافِيلَ أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ وَمِنْ عَذَابِ الْقَبْرِ","tr":"Allaahumma rab-ba jibraa’eel wa meekaa’eel, wa rab-ba israafeel, a‛oodhu bika min ‘harrin naar, wa min ‛adhaabil qabr","ref":"Sahih. Nasa'i: 5519"},{"id":755,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ وَأَسْأَلُكَ أَنْ تَعْزِمَ لِي عَلَى رُشْدِ أَمْرِيْ","tr":"Allahumma inni A‛oodhu bika min sharri nafsi wa ‘as’aluka an ta’zima li ‘alaa rushdi ‘amri","ref":"Sahih (Al Wadi). Sahihul Musnad: 322"},{"id":756,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اغْفِرْ لِي مَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَخْطَأْتُ وَمَا تَعَمَّدْتُ وَمَا عَلِمْتُ وَمَا جَهِلْتُ","tr":"Allaahummagfirli maa asrartu wa maa a’alantu wa maa akhtaa’-tu wa maa ta’ammadtu wa maa ‘alimtu wa maa jahiltu","ref":"Sahih (Ibn al-Qayyim). Al Wabilus Sayyib: P. 199"},{"id":758,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ فَالِقَ الْحَبِّ وَالنَّوَى وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيْلِ وَالْفُرْقَانِ أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","tr":"Allaahumma Rabbas-samawaati wa Rabbal ardi, wa Rabbal-'Arshil-'Adheem, Rabbanaa wa Rabba kulli shay 'in, faaliqal-habbi wannawaa, wa munzilat-Tawraati wal-'Injeeli, wal-Furqaan, 'a'oodhu bika min sharri kulli shay'in 'Anta 'aakhidhun binaasiyatihi. Allaahumma 'Antal-'Awwalu falaysa qablaka shay'un, wa 'Antal-'Aakhiru falaysa ba'daka shay'un, wa 'Antadh-Dhaahiru falaysa fawqaka shay'un, wa 'Antal-Baatinu falaysa doonaka shay'un, iqdhi 'annad-dayna wa 'aghninaa minal-faqr","ref":"Muslim: 2713"},{"id":759,"cat":"duas-of-hadith","sub":112,"ar":"رَبَّنَا أَصْلِحْ بَيْنَنَا وَاهْدِنَا سَبِيلَ الْإِسْلَامِ وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ وَاصْرِفْ عَنَّا الْفَوَاحِشَ مَا ظَهْرَ مِنْهَا وَمَا بَطَنَ وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ وَاجْعَلْنَا شَاكِرِينَ لِنِعْمَتِكَ مُثْنِينَ بِهَا قَائِلِينَ بِهَا وَأَتْمِمْهَا عَلَيْنَا","tr":"Rabbanaa aslih baynanaa wahdinaa sabiilal islaam, wa najjinaa minadh dhulumaati ilaannur wasrif ‘annaal fawaa’hisha maa dhahraa minhaa wa maa batana wa baarik lanaa fii asmaa-’inaa wa absaarinaa wa quluubinaa wa azwaajinaa wa dhurriyyaatinaa wa tub ‘alainaa innaka antat tawwabur rahiim waj’alnaa shaakiriinaa lini’matika muth niina bihaa qaa-iliina bihaa wa atmimhaa ‘alainaa","ref":"Sahih. Sahih Adabul Mufrad: 630"},{"id":760,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ وَخَيْرَ الدُّعَاءِ وَخَيْرَ النَّجَاحِ وَخَيْرَ الْعَمَلِ وَخَيْرَ الثَّوَابِ وَخَيْرَ الْحَيَاةِ وَخَيْرَ الْمَمَاتِ وَثَبِّتْنِيْ وَثَقِّل مَوَازِينِيْ وَحَقِّقْ إِيْمَانِيْ وَارْفَعْ دَرَجَاتِيْ وَتَقَبَّلْ صَلَاتِيْ وَاغْفِرْ خَطِيْئَتِيْ وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ اَللَّهُمَّ إِنِّي أَسْأَلُكَ فَوَاتِحَ الْخَيْرِ وَخَوَاتِمَهُ وَجَوَامِعَهُ وَأَوَّلَهُ وَآخِرَهُ وَظَاهِرَهُ وَبَاطِنَهُ وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا آتِيْ وَخَيْرَ مَا أَفْعَلُ وَخَيْرَ مَا أَعْمَلُ وَخَيْرَ مَا بَطَنَ وَخَيْرَ مَا ظَهَرَ وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ اَللَّهُمَّ إنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِيْ وَتَضَعَ وِزْرِيْ وَتُصْلِحَ أَمْرِيْ وَتُطَهِّرَ قَلْبِيْ وَتُحَصِّنَ فَرْجِيْ وَتُنَوِّرَ قَلْبِيْ وَتَغْفِرَ لِي ذَنْۢبِيْ وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ اَللَّهُمَّ إنِّي أَسْأَلُكَ أَنْ تُبَارِكَ لِي فِي نَفْسِيْ وَفِي سَمْعِيْ وَفِي بَصَرِيْ وَفِي رُوحِيْ وَفِي خَلْقِيْ وَفِي خُلُقِيْ وَفِي أَهْلِيْ وَفِي مَحْيَايَ وَفِي مَمَاتِيْ وَفِي عَمَلِيْ فَتَقَبَّلْ حَسَنَاتِيْ وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ","tr":"Allaahumma inni as’aluka khairal mas alati, wa khairad dua’a-i, wa khairan najaa’hi wa khairal ‘amali wa khairath thawaabi wa khairal ‘hayaati wa khairal mamaati wa thabbitni wa thaqqil mawaazinii wa haqqiq iimaani warfa’ darajaatii wa taqabbal salaatii waghfir khatii-atii wa as-alukad darajaatil ‘ulaa minal jannati. Allaahumma inni as-aluka fawati’hal khayri wa khawaatimahu, wa jawaami’ahu, wa awwalahu wa aakhirahu wa dhaahirahu wa batinahu waddarajaatil ‘ulaa minal jannati aamin. Allaahumma inni as-aluka khaira maa aatii wa khaira maa af’alu wa khaira maa a’malu wa khaira maa batana wa khaira maa dhahara wad darajaatil ‘ulaa minal jannati aamin. Allaahumma inni as-aluka an tarfa’a dhikrii wa tada’a wizrii wa tusli’ha amrii wa tutahhira qalbii wa tu’hassina farjii wa tunawwira qalbii wa taghfira lii dhambii wa as-alukad darajaatil ‘ulaa minal jannati aamin. Allaahumma inni as-aluka an tubaarika lii fii nafsii wa fii sam’ii wa fii basarii wa fi ruuhii wa fii khalqii wa fii khuluqi wa fi ahlii wa fii ma’hyaaya wa fii mamaati wa fii ‘amalii fataqabbal hasanaatii wa as-alukad darajaatil ‘ulaa minal jannati aamin","ref":"Sahih (Haisami). Majma Al-Jawwat: 10/108"},{"id":761,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ قَنِّعْنِيْ بِمَا رَزَقْتَنِيْ وَبَارِكْ لِي فِيهِ وَأَخْلِفْ عَلَيَّ كُلَّ غَائِبَةٍ لِي بِخَيْرٍ","tr":"Allaahumma qanni`ni bimaa razaqtani wa baarik lee feehi wa akhlif ‘alayya kulla ghaa'ibatin lee bikhayr","ref":"Hasan (Ibn Hajar). Futuhatur Rabbaniyyah: 4/383"},{"id":762,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ حَاسِبْنِيْ حِسَابًا يَسِيْرًا","tr":"Allaahumma haasibni hisaabay yasira","ref":"Bukhari: 6537"},{"id":764,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ إِيْمَانًا لَا يَرْتَدُّ وَنَعِيْمًا لَا يَنْفَدُ وَمُرَافَقَةَ نَبِيِّنَا مُحَمَّدٍ (صلى الله عليه وسلم) فِي أَعْلَى جَنَّةِ الْخُلْدِ","tr":"Allaahumma Inni As'aluka Imaanan Laa Yartaddu Wa Na'eeman Laa Yanfadu Wa Muraafaqata Nabyyinaa (ﷺ) Fee A'laa Jannatil-Khuld.","ref":"Hasan (Albani). Silsilatul Sahiha: 5/379"},{"id":765,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ أَلْهِمْنِيْ رُشْدِيْ وَأَعِذْنِيْ مِنْ شَرِّ نَفْسِيْ","tr":"Allaahumma alhimni rushdi, wa a-‘idhni min sharri nafsi","ref":"Hasan (Ibn Hajar). Takhrij Mishkat: 3/24"},{"id":766,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَغَلَبَةِ الْعَدُوِّ وَشَمَاتَةِ الْأَعْدَاءِ","tr":"Allaahumma inni A‛oodhu bika min ghalabatid-daini, wa ghalabatil-'aduwwi, wa shamaatatil-a'daa'i","ref":"Sahih. Nasa'i: 5487"},{"id":767,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَاهْدِنِيْ وَارْزُقْنِيْ وَعَافِنِيْ أَعُوْذُ بِاللَّهِ مِنْ ضِيْقِ الْمَقَامِ يَوْمَ الْقِيَامَةِ","tr":"Allaahummaghfir li, wahdini, warzuqni wa 'aafini. A‛oodhu billaahi min di'qil-maqaami yawmal-qiyaamah","ref":"Hasan Sahih. Nasa'i: 1617"},{"id":768,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ مَتِّعْنِيْ بِسَمْعِيْ وَبَصَرِيْ وَاجْعَلْهُمَا الْوَارِثَ مِنِّيْ وَانْصُرْنِيْ عَلَى عَدُوِّيْ وَأَرِنِيْ مِنْهُ ثَأْرِيْ","tr":"Allaahumma mati‛ni bi sam‛i wa basari waj-‛alhumal-waaritha minni, wan-surni 'alaa 'aduwwi wa-arini minhu bi tha’ri","ref":"Sahih. Adabul Mufrad: 650"},{"id":769,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِيْشَةً نَقِيَّةً وَمِيْتَةً سَوِيَّةً وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَضِحٍ","tr":"Allaahumma inni as'aluka ‘ishatan naqiyyatan, wa mitatan saweyyatan wa maraddan ghaira mukhzin wala fadi'hin","ref":"Sahih (Suyuti). Jami' as-Sagir: 1505"},{"id":770,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ اَللَّهُمَّ لَا قَابِضَ لِمَا بَسَطْتَ وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا مَانِعَ لِمَا أَعْطَيْتَ. اَللَّهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ اَللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ. اَللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْعَيْلَةِ وَالْأَمْنَ يَوْمَ الْحَرْبِ اَللَّهُمَّ عَائِذًا بِكَ مِنْ سُوءِ مَا أَعْطَيْتَنَا وَشَرِّ مَا مَنَعْتَ مِنَّا. اَللَّهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ وَاجْعَلْنَا مِنَ الرَّاشِدِينَ. اَللَّهُمَّ تَوَفَّنَا مُسْلِمِينَ وَأَحْيِنَا مُسْلِمِينَ وَأَلْحِقْنَا بِالصَّالِحِينَ غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ. اَللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِكَ وَيُكَذِّبُونَ رُسُلَكَ وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ. اَللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَهَ الْحَقِّ","tr":"Allaahumma lakal ‘hamdu kulluhu, Allaahumma laa qaabidha limaa basat-ta, wa laa muqarriba limaa baa-’adta wa laa mubaa-’ida limaa qrrabta wa laa mu’tii-a limaa mana’ta wa laa maani’aa limaa a’tayta. Allaahummabsut ‘alainaa min barakaatika wa ra’hmatika wa fadhlika wa rizqika. Allaahumma inni as-alukan na’iimal muqiimalladhi laa ya’hulu wa laa yazuulu. Allaahumma inni as-alukan na’iima yawmal ‘ailati wal amna yawmal ‘harbi, Allaahumma ‘aa-idhan bika min suu-i maa a’taitanaa wa sharri maa mana’ta minnaa. Allaahumma habbib ilainal iimaana wa zayyinhu fii qulubinaa wa karrih ilainaal kufra wal fusuuqa wal ‘isyaana, waj’alnaa minar rashidin. Allaahumma tawaffana muslimin wa ah’inaa muslimiin. Wa alhiqnaa bissaalihiina ghaira khazayaa wa laa maftuuniin. Allaahumma qaatilil kafaratalla-dhiinaa yasudduuna ‘an sabiilika wa yukazzibuna rusulaka waj’al ‘alaihim rijzaka wa ‘adhaabaka. Allaahumma qaatilil kafaratalla-dhina ootul kitaaba, ilaahal haqq","ref":"Sahih. Adabul Mufrad: 699"},{"id":771,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِيْ وَعَافِنِيْ وَارْزُقْنِيْ","tr":"Allaahumma-ghfir li warhamni wa 'aafini warzuqni","ref":"Sahih. Ibn Majah: 3845"},{"id":772,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ زِدْنَا وَلَا تَنْقُصْنَا وَأَكْرِمْنَا وَلَا تُهِنَّا وَأَعْطِنَا وَلَا تَحْرِمْنَا وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا وَأَرْضِنَا وَارْضَ عَنَّا","tr":"Allaahumma zidnaa wa laa tanqusnaa wa akrimnaa walaa tuhinnaa wa a'tinaa wa laa ta’hrimnaa wa a-thirnaa walaa tu'thir alaynaa wa ardinaa war-da ‘annaa","ref":"Hasan (Bagawi). Sharhus Sunnah: 3/154"},{"id":773,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ أَحْسَنْتَ خَلْقِيْ فَأَحْسِنْ خُلُقِيْ","tr":"Allaahumma a’hsanta khalqi fa a’hsin khuluqi","ref":"Sahih (Albani). Ahmad: 24392"},{"id":774,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ ثَبِّتْهُ وَاجْعَلْهُ هَادِيًا مَهْدِيًّا","tr":"Allaahumma thabbithu waj'alhu haadiyan mahdiyan","ref":"Bukhari: 4356"},{"id":776,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ رَبَّ مُحَمَّدٍ النَّبِيِّ اِغْفِرْ لِي ذَنْبِيْ وَأَذْهِبْ غَيْظَ قَلْبِيْ وَأَجِرْنِيْ مِنْ مُضِلاَّتِ الْفِتَنِ مَا أَحْيَيْتَنَا","tr":"Allaahumma rabba muhammadin nabiyyi ighfir li dhanbi wa adh'hib gahiza qalbi wa ajirni min mudhillatil fitani maa ahyaitanaa","ref":"Hasan (Haisami). Mazmauz yawaidah 10/27"},{"id":777,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ وَالْعَزِيْمَةَ عَلَى الرُّشْدِ وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَحُسْنَ عِبَادَتِكَ وَأَسْأَلُكَ قَلْبًا سَلِيْمًا وَلِسَانًا صَادِقًا وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ","tr":"Allaahumma inni as'aluka ath-thabbaata fil-amri wal-'azimata 'alar-rushdi wa as'aluka shukra ni'matika wa ‘husna 'ibaadatika wa as'aluka qalban saliman wa lisaanan sadiqan wa as'aluka min khairi maa ta'lamu wa A‛oodhu bika min sharri maa ta'lamu wa astaghfiruka limaa ta'lamu","ref":"Sahih Li Ghairihi. Takhrij Mishkat: 915"},{"id":778,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيةَ فِي الدُّنْيَا وَالْآخِرَةَ","tr":"Allaahumma 'innee 'as'alukal-'afwa wal 'aafiyah fid-dunyaa wal 'aakhirah","ref":"Sahih. Ibn Majah: 3871"},{"id":779,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُؤُ لَكَ بِنِعْمَتِكَ عَلَىَّ وَأَبُؤُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","tr":"Allaahumma 'Anta Rabbee laa 'ilaaha 'illaa 'Anta, khalaqtanee wa 'anaa 'abduka, wa 'anaa 'alaa 'ahdika wa wa'dika mas-tata'tu, 'a'oodhu bika min sharri maa sana'tu, 'aboo-'u laka bini'matika 'alayya, wa 'aboo-'u bidhanbee faghfir lee fa'innahu laa yaghfiruth-dhunooba 'illaa 'Anta","ref":"Bukhari: 6306"},{"id":780,"cat":"duas-of-hadith","sub":112,"ar":"أَسْتَغْفِرُ اللَّهَ وَأَتُوْبُ إِلَيْهِ","tr":"Astaghfirullaaha wa 'atoobu 'ilayhi","ref":"Bukhari: 6307"},{"id":781,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ","tr":"Allaahumma fa'ayyumaa mu'minin sababtuhu faj'al dhaalika lahu qurbatan 'ilayka yawmal-qiyaamah","ref":"Bukhari: 6361"},{"id":783,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ اِنِّي أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحُزْنِ وَالْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","tr":"Allaahumma, inni A‛oodhu bika minal hammi, wal-huzni, wal-'ajzi, wal-kasali, wal-jubni, wal-bukhli, wa dala'id-daini, wa ghalabatir-rijal","ref":"Bukhari: 2893"},{"id":923,"cat":"duas-of-hadith","sub":112,"ar":"اَللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ الآخِرَه فَاغْفِرْ لِلْمُهَاجِرِينَ وَالْأَنْصَارِ","tr":"Allahumma laa- ‘aisha illa- ‘aishul akhirah. fagfir lilmuhajirina wal ansaar","ref":"Muslim: 1805"},{"id":784,"cat":"duas-of-sahaba","sub":113,"ar":"إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ ٩ وَمَا جَعَلَهُ اللَّـهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِ قُلُوبُكُمْ ۚ وَمَا النَّصْرُ إِلَّا مِنْ عِندِ اللَّـهِ ۚ إِنَّ اللَّـهَ عَزِيزٌ حَكِيمٌ ١٠","tr":"Iz tastagheethoona Rabbakum fastajaaba lakum annee mumiddukum bi-alfim-minal-malaaa'ikati murdifeen. Wa maa ja'alahullaahu illaa bushraa wa litatmainna bihee quloobukum; wa man-nasru illaa min 'indillaah; innallaaha 'Azeezun Hakeem.","ref":"Surah Al-Anfal 8: 9-10"},{"id":785,"cat":"duas-of-sahaba","sub":113,"ar":"وَلَقَدْ نَصَرَكُمُ اللَّـهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ ۖ فَاتَّقُوا اللَّـهَ لَعَلَّكُمْ تَشْكُرُونَ ١٢٣ إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَاثَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُنزَلِينَ ١٢٤ بَلَىٰ ۚ إِن تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُم مِّن فَوْرِهِمْ هَـٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُسَوِّمِينَ ١٢٥ وَمَا جَعَلَهُ اللَّـهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِ ۗ وَمَا النَّصْرُ إِلَّا مِنْ عِندِ اللَّـهِ الْعَزِيزِ الْحَكِيمِ ١٢٦","tr":"Wa laqad nasarakumullaahu bi-Badrin wa antum azilla; fattaqullaaha la'allakum tashkuroon. Iz taqoolu lil-mu'mineena alan yakfiyakum ay-yumiddakum Rabbukum bithalaathati aalaafim-minal-malaaa'ikati munzaleen. Balaaa; in tasbiroo wa tattaqoo wa ya'tookum min fawrihim haazaa yumdidkum Rabbukum bikhamsati aalaafim-minal-malaaa'ikati musawwimeen. Wa maa ja'alahullaahu illaa bushraa lakum wa litatmainna quloobukum bih; wa man-nasru illaa min 'indillaahil-'Azeezil-Hakeem.","ref":"Surah Ali-Imran 3: 123-126"},{"id":786,"cat":"duas-of-sahaba","sub":113,"ar":"اَلَّذِينَ قَالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّـهُ وَنِعْمَ الْوَكِيلُ ١٧٣ فَانقَلَبُوا بِنِعْمَةٍ مِّنَ اللَّـهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوءٌ وَاتَّبَعُوا رِضْوَانَ اللَّـهِ ۗ وَاللَّـهُ ذُو فَضْلٍ عَظِيمٍ ١٧٤","tr":"Allazeena qaala lahumun-naasu innan-naasa qad jama'oo lakum fakhshawhum fazaadahum eemaanan wa qaaloo hasbunallaahu wa ni'mal-Wakeel. Fanqalaboo bini'matim-minallaahi wa fadlil-lam yamsashum sooo'un wattaba'oo ridwaanallaah; wallaahu zoo fadlin 'azeem.","ref":"Surah Ali-Imran 3: 173-174"},{"id":787,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ وَأَطِلْ حَيَاتَهُ وَاغْفِرْ لَهُ","tr":"Allaahumma akthir maalahu wa waladahu wa atil hayaatahu waghfir lahu","ref":"Bukhari: 6344"},{"id":789,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ اهْدِ أُمَّ أَبِي هُرَيْرَةَ","tr":"Allaahummahdi ummi abi Hurairah","ref":"Muslim: 2491"},{"id":790,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ حَبِّبْ عُبَيْدَكَ هَذَا وَأُمَّهُ إِلَى عِبَادِكَ الْمُؤْمِنِينَ وَحَبِّبْ إِلَيْهِمُ الْمُؤْمِنِيْنَ","tr":"Allaahumma habbib 'ubaidaka hadha wa ummahu ilaa 'ibadikal mu'minin, wa habbib ilayhimul mu'minin","ref":"Muslim: 2491"},{"id":792,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ بَارِكْ لَهُ فِي صَفْقَةِ يَمِيْنِهِ","tr":"Allaahumma baarik lahu fi safqati yaminihi","ref":"Baihaqi: 6/112, Ahmed: 1750"},{"id":793,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ عَلَيْكَ بِقُرَيْشٍ","tr":"Allaahumma 'Alaika bi Quraish","ref":"Muslim: 1794"},{"id":794,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ عَلَيْكَ بِأَبِي جَهْلِ بْنِ هِشَامٍ وَعُتْبَةَ بْنِ رَبِيْعَةَ وَشَيْبَةَ بْنِ رَبِيْعَةَ وَالْوَلِيْدِ بْنِ عُقْبَةَ وَأُمَيَّةَ بْنِ خَلَفٍ وَعُقْبَةَ بْنِ أَبِيْ مُعَيْطٍ","tr":"Allaahumma ‘Alaika bi abi jahl ibn Hisham, wa Utbath ibn Rabi'ah, wa Shaibah ibn Rabi'ah, wal Walid ibn Uqbah, wa Umayyah ibn Khalaf, wa Uqbah ibn abi Mu'ait","ref":"Muslim: 1794"},{"id":795,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ اصْرَعْهُ","tr":"Allahum-mas ra'hu","ref":"Bukhari: 3911"},{"id":796,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ أَنْجِزْ لِي مَا وَعَدْتَنِي اَللَّهُمَّ آتِ مَا وَعَدْتَنِي اَللَّهُمَّ إِنْ تُهْلِكْ هَذِهِ الْعِصَابَةَ مِنْ أَهْلِ الْإِسْلَامِ لَا تُعْبَدُ فِي الْأَرْضِ","tr":"Allaahumma anjiz li ma wa ‘adtani, Allaahumma aati ma wa ‘adtani, Allaahumma in tuhlik hadhi-hil 'ishabata min ahlil Islaami, la tu'badu fil ardi","ref":"Muslim: 1763"},{"id":797,"cat":"duas-of-sahaba","sub":113,"ar":"إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ","tr":"Iz tastagheethoona Rabbakum fastajaaba lakum annee mumiddukum bi-alfim-minal-malaaa'ikati murdifeen.","ref":"Muslim: 1763"},{"id":799,"cat":"duas-of-sahaba","sub":113,"ar":"يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا ۚ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا ٩ إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا ١٠ هُنَالِكَ ابْتُلِيَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالًا شَدِيدًا ١١","tr":"Am hasibtum an tadkhulul-Jannata wa lammaa ya'tikum-mathalul-lazeena khalaw min qablikum massathumul-ba'saaa'u wad-darraaa'u wa zulziloo hattaa yaqoolar-Rasoolu wallazeena aamanoo ma'ahoo mataa nasrullaah; alaaa inna nasrallaahi qareeb.","ref":"[1] Surah Al-Ahzab 33: 9-11 [2] Jadul Ma'ad: 3/274"},{"id":800,"cat":"duas-of-sahaba","sub":113,"ar":"اَللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ اِهْزِمِ الْأَحْزَابَ اَللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ","tr":"Allaahumma munzilal-kitaabi, saree'al-hisaabi, ihzimil-'ahzaaba, Allaahummah zimhum wa zalzilhum.","ref":"Muslim: 1742"},{"id":801,"cat":"duas-of-sahaba","sub":113,"ar":"شَاهَتِ الْوُجُوْهُ","tr":"Shaahatil wujooh","ref":"Muslim: 1777"},{"id":802,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ وَدَرَكِ الشَّقَاءِ وَسُوْءِ الْقَضَاءِ وَشَمَاتَةِ الْأَعْدَاءِ","tr":"Allaahumma innee ‘a’oodhu bika min jahdil-balaa’i, wa darakish-shaqaa’i, wa soo’il qadhaa’i, wa shamaatatil-‘a’adaa","ref":"Bukhari: 6347"},{"id":803,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ اَللَّهُمَّ آتِ نَفْسِيْ تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا.","tr":"Allaahumma innee a‛oodhu bika minal ‛ajzi wal-kasali, wal-jubni wal-bukhli, wal harami wa ‛adhaabil-qabr, Allaahumma aati nafsee taq-waahaa wa zakkihaa anta khairu man zakkaahaa anta wali-yuhaa wa mawlaahaa, Allaahumma inni a‛oodhu bika min ‛ilmin laa yanfa‛u, wa min qalbin laa yakh-sha‛u, wa min nafsin laa tashba‛u, wa min da‛wat-in laa yustajaabu lahaa","ref":"Muslim: 2722"},{"id":804,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيْعِ سَخَطِكَ","tr":"Allaahumma inni A‛oodhu bika min zawaali ni'matika, wa tahawwuli 'afiyatika, wa fujaa-ati niqmatika, wa jami'i sakhatik","ref":"Muslim: 2739"},{"id":805,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ ارْزُقْنِي حُبَّكَ وَحُبَّ مَنْ يَنْفَعُنِي حُبُّهُ عِنْدَكَ اَللَّهُمَّ مَا رَزَقْتَنِي مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُّحِبُّ اَللَّهُمَّ وَمَا زَوَيْتَ عَنِّي مِمَّا أُحِبُّ فَاجْعَلْهُ لِي فَرَاغًا فِيمَا تُحِبُّ","tr":"Allaahummar zuqni 'hubbaka, wa 'hubba man yanfa’uni 'hubbuhu ‘indaka. Allaahumma maa razaqtani mimma u'hibbu faaj’alhu quwwatan lee fimaa tu'hibbu. Allaahumma wa maa zawaita ‘anni mimma u'hibbu faaj’alhu lee faraaghan fimaa tu'hibbu","ref":"Hasan (Ibn Hazar). Takhrijul Masaabih: 3/31"},{"id":806,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ زِدْنَا وَلَا تَنْقُصْنَا وَأَكْرِمْنَا وَلَا تُهِنَّا وَأَعْطِنَا وَلَا تَحْرِمْنَا وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا وَأَرْضِنَا وَارْضَ عَنَّا","tr":"Allaahumma zidnaa wa laa tanqusnaa, wa akrimnaa wa laa tuhinnaa, wa aa-tinaa wa laa tahrimnaa, wa athir-naa wa laa tu-'thir ‘alaynaa, wa ardinaa warda ‘annaa","ref":"Sahih (Ahmad Shakir). Musnad Ahmad 1/124"},{"id":808,"cat":"masnun-duas","sub":114,"ar":"يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلَى دِيْنِكَ","tr":"Ya Muqallibal-qulubi, thabbit qalbi `alaa dinik","ref":"Sahih. Tirmidhi: 3522"},{"id":809,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُوْرِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ","tr":"Allaahumma a’hsin ‘aaqibatanaa fil-umuri kullihaa, wa ajirnaa min khizy-id dunyaa wa adhaabil akhirah","ref":"Sahih (Ahmad Shakir). 'Umdatut Tafsir: 1/162"},{"id":811,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ حْفَظْنِي بِالْإِسْلَامِ قَائِمًا وَاحْفَظْنِي بِالْإِسْلَامِ قَاعِدًا وَحْفَظْنِي بِالْإِسْلَامِ رَاقِدًا وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَسِدًا اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ وَأَعُوْذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ","tr":"Allaahumma’h fazni bil-islaami qaa'iman wa’h faazni bil-islaami qaa'idan wa’h fazni bil-islaami raaqidan walaa tushmit bi ‘aduwan walaa ‘hasidan. Allaahumma inni as-aluka min kulli khayrin khazaa-inuhu bi yadik, wa A‛oodhu bika min kulli sharrin khazaa-inuhu bi yadik","ref":"Hasan (Albani). Silsilatul Sahihah: 1540"},{"id":812,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَىَّ عِنْدَ كِبَرِ سِنِّي وَانْقِطَاعِ عُمُرِي","tr":"Allahumm-aj'al Awsa'a Rizqika Alayya inda kibari sinni wan qita-i umuri","ref":"Hasan (Haithami). Majmauz Zawayid: 10/185"},{"id":813,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَالْقَسْوَةِ وَالْغَفْلَةِ وَالْعَيْلَةِ وَالذِّلَّةِ وَالْمَسْكَنَةِ وَأَعُوْذُ بِكَ مِنَ الْفَقْرِ وَالْكُفْرِ وَالْفُسُوْقِ وَالشِّقَّاقِ وَالنِّفَقِ وَالسُّمْعَةِ والرِّيَاءِ وَأَعُوْذُ بِكَ مِنَ الصَّمَمِ وَالْبَكَمِ وَالْجُنُوْنِ وَالْجُذَامِ وَالْبَرَصِ وَسَيِّءِ الْأَسْقَامِ","tr":"Allaahumma inni A‛oodhu bika minal-'ajzi, wal-kasali, wal-jubni, wal-bukhli, wal-harami, wal qaswati wal ghaflati wal’aylati wadh-dhillati wal maskanati wa a’uudhu bika minal faqri wal kufri wal fusuuqi wash-shiqaaqi wan nifaaqi was-sum’ati war-riyaai wa A‛oodhu bika minas-samami wal bakami wal junuuni wal judhaami wal barasi wasayyi-il-asqaam","ref":"Sahih (Albani). Sahihul Jame: 1285"},{"id":814,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ يَوْمِ السُّوءِ وَمِنْ لَيْلَةِ السُّوءِ وَمِنْ سَاعَةِ السُّوءِ وَمِنْ صَاحِبِ السُّوءِ وَمِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ","tr":"Allaahumma innee A‛oodhu bika min yawmis-suu’i, wa min laylatis-suu’i, wa min saa‛atis-suu’i, wa min saa’hibis-suu’i, wa min jaaris-suu’i fee daaril-muqaamah","ref":"Hasan (Albani). Sahihul Jami: 1299"},{"id":815,"cat":"masnun-duas","sub":114,"ar":"اَللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي وَعَلِّمْنِي مَا يَنْفَعُنِي وَزِدْنِي عِلْمًا","tr":"Allahum-manfa'ni bima 'al-lamtani, wa 'al-limni maa yanfa'uni, wa zidni 'ilma","ref":"Sahih. Tirmidhi: 3599"},{"id":818,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ","tr":"Allaahumma 'innee 'a'oodhu bika 'an 'ushrika bika wa 'anaa 'a'lamu, wa 'astaghfiruka limaa laa 'a'lamu","ref":"Sahih. Adabul Mufrad: 716"},{"id":820,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ لَا طَيْرَ إِلَّا طَيْرُكَ وَلَا خَيْرَ إِلَّا خَيْرُكَ وَلَا إِلَهَ غَيْرُكَ","tr":"Allaahumma laa tayra 'illaa tayruka, wa laa khayra 'illaa khayruka, wa laa 'ilaaha ghayruka","ref":"[1] Sahih (Albani). Ahmad: 7045 [2] Abu Dawud: 3719, Ahmad: 9040. See also Al-Albani, Silsilatul-'Ahadith As-Sahihah 2/363, and it is with Abu Ash-Shaikh Al-Asfahani in 'Akhlaqun-Nabiyy, pg. 270."},{"id":825,"cat":"other-duas","sub":115,"ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيهِ","tr":"Astaghfirullaahal-'Adheemal-ladhee laa 'ilaaha 'illaa Huwal-Hayyul-Qayyoomu wa 'atoobu 'ilayhi","ref":"[1] Sahih. Abu Dawud 1517 [2] Sahih. Tirmidhi 3579 [3] Muslim 482 [4] Muslim 2702"},{"id":826,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا وَبَارِكْ لَنَا فِي مَدِينَتِنَا وَبَارِكْ لَنَا فِي صَاعِنَا وَبَارِكْ لَنَا فِي مُدِّنَا","tr":"Allaahumma baarik lanaa fee thamarinaa, wa baarik lanaa fee madeenatinaa wa baarik lanaa fee saa'inaa, wa baarik lanaa fee muddinaa","ref":"Muslim: 1373"},{"id":827,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ اِنِّي اَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْاَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ","tr":"Allaahumma inni a`udhu bika min munkaraatil-akhlaaqi wal-a`maali wal-ahwaa","ref":"Sahih. Tirmidhi: 3591"},{"id":828,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ اِنِّي اَعُوذُ بِكَ مِنْ شَرِّ سَمْعِيْ وَمِنْ شَرِّ بَصَرِيْ وَمِنْ شَرِّ لِسَانِيْ وَمِنْ شَرِّ قَلْبِيْ مِنْ شَرِّ مَنِيِّيْ","tr":"Allaahumma inni a`udhu bika min sharri sam`i wa min sharri basari, wa min sharri lisaani, wa min sharri qalbi, wa min sharri maniyyi","ref":"Sahih. Abu Dawud: 1551"},{"id":829,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ مُصَرِّفَ الْقُلُوْبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ","tr":"Allaahumma musarrifal-qulubi, sarrif qulubanaa 'alaa taa'atik","ref":"[1] Muslim : 2654 [2] Sahih (Albani). Tirmidhi: 2140"},{"id":831,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ حَسَّنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي","tr":"Allaahumma hassanta khalqi fa a'hsin khuluqi","ref":"Sahih (Albani). Musnad Ahmad: 5099"},{"id":835,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ","tr":"Allaahummakthir maa-lahu wa waladahu wa baarik lahu fiimaa a-'ataitahu","ref":"Bukhari: 6344"},{"id":838,"cat":"other-duas","sub":115,"ar":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ","tr":"Yaa Hayyu yaa Qayyoomu bira'hmatika 'astagheeth","ref":"Hasan. Tirmidhi: 3524"},{"id":839,"cat":"other-duas","sub":115,"ar":"اَلْحَمْدُ لِلَّهِ عَدَدَ مَا خَلَقَ وَالْحَمْدُ لِلَّهِ مِلْءَ مَا خَلَقَ وَالْحَمْدُ لِلَّهِ عَدَدَ مَا فِي الْأَرْضِ وَالسَّمَاءِ وَالْحَمْدُ لِلَّهِ مِلْءَ مَا فِي الْأَرْضِ وَالسَّمَاءِ وَالْحَمْدُ لِلَّهِ عَدَدَ مَا أَحْصَى كِتَابُهُ وَالْحَمْدُ لِلَّهِ عَدَدَ كُلِّ شَيْءٍ وَالْحَمْدُ لِلَّهِ مِلْءَ كُلِّ شَيْءٍ سُبْحَانَ لِلَّهِ عَدَدَ مَا خَلَقَ وَسُبْحَانَ لِلَّهِ مِلْءَ مَا خَلَقَ وَسُبْحَانَ لِلَّهِ عَدَدَ مَا فِي الْأَرْضِ وَالسَّمَاءِ وَسُبْحَانَ لِلَّهِ مِلْءَ مَا فِي الْأَرْضِ وَالسَّمَاءِ وَسُبْحَانَ لِلَّهِ عَدَدَ مَا أَحْصَى كِتَابُهُ وَسُبْحَانَ لِلَّهِ عَدَدَ كُلِّ شَيْءٍ وَسُبْحَانَ لِلَّهِ مِلْءَ كُلِّ شَيْءٍ","tr":"Alhamdulillahi 'Adada Ma Khalaqa, Walhamdulillahi Mil'a Ma Khalaqa, Walhamdulillahi 'Adada Ma fil Ardi Was Samayi, Walhamdulillahi Mil'a Ma fil Ardi Was Samayi, Walhamdullahi 'Adada Ma a’hsaa kitabuhu, Walhamdullahi 'Adada Kulli Shayin, Walhamdullahi Mil'a Kulli Shayin. Subhanallahi 'Adada Ma Khalaqa, Wa Subhanallahi Mil'a Ma Khalaqa, Wa Subhanallahi 'Adada Ma fil Ardi Was Samayi, Wa Subhanallahi Mil'a Ma fil Ardi Was Samayi, Wa Subhanallahi 'Adada Ma a’hsaa kitabuhu, Wa Subhanallahi 'Adada Kulli Shayin, Wa Subhanallahi Mil'a Kulli Shayin.","ref":"Sahih (Albani). Sahihul Jami: 2615"},{"id":925,"cat":"other-duas","sub":115,"ar":"اَللَّهُمَّ اغْفِرْ ذَۢنْبِي وَطَهِّرْ قَلْبِي وَحَصِّنْ فَرْجِي","tr":"Allaahummaghfir dham-bee wa tah-hir qalbee, wa hassin far-jee","ref":"Sahih (Albani). Musnad Ahmad: 22265"},{"id":841,"cat":"when-to-say-what","sub":116,"ar":"إِنْ شَاءَ اللَّهُ","tr":"inshaa'Allah","ref":"Sura Al Kahf: 23-24"},{"id":844,"cat":"when-to-say-what","sub":116,"ar":"اَلْحَمْدُ لِلَّهِ","tr":"Alhamdu lillaah","ref":"Ibn Majah: 3805"},{"id":845,"cat":"when-to-say-what","sub":116,"ar":"إِنَّا لِلَّهِ","tr":"Innaa lillaahi","ref":"Muslim: 2126"},{"id":846,"cat":"when-to-say-what","sub":116,"ar":"مَا شَاءَ ٱللَّهُ","tr":"ma sha Allah","ref":"Muslim: 3508"},{"id":847,"cat":"when-to-say-what","sub":116,"ar":"جَزَاكَ اللَّهُ خَيْرًا","tr":"JazaakAllahu khayran","ref":"[1] Bukhari: 336 [2] Sahih. Tirmidhi: 2035"},{"id":850,"cat":"when-to-say-what","sub":116,"ar":"أَسْتَغْفِرُ اللَّهَ","tr":"astaghfir-ullaah","ref":"Sura Muhammad: 19"},{"id":852,"cat":"when-to-say-what","sub":116,"ar":"نَعُوذُ بِاللَّهِ","tr":"NA‛oodhu billaah","ref":"Bukhari: 6362"},{"id":853,"cat":"when-to-say-what","sub":116,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ","tr":"Innaa lillaahi wa 'innaa 'ilayhi raaji'oon","ref":"Sura Bakara 2:156"},{"id":854,"cat":"when-to-say-what","sub":116,"ar":"آمِينْ","tr":"Aamin","ref":"Sahih Lee Ghairihi (Albani). Targib wat Tarhib, 2/66"},{"id":857,"cat":"when-to-say-what","sub":116,"ar":"وَاللَّهُ أَعْلَمُ","tr":"Wallahu a'lam","ref":"Bukhari: 5570"},{"id":858,"cat":"when-to-say-what","sub":116,"ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ","tr":"Bismillaahi wAllahu 'Akbar","ref":"Bukhari: 5565"},{"id":926,"cat":"eid","sub":117,"ar":"اَللَّهُ أَكْبرُ اَللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ وَلِلَّهِ الْحَمْدُ","tr":"Allaahu akbar, Allaahu akbar, laa ilaaha illallaahu wallaahu akbar, Allahu akbar wa lillaahil hamd.","ref":"Hassan (Albani). Musannaf: 5650"},{"id":927,"cat":"eid","sub":117,"ar":"اَللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ وَلِلَّهِ الْحَمْدُ اَللَّهُ أَكْبَرُ وَأَجَلُّ اَللَّهُ أَكْبَرُ عَلىَ مَا هَدَانَا","tr":"Allaahu akbar, Allaahu akbar, Allaahu akbar, wa lillaahil hamd, allaahu akbar wa ajall, allaahu akbar 'alaa maa hadaana.","ref":"Irwa'ul-Ghalil, Albani: 3/125"},{"id":928,"cat":"eid","sub":117,"ar":"اَللَّهُ أَكْبَرُ كَبِيْرًا اَللَّهُ أَكْبَرُ كَبِيْرًا اَللَّهُ أَكْبَرُ وَأَجَلُّ اَللَّهُ أَكْبَرُ وَلِلَّهِ الْحَمْدُ","tr":"Allaahu akbar kabira, Allaahu akbar kabira, Allaahu akbar wa ajall, Allaahu akbar, wa lillaahil hamd. [1]","ref":"[1] Irwa'ul-Ghalil, Albani: 3/126 [2] Bukhari 971 [3] As-ilatun wa ajbibatun fee salatil Eidain 31-32 p."},{"id":929,"cat":"eid","sub":117,"ar":"تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكَ","tr":"Taqabbalallahu minna wa minka","ref":"Hasan (Ibn Hajar al-Asqalani). Fathul Bari: 2/517"},{"id":941,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا","tr":"Rabbi zidnee 'ilmaa.","ref":"Surah Al-Baqara 2:286"},{"id":965,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا","tr":"Rabbanaa laa tahmil 'alainaa isran kamaa hamaltahoo 'alal-lazeena min qablinaa.","ref":"Surah Al-Baqara 2:286"},{"id":966,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","tr":"Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih; wa'fu 'annaa waghfir lanaa warhamnaa; Anta Mawlaanaa fansurnaa 'alal-qawmil-kaafireen.","ref":"Surah Al-Baqara 2:286"},{"id":968,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ ٩","tr":"Rabbanaaa innaka jaami'un-naasi Li-Yawmil-laa raiba feeh; innallaaha laa yukhliful-mee'aad.","ref":"Surah Ali-Imran 3:9"},{"id":972,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ١٩١","tr":"Rabbanaa maa khalaqta haazaa baatilan Subhaanaka faqinaa 'azaaban-Naar.","ref":"Surah Ali-Imran 3:191"},{"id":973,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ١٩٢","tr":"Rabbanaa innaka man tudkhilin-Naara faqad akhzaitahoo wa maa lizzaalimeena min ansaar.","ref":"Surah Ali-Imran 3:192"},{"id":974,"cat":"40-rabbana-duas","sub":118,"ar":"رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا","tr":"Rabbanaa innanaa sami'naa munaadiyan yunaadee lil-eemaani an aaminoo bi-Rabbikum fa-aamannaa.","ref":"Surah Ali-Imran 3:193"},{"id":975,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ١٩٣","tr":"Rabbanaa faghfir lanaa zunoobanaa wa kaffir 'annaa sayyi-aatinaa wa tawaffanaa ma'al-abraar.","ref":"Surah Ali-Imran 3:193"},{"id":976,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ١٩٤","tr":"Rabbanaa wa aatinaa maa wa'adtanaa 'alaa rusulika wa laa tukhzinaa Yawmal-Qiyaamah; innaka laa tukhliful-mee'aad.","ref":"Surah Ali-Imran 3:194"},{"id":983,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ ٨٥ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ ٨٦","tr":"Rabbanaa laa taj'alnaa fitnatal-lil-qawmiz-zaalimeen. Wa najjinaa birahmatika minal-qawmil-kaafireen.","ref":"Surah Yunus 10: 85-86"},{"id":984,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى اللَّهِ مِن شَيْءٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ ٣٨","tr":"Rabbanaaa innaka ta'lamu maa nukhfee wa maa nu'lin; wa maa yakhfaa 'alallaahi min shai'in fil-ardi wa laa fis-samaaa'.","ref":"Surah Ibrahim 14:38"},{"id":986,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ ٤١","tr":"Rabbanaa aghfir lee wa liwaalidayya wa lil-mu'mineena Yawma yaqoomul-hisaab.","ref":"Surah Ibrahim 14:41"},{"id":988,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَا أَوْ أَن يَطْغَىٰ ٤٥","tr":"Rabbanaa innanaa nakhaafu 'an yafruta 'alaynaa 'aw 'an yatghaa.","ref":"Surah Ta Ha 20:45"},{"id":992,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا لَغَفُورٌ شَكُورٌ ٣٤","tr":"Rabbanaa la-Ghafoorun Shakqoor.","ref":"Surah Al-Fatir 35:34"},{"id":994,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ٨ وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ٩","tr":"Rabbanaa wa adkhilhum jannaati 'adninil-latee wa'adtahum wa man salaha min aabaaa'ihim wa azwaajihim wa zurriyyaatihim; innaka Antal-'Azeezul-Hakeem. Wa qihimus-sayyi-aat; wa man taqis-sayyi-aati Yawma'izin faqad rahimtah; wa zaalika huwal-fawzul-'azeem.","ref":"Surah Ghafir 40:8-9"},{"id":995,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا","tr":"Rabbanagh-fir lanaa wa li-ikhwaaninallazeena sabaqoonaa bil-eemaani wa laa taj'al fee quloobinaa ghillal-lillazeena aamanoo.","ref":"Surah Hashr 59:10"},{"id":996,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ","tr":"Rabbanaaa innaka Ra'oofur-Raheem.","ref":"Surah Hashr 59:10"},{"id":997,"cat":"40-rabbana-duas","sub":118,"ar":"رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ ٤","tr":"Rabbanaa 'alaika tawakkalnaa wa ilaika anabnaa wa ilaikal-maseer.","ref":"Surah Mumtahina 60:4"},{"id":998,"cat":"40-rabbana-duas","sub":118,"ar":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا ۖ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ٥","tr":"Rabbanaa laa taj'alnaa fitnatal-lillazeena kafaroo waghfir lanaa Rabbanaa innaka Antal-'Azeezul-Hakeem.","ref":"Surah Mumtahina 60:5"}];
